INSERT INTO `pages` (`id`, `name`, `content`, `user_id`, `image`, `template`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Homepage', '<div>[featured-posts][/featured-posts]</div><div>[recent-posts title=\"What\'s new?\"][/recent-posts]</div><div>[featured-categories-posts title=\"Best for you\" category_id=\"\" enable_lazy_loading=\"yes\"][/featured-categories-posts]</div><div>[all-galleries limit=\"6\" title=\"Galleries\" enable_lazy_loading=\"yes\"][/all-galleries]</div>', 1, NULL, 'no-sidebar', NULL, 'published', '2024-10-13 17:05:05', '2024-10-13 17:05:05'),
(2, 'Blog', '---', 1, NULL, NULL, NULL, 'published', '2024-10-13 17:05:05', '2024-10-13 17:05:05'),
(3, 'Contact', '<p>Address: North Link Building, 10 Admiralty Street, 757695 Singapore</p><p>Hotline: 18006268</p><p>Email: contact@botble.com</p><p>[google-map]North Link Building, 10 Admiralty Street, 757695 Singapore[/google-map]</p><p>For the fastest reply, please use the contact form below.</p><p>[contact-form][/contact-form]</p>', 1, NULL, NULL, NULL, 'published', '2024-10-13 17:05:05', '2024-10-13 17:05:05'),
(4, 'Cookie Policy', '<h3>EU Cookie Consent</h3><p>To use this website we are using Cookies and collecting some Data. To be compliant with the EU GDPR we give you to choose if you allow us to use certain Cookies and to collect some Data.</p><h4>Essential Data</h4><p>The Essential Data is needed to run the Site you are visiting technically. You can not deactivate them.</p><p>- Session Cookie: PHP uses a Cookie to identify user sessions. Without this Cookie the Website is not working.</p><p>- XSRF-Token Cookie: Laravel automatically generates a CSRF \"token\" for each active user session managed by the application. This token is used to verify that the authenticated user is the one actually making the requests to the application.</p>', 1, NULL, NULL, NULL, 'published', '2024-10-13 17:05:05', '2024-10-13 17:05:05'),
(5, 'Galleries', '<div>[gallery title=\"Galleries\" enable_lazy_loading=\"yes\"][/gallery]</div>', 1, NULL, NULL, NULL, 'published', '2024-10-13 17:05:05', '2024-10-13 17:05:05'),
(6, 'সর্বশেষ', '<shortcode>[recent-posts background_color=\"#fff\" with_sidebar=\"yes\" enable_lazy_loading=\"yes\"][/recent-posts]</shortcode>', 3, NULL, 'default', '', 'published', '2025-07-04 04:25:44', '2025-07-05 09:38:52');
INSERT INTO `posts` (`id`, `name`, `description`, `content`, `status`, `author_id`, `author_type`, `is_featured`, `image`, `views`, `format_type`, `created_at`, `updated_at`) VALUES
(21, 'বাংলাদেশ থেকে কাপড়-পাট-সুতার পণ্য আমদানিতে নিষেধাজ্ঞা ভারতের', 'নিজেদের স্থলবন্দর দিয়ে বাংলাদেশের বোনা কাপড়, পাট ও সুতার পণ্য আমদানিতে নিষেধাজ্ঞা দিয়েছে ভারত। শুক্রবার (২৭ জুন) ভারতের বৈদেশিক বাণিজ্য অধিদপ্তরের মহাপরিচালক এক বিবৃতিতে এ তথ্য জানিয়েছেন।', '<p>এতে বলা হয়েছে, “ ভারত-বাংলাদেশ সীমান্তে স্থলবন্দর দিয়ে বাংলাদেশ থেকে কোনো পণ্য আমদানি হবে না। শুধুমাত্র নাহভা শেভা সমুদ্রবন্দর দিয়ে নির্দিষ্ট এসব পণ্য আমদানি করা যাবে। যারমধ্যে রয়েছে পাটজাত পণ্য, একাধিক ভাঁজের বোনা কাপড়, একক শণ সুতা, পাটের একক সুতা, ব্লিচ না করা পাটের বোনা কাপড়।” এরআগে গত মে মাসে নিজেদের স্থলবন্দর দিয়ে বাংলাদেশের তৈরি পোশাক আমদানিতে নিষেধাজ্ঞা দিয়েছিল ভারত। ওই সময় এই পণ্য শুধুমাত্র মহারাষ্ট্রের নহভা শেভা এবং কলকাতা বন্দর দিয়ে আমদানির সুযোগ রেখেছিল দেশটি। বাংলাদেশ ভারতে প্রায় ৭০০ মিলিয়ন ডলারের তৈরি পোশাক রপ্তানি করে। স্থলবন্দর দিয়ে এই পণ্য আমদানিতে নিষেধাজ্ঞা দেওয়ায় এই খাতে বিরূপ প্রভাব পড়ার শঙ্কা তৈরি হয়েছিল।</p><shortcode>[blog-posts paginate=\"2\" category_ids=\"2\" enable_lazy_loading=\"yes\"][/blog-posts]</shortcode><p>ভারতের বৈদেশিক বাণিজ্য অধিদপ্তর জানিয়েছে, বাংলাদেশ থেকে নেপাল ও ভুটানে যেসব পণ্য যাবে সেগুলোর ক্ষেত্রে এ নিষেধাজ্ঞা কার্যকর হবে না। কিন্তু এসব পণ্য পুনরায় রপ্তানি করা যাবে না।</p><p>সাবেক স্বৈরাচার প্রধানমন্ত্রী শেখ হাসিনা গত বছরের ৫ আগস্ট গণঅভ্যুথানের মুখে ভারতে পালিয়ে যান। এরপর থেকেই দেশটি বাংলাদেশের সঙ্গে ‘শত্রুভাবাপন্ন’ আচরণ শুরু করে। এছাড়া বাংলাদেশের বিরুদ্ধে সংখ্যালঘুদের ওপর নির্যাতনের মিথ্যা অভিযোগ ছাড়াও অন্যান্য আরও অভিযোগ আনে তারা।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, 'https://cdn.dhakapost.com/media/imgAll/BG/2025July/yunus-2-20250703204740.jpg', 95, NULL, '2025-06-27 12:09:31', '2025-07-05 10:38:54'),
(22, 'পারমাণবিক জ্বালানি নিরাপত্তায় যৌথ কনভেনশনে স্বাক্ষরের প্রস্তাব অনুমোদন', 'বৃহস্পতিবার (৩ জুলাই) মন্ত্রিপরিষদ বিভাগের এক সংবাদ বিজ্ঞপ্তিতে এ তথ্য জানানো হয়েছে।', '<p>বৃহস্পতিবার (৩ জুলাই) মন্ত্রিপরিষদ বিভাগের এক সংবাদ বিজ্ঞপ্তিতে এ তথ্য জানানো হয়েছে। এতে বলা হয়, পারমাণবিক জ্বালানি এবং তেজস্ক্রিয় বর্জ্য ব্যবস্থাপনার নিরাপত্তা নিশ্চিত করার লক্ষ্যে গৃহীত আন্তর্জাতিক চুক্তিতে বাংলাদেশের অংশগ্রহণের পদক্ষেপ হিসেবে, ১৯৯৭ সালের ৫ সেপ্টেম্বর আন্তর্জাতিক পরমাণু শক্তি সংস্থা (আইএইএ) কর্তৃক গৃহীত ব্যবহৃত পারমাণবিক জ্বালানি ব্যবস্থাপনা এবং তেজস্ক্রিয় বর্জ্য ব্যবস্থাপনার নিরাপত্তা সম্পর্কিত যৌথ কনভেনশন-এ স্বাক্ষর করার প্রস্তাব অনুমোদন করা হয়েছে। এর আগে সকালে প্রধান উপদেষ্টা প্রফেসর মুহাম্মদ ইউনূসের সভাপতিত্বে ঢাকায় তেজগাঁওয়ে তার কার্যালয়ে উপদেষ্টা পরিষদের বৈঠক অনুষ্ঠিত হয়।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, 'dmp2-20250703141656.jpg', 71, NULL, '2025-07-03 13:00:07', '2025-07-05 10:19:30'),
(23, 'ইরানের সঙ্গে সংঘাত কেবল কূটনৈতিকভাবে সমাধান করা উচিত : ট্রাম্পকে পুতিন', 'যুক্তরাষ্ট্রের প্রেসিডেন্ট ডোনাল্ড ট্রাম্পের সঙ্গে ঘণ্টাব্যাপী ফোনালাপ করেছেন রাশিয়ার প্রেসিডেন্ট ভ্লাদিমির পুতিন। বৃহস্পতিবার এ দুই রাষ্ট্রনেতার ফোনালাপে ইউক্রেন যুদ্ধ, ইরান-ইসরায়েল সংঘাতসহ বিশ্বের বিভিন্ন ইস্যুতে কথা হয়েছে।', '<p>রুশ নেতা ভ্লাদিমির পুতিন যুক্তরাষ্ট্রের প্রেসিডেন্ট ডোনাল্ড ট্রাম্পের সঙ্গে ফোনালাপে জোর দিয়ে বলেছেন, ইরানের সঙ্গে সংঘাতসহ মধ্যপ্রাচ্যের অন্যান্য সঙ্কট কেবল কূটনৈতিকভাবে সমাধান করা উচিত। ফোনালাপের পর ক্রেমলিনের উপদেষ্টা ইউরি উশাকভ সাংবাদিকদের বলেন, রাশিয়ার পক্ষ থেকে সব বিরোধপূর্ণ বিষয়, মতপার্থক্য ও সংঘাতমূলক পরিস্থিতি কেবল রাজনৈতিক ও কূটনৈতিক উপায়ে সমাধান করতে হবে বলে জোর দিয়ে বলা হয়েছে।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, 'https://cdn.dhakapost.com/media/imgAll/BG/2025July/trump-putin-phonecall-20250703225716.jpg', 123, NULL, '2025-07-03 13:07:49', '2025-07-05 10:35:51'),
(24, 'গাজার মানুষ নিরাপদে থাকুক, এটাই চাই : ট্রাম্প', 'যুক্তরাষ্ট্রের প্রেসিডেন্ট ডোনাল্ড ট্রাম্প বলেছেন, গাজার মানুষ নিরাপদে থাকুক, তিনি এটাই চান। এমনকি গাজার বাসিন্দারা নরকের ভেতর দিয়ে গেছেন বলেও মন্তব্য করেছেন তিনি।', '<p>শুক্রবার (৪ জুলাই) এক প্রতিবেদনে এই তথ্য জানিয়েছে বার্তাসংস্থা আনাদোলু। বার্তাসংস্থাটি বলছে, প্রেসিডেন্ট ডোনাল্ড ট্রাম্প বৃহস্পতিবার এক বক্তব্যে বলেন, তিনি চান গাজার মানুষ নিরাপদে থাকুক। তিনি সাংবাদিকদের বলেন, “আমি চাই গাজার মানুষ নিরাপদে থাকুক। এটা সবচেয়ে গুরুত্বপূর্ণ। ওরা সত্যিই নরকের ভেতর দিয়ে গেছে।”</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, 'https://cdn.dhakapost.com/media/imgAll/BG/2025July/trump-59-20250704091622.jpg', 55, NULL, '2025-07-03 21:35:54', '2025-07-04 03:48:11'),
(25, 'হাসপাতালে ভর্তি অভিনেত্রী স্বস্তিকা', 'ওপার বাংলার জনপ্রিয় অভিনেত্রী স্বস্তিকা দত্ত হঠাৎ অসুস্থ হয়ে হাসপাতালে ভর্তি হয়েছেন। \'ভানুমতী ভূতের হোটেল\' ছবির শুটিং চলাকালীন তীব্র ব্যথায় কাবু হয়ে পড়েন তিনি। তাৎক্ষণিকভাবে তাকে হাসপাতালে নেওয়া হয়।', '<p>এই ঘটনায় তার ভক্ত ও সহকর্মীদের মধ্যে উদ্বেগ ছড়িয়ে পড়েছে। অভিনেত্রী নিজেই তার সামাজিক যোগাযোগ মাধ্যমে এক পোস্টে নিজের অসুস্থতার কথা জানিয়েছেন। তিনি লিখেছেন, ‘আমি বুঝি, সব ঘটনার পিছনে কোনো কারণ থাকে।’</p><p>‘গতকাল আমি \'ভানুপ্রিয়া ভূতের হোটেল\' ছবির শুটিং করছিলাম। হঠাৎ অসহ্য যন্ত্রণা শুরু হয়। মনে হচ্ছিল, পৃথিবীর সবচেয়ে কঠিন যন্ত্রণা। সঙ্গে সঙ্গে আমাকে হাসপাতালে নিয়ে যাওয়া হয়।’</p><p>এদিকে ভারতীয় গণমাধ্যমকে তিনি বলেন, ‘সবচেয়ে কঠিন যন্ত্রণার সঙ্গে আমি লড়াই করছি। সমস্ত সহ-অভিনেতাদের সহযোগিতা করার জন্য ধন্যবাদ। এই ছবি আমার কাছে খুব বিশেষ।’</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 0, 'swastika-dutta-20250704093915.jpg', 47, NULL, '2025-07-03 23:59:27', '2025-07-05 10:34:08'),
(26, 'মুম্বাই চলে যাচ্ছেন দেব-রুক্মিণী, কিনছেন ফ্ল্যাট', 'দেব-রুক্মিণীকে নিয়ে ইন্ডাস্ট্রির অন্দরমহলে চর্চার অন্ত নেই। বিগত এক দশক ধরে একাধিকবার তাদের সম্পর্কের দুষ্টু-মিষ্টি মুহূর্তের সাক্ষী থেকেছে বহু শিরোনাম।', '<p>তবে সম্প্রতি নিন্দুকরা দাবি করেছিলেন, সুপারস্টার এই জুটির সম্পর্কে নাকি ফাঁটল ধরেছে। আর এই গুঞ্জনকে বুড়ো আঙুল দেখিয়ে দেব বলছেন, “গত ১২ বছর ধরে একটা সম্পর্কে রয়েছি, কোনওদিন সেটা নিয়ে কারও সঙ্গে আলোচনা করিনি, তাহলে আজ কেন উত্তর দিতে হবে? গোটা ইন্ডাস্ট্রি আমাদের সম্পর্ক নিয়ে যা খুশি বলতে পারে, তবে তার জন্য আমি কৈফিয়ত দেব না!”</p><shortcode>[featured-categories-posts with_sidebar=\"no\" background_color=\"#ecf0f1\" enable_lazy_loading=\"yes\"][/featured-categories-posts]</shortcode><p>শুধু তাই নয়, পাশাপাশি আরেকটি বোমা ফাটিয়েছেন টলিউড সুপারস্টার। জানালেন, রুক্মিণী মৈত্রর সঙ্গে তিনিও এবার মুম্বাইতে শিফট করার চেষ্টা করছেন।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 0, 'rukmini-dev-1-20250703102341.jpg', 95, NULL, '2025-07-04 00:10:06', '2025-07-05 10:34:37'),
(27, 'বিএনপির পাল্টা শক্তি হতে তৎপর ইসলামি দলগুলো', 'ত্রয়োদশ জাতীয় সংসদ নির্বাচন সামনে রেখে বিএনপির বিপরীতে ইসলামপন্থী দলগুলোর মধ্যে একটা ‘সমঝোতায়’ যাওয়ার তৎপরতা চলছে। সব আসনে একক প্রার্থী দেওয়া এবং ভোটের প্রতিদ্বন্দ্বিতায় বিএনপির বিকল্প শক্তি হিসেবে দাঁড়ানোর লক্ষ্যে জামায়াতে ইসলামী ও ইসলামী আন্দোলনের পাশাপাশি আরও কিছু দল সক্রিয় রয়েছে।', '<p><strong>ত্রয়োদশ জাতীয় সংসদ নির্বাচন সামনে রেখে বিএনপির বিপরীতে ইসলামপন্থী দলগুলোর মধ্যে একটা ‘সমঝোতায়’ যাওয়ার তৎপরতা চলছে। সব আসনে একক প্রার্থী দেওয়া এবং ভোটের প্রতিদ্বন্দ্বিতায় বিএনপির বিকল্প শক্তি হিসেবে দাঁড়ানোর লক্ষ্যে জামায়াতে ইসলামী ও ইসলামী আন্দোলনের পাশাপাশি আরও কিছু দল সক্রিয় রয়েছে।</strong></p><p>তবে এই ‘সমঝোতা’ উদ্যোগকে এখনই জোট বলতে চাইছে না সংশ্লিষ্ট দলগুলো। সংশ্লিষ্ট সূত্রগুলো বলছে, এখনই জোট গঠনের কোনো ঘোষণা দেওয়া হবে না। নির্বাচনের তফসিল ঘোষণার পরে এটা একটা রূপ পেতে পারে।</p><shortcode>[recent-posts background_color=\"#fff\" with_sidebar=\"no\" enable_lazy_loading=\"yes\"][/recent-posts]</shortcode><p>এই প্রক্রিয়ার সঙ্গে জাতীয় নাগরিক পার্টি (এনসিপি) কতটা যুক্ত হবে, সেটা এখনো পরিষ্কার নয়। দলটির সঙ্গে সংস্কার–সংক্রান্ত বিভিন্ন বিষয়ে একধরনের মতৈক্য আছে ইসলামী আন্দোলন ও জামায়াতের সঙ্গে। ইসলামী আন্দোলন বাংলাদেশের মুখপাত্র গাজী আতাউর রহমান প্রথম আলোকে বলেন, ‘এনসিপিও নতুন বাংলাদেশের প্রত্যাশা নিয়ে এগোচ্ছে। তাদের সঙ্গে আমাদের বোঝাপড়া আছে। নতুন করে ফ্যাসিস্ট না আসুক, সেটি তারাও চায়। তাদের সঙ্গে ভালো যোগাযোগ আছে। হয়তো সামনেও যোগাযোগ হতে পারে।’</p><p><img src=\"http://localhost/hcpsc-web/public/storage/rukmini-dev-1-20250703102341.jpg\" alt=\"rukmini-dev-1-20250703102341\" width=\"1200\" height=\"675\" loading=\"lazy\"><br>&nbsp;</p><p>রাজনীতি-সংশ্লিষ্ট সূত্রগুলোর মতে, আগামী নির্বাচনে আওয়ামী লীগ অংশ নিতে পারবে না, এটা ধরে নিয়েই ইসলামপন্থী ও মধ্যপন্থী দলগুলো বিএনপির সঙ্গে প্রতিদ্বন্দ্বিতায় নামতে চাচ্ছে।</p><p>সংবিধানসহ গুরুত্বপূর্ণ কিছু সংস্কার প্রশ্নেও এসব দলের অধিকাংশের অবস্থান কাছাকাছি। জামায়াত, এনসিপি, ইসলামী আন্দোলন ও খেলাফত মজলিসের দুই অংশসহ অনেকগুলো দল সংসদের প্রস্তাবিত উচ্চকক্ষে আনুপাতিক প্রতিনিধিত্ব পদ্ধতিতে নির্বাচনের পক্ষে। এর মধ্যে জামায়াত, ইসলামী আন্দোলনসহ কিছু কিছু দল উচ্চকক্ষের মতো নিম্নকক্ষেও আনুপাতিক প্রতিনিধিত্ব পদ্ধতিতে নির্বাচন চায়। সাংবিধানিক প্রতিষ্ঠানে নিয়োগের ক্ষেত্রে প্রধানমন্ত্রীর একক ক্ষমতা কমাতে প্রস্তাবিত সাংবিধানিক ও সংবিধিবদ্ধ প্রতিষ্ঠানের নিয়োগ কমিটি গঠনের প্রস্তাবে এবং রাষ্ট্রপতি নির্বাচনের পদ্ধতি বদলাতেও তারা একমত। জামায়াত ও এনসিপি জাতীয় নির্বাচনের আগে স্থানীয় সরকার নির্বাচন চায়।</p><shortcode>[featured-categories-posts category_id=\"9\" with_sidebar=\"no\" background_color=\"#ecf0f1\" enable_lazy_loading=\"no\"][/featured-categories-posts]</shortcode><p>&nbsp;</p><p>অন্যদিকে বিএনপি এ প্রস্তাবগুলোর অনেকটির সঙ্গে দ্বিমত পোষণ করেছে। বিএনপি মনে করে, নিম্নকক্ষের প্রাপ্ত আসনের ভিত্তিতে উচ্চকক্ষের আসন বণ্টনই উপযুক্ত। সংখ্যানুপাতিক পদ্ধতি জটিল। স্থানীয় সরকার নির্বাচন এখন সম্ভব নয়। পাশাপাশি সরকারপ্রধানের ক্ষমতা কমানো ও মেয়াদের বিষয়ে দলটি শর্ত দিয়েছে। তারা মনে করে সরকারপ্রধানের ক্ষমতা খর্ব হলে রাষ্ট্র পরিচালনায় সমস্যা হবে।</p><p>সংস্কার বিষয়ে বিএনপির সঙ্গে এই অবস্থানগত ব্যবধানও ইসলামপন্থী, এনসিপিসহ কিছু দলের মধ্যে পারস্পরিক বোঝাপড়ার ক্ষেত্র তৈরি করছে বলে মনে করা হচ্ছে।</p><blockquote><p>সংস্কার বিষয়ে বিএনপির সঙ্গে এই অবস্থানগত ব্যবধানও ইসলামপন্থী, এনসিপিসহ কিছু দলের মধ্যে পারস্পরিক বোঝাপড়ার ক্ষেত্র তৈরি করছে বলে মনে করা হচ্ছে।</p></blockquote><p>এর মধ্যে ইসলামী আন্দোলন সংস্কার, জুলাই হত্যাকাণ্ডের বিচার ও সংখ্যানুপাতিক পদ্ধতির (পিআর) নির্বাচনের দাবিতে গত শনিবার ঢাকায় যে মহাসমাবেশ করেছে তাতে জামায়াত ও এনসিপিসহ বিভিন্ন দলের নেতারা অংশ নেন। তবে বিএনপির কেউ ছিলেন না। তাঁদের আমন্ত্রণও জানানো হয়নি। ওই সমাবেশে অংশ নেওয়া দলগুলোর নির্বাচন ও সংস্কার—দুই বিষয়ে বিএনপির অবস্থানের বিপরীতে নিজেদের অবস্থান পরিষ্কার করছে। সমাবেশে ধর্মভিত্তিক কয়েকটি দলের নেতাদের বক্তব্যে নির্বাচনে জোটবদ্ধভাবে অংশ নেওয়ার কথা প্রকাশ পায়। এটাকে নির্বাচন সামনে রেখে ইসলামপন্থী দলগুলোর একমঞ্চে আসার প্রাক্‌-প্রস্তুতি হিসেবেও দেখা হচ্ছে।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 0, '7197ab50-265b-11f0-8c66-ebf25fc2cfefjpg.webp', 115, NULL, '2025-07-04 04:37:46', '2025-07-05 08:16:09'),
(28, 'চট্টগ্রামে যান্ত্রিক ত্রুটি নিয়ে রানওয়েতে আটকে পড়ে হজযাত্রীদের ফ্লাইট', 'সৌদি আরবের মদিনা থেকে আসা হজযাত্রীদের একটি ফ্লাইট যান্ত্রিক ত্রুটি নিয়ে চট্টগ্রাম শাহ আমানত আন্তর্জাতিক বিমানবন্দরের রানওয়েতে আটকা পড়েছে। এতে দুই ঘণ্টা রানওয়ে বন্ধ ছিল।', '<p><strong>সৌদি আরবের মদিনা থেকে আসা হজযাত্রীদের একটি ফ্লাইট যান্ত্রিক ত্রুটি নিয়ে চট্টগ্রাম শাহ আমানত আন্তর্জাতিক বিমানবন্দরের রানওয়েতে আটকা পড়েছে। এতে দুই ঘণ্টা রানওয়ে বন্ধ ছিল।</strong></p><p>শনিবার (৫ জুলাই) সকাল সাড়ে ৯টার দিকে বাংলাদেশ বিমানের ফ্লাইটটি (বিজি-১৩৮) অবতরণের পর এ ঘটনা ঘটে। ওই ফ্লাইটে ৩৭৮ জন হজযাত্রী ছিলেন।</p><p>বিষয়টি নিশ্চিত করে শাহ আমানত আন্তর্জাতিক বিমানবন্দরের জনসংযোগ কর্মকর্তা প্রকৌশলী মোহাম্মদ ইব্রাহীম খলিল বলেন, মদিনা থেকে হজ্জযাত্রী নিয়ে চট্টগ্রামে আসা বিমান বাংলাদেমের ফ্লাইট ল্যান্ড করার পর রানওয়ে-২৩ প্রান্তে এসে যান্ত্রিক ত্রুটিজনিত কারণে আটকা পড়ে। ত্রুটি সারিয়ে বিমানটিকে বেলা ১১টা ২০ মিনিটে রানওয়ে থেকে নিরাপদে সরিয়ে এপ্রোনে নিয়ে আসা হয়েছে।&nbsp;</p><shortcode>[featured-categories-posts with_sidebar=\"yes\" background_color=\"#ecf0f1\" enable_lazy_loading=\"yes\"][/featured-categories-posts]</shortcode><p>&nbsp;</p><p>তিনি বলেন, অনাকাঙ্ক্ষিত এই ইস্যুতে চট্টগ্রাম বিমানবন্দরের রানওয়ে প্রায় ২ ঘণ্টা বন্ধ ছিল। ফ্লাইটে ৩৭৮ জন হজযাত্রী ছিলেন।</p><p>এদিকে চট্টগ্রাম বিমানবন্দরের সহকারী সিকিউরিটি সুপারভাইজার আবদুল আলম এক বার্তায় জানান, বাংলাদেশ বিমানের ফ্লাইট নম্বর বিজি-১৩৮ মদিনা থেকে চট্টগ্রামে অবতরণ করার পরে রানওয়ের শেষ মাথা আটকে যায়। বাংলাদেশ বিমানের জিইসি টিম পুশ কার্ট দিয়ে সামনের চাকা টেনে ঠিক করে দিলে পরবর্তী সময়ে বিমান ইঞ্জিন স্টার্ট করে বে-তে চলে আসে। বর্তমানে চট্টগ্রাম বিমান বন্দরে উড্ডয়ন ও অবতরণ পুনরায় চালু করা হলো।</p><p>আরএমএন/এসএম</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, './biman-20250705122139.webp', 78, NULL, '2025-07-05 11:11:58', '2025-07-05 11:11:58'),
(29, 'এবার যেনতেন নির্বাচন মেনে নেওয়া হবে না : জামায়াত আমির', 'এবার আর যেনতেন নির্বাচন মেনে নেওয়া হবে না বলে মন্তব্য করেছেন জামায়াতে ইসলামীর আমির ডা. শফিকুর রহমান। তিনি বলেন, ১৪, ১৮ ও ২৪ মার্কা নির্বাচনের আলামত লক্ষ্য করা যাচ্ছে। যারা এ ধরনের অপকর্মের চিন্তা করছেন তাদের জন্য আমাদের স্পষ্ট বার্তা—মানুষ রক্ত দিয়ে পরিবর্তন এনেছে। আবার প্রয়োজনে রক্তের বিনিময়ে পরিবর্তনকে সফল করব। এক্ষেত্রে এ জাতি কাউকে ছাড় দেয়নি, আমরাও দেবো না।', '<p><strong>এবার আর যেনতেন নির্বাচন মেনে নেওয়া হবে না বলে মন্তব্য করেছেন জামায়াতে ইসলামীর আমির ডা. শফিকুর রহমান। তিনি বলেন, ১৪, ১৮ ও ২৪ মার্কা নির্বাচনের আলামত লক্ষ্য করা যাচ্ছে। যারা এ ধরনের অপকর্মের চিন্তা করছেন তাদের জন্য আমাদের স্পষ্ট বার্তা—মানুষ রক্ত দিয়ে পরিবর্তন এনেছে। আবার প্রয়োজনে রক্তের বিনিময়ে পরিবর্তনকে সফল করব। এক্ষেত্রে এ জাতি কাউকে ছাড় দেয়নি, আমরাও দেবো না।</strong></p><p>শনিবার (৫ জুলাই) সকালে ফেনী যাওয়ার পথে কুমিল্লার আলেখারচর বিশ্বরোডে এক পথসভায় এসব কথা বলেন তিনি।</p><p>ডা. শাফিকুর রহমান বলেন, ছাত্র, যুবক, শ্রমিক অতীতে যেমন বুক চিতিয়ে লড়াই করে নিজেদের অধিকার আদায়ের জন্য এগিয়ে গিয়েছিল, আগামীতেও সেই অধিকার আদায়ে সামনে এগিয়ে যেতে হবে। আমাদের লড়াই ফ্যাসিবাদীদের বিরুদ্ধে নয়, ফ্যাসিবাদের বিরুদ্ধে। এই ফ্যাসিবাদ পুরাতন হোক আর নতুন, আমাদের লড়াই চলবে। যতদিন ফ্যাসিবাদের অস্তিত্ব থাকবে, ততদিন আমাদের লড়াই চলবে।</p><shortcode>[featured-categories-posts with_sidebar=\"yes\" background_color=\"#ecf0f1\" enable_lazy_loading=\"no\"][/featured-categories-posts]</shortcode><p>স্বপ্নের বাংলাদেশ প্রতিষ্ঠার প্রত্যয় ব্যক্ত করে জামায়াতের আমির বলেন, কিশোর, তরুণ ও যুবকদের জন্য এমন এক দেশ রেখে যেতে চাই—যেন শান্তিতে তারা নিশ্বাস নিতে পারে। চাঁদাবাজমুক্ত, দখলবাজমুক্ত সমাজ গড়ে তুলতে আল্লাহর আইনের বিকল্প নেই। আমরা সকলকে আল্লাহর আইনের প্রতি আহ্বান জানাচ্ছি।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 0, './cumilla-jamayat-20250705113231.webp', 59, NULL, '2025-07-05 11:15:25', '2025-07-05 11:15:25'),
(30, 'রাঙ্গুনিয়ার আ.লীগ নেতা বায়েজিদ বোস্তামী থেকে আটক', 'চট্টগ্রাম মহানগরীর বায়েজিদ বোস্তামী থানা এলাকার অক্সিজেন মীনা বাজার এলাকা থেকে মো. আইয়ুব (৪৬) নামে এক আওয়ামী লীগ নেতাকে আটক করেছে র‌্যাপিড অ্যাকশন ব্যাটালিয়নের (র‍্যাব) সদস্যরা।', '<p>চট্টগ্রাম মহানগরীর বায়েজিদ বোস্তামী থানা এলাকার অক্সিজেন মীনা বাজার এলাকা থেকে মো. আইয়ুব (৪৬) নামে এক আওয়ামী লীগ নেতাকে আটক করেছে র‌্যাপিড অ্যাকশন ব্যাটালিয়নের (র‍্যাব) সদস্যরা।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 0, './rab-hospital-20250705113156.webp', 46, NULL, '2025-07-05 11:21:25', '2025-07-05 11:24:30'),
(31, 'হঠাৎ অস্থির চালের বাজার', 'বাংলাদেশের অন্যতম প্রধান খাদ্যপণ্য চাল। দেশের আপামর মানুষ প্রতিদিনের খাদ্যতালিকায় যে খাদ্যটি অবিচ্ছেদ্যভাবে গ্রহণ করে, তা হলো ভাত। কিন্তু সাম্প্রতিক সময়ের বাজার পরিস্থিতি দেখে মনে হচ্ছে, সাধারণ মানুষের সেই মৌলিক চাহিদাটিই আজ হুমকির মুখে পড়েছে। ভরা মৌসুমেও চালের দাম বেড়ে যাওয়ায় উদ্বিগ্ন হয়ে পড়েছেন সাধারণ ক্রেতা', '<p>বাংলাদেশের অন্যতম প্রধান খাদ্যপণ্য চাল। দেশের আপামর মানুষ প্রতিদিনের খাদ্যতালিকায় যে খাদ্যটি অবিচ্ছেদ্যভাবে গ্রহণ করে, তা হলো ভাত। কিন্তু সাম্প্রতিক সময়ের বাজার পরিস্থিতি দেখে মনে হচ্ছে, সাধারণ মানুষের সেই মৌলিক চাহিদাটিই আজ হুমকির মুখে পড়েছে। ভরা মৌসুমেও চালের দাম বেড়ে যাওয়ায় উদ্বিগ্ন হয়ে পড়েছেন সাধারণ ক্রেতা, বিশেষ করে নিম্নবিত্ত ও নিম্ন-মধ্যবিত্ত শ্রেণি। প্রতিবছর বোরো মৌসুমে নতুন চাল বাজারে আসে এবং তখন চালের দাম কিছুটা কমে যায়—এটাই ছিল স্বাভাবিক চিত্র। কিন্তু এবার সে ধারার ব্যতিক্রম দেখা গেছে। রাজধানীসহ সারা দেশের বাজারে চালের দাম কেজিপ্রতি ২ থেকে ৮ টাকা পর্যন্ত বেড়েছে। কোথাও কোথাও এই বৃদ্ধি ১০ থেকে ১৫ টাকা পর্যন্ত পৌঁছেছে। এটি নিঃসন্দেহে অস্বাভাবিক এবং উদ্বেগজনক। বিশেষজ্ঞরা বলছেন, এবার নতুন চাল বাজারে আসার পরও এই মূল্যবৃদ্ধি বাজার ব্যবস্থাপনায় বড় ধরনের ত্রুটি এবং ব্যবসায়ী কারসাজিরই প্রমাণ। চালের এমন দাম বৃদ্ধিতে সবচেয়ে বেশি কষ্টে পড়েছেন নিম্ন আয়ের মানুষ এবং শ্রমজীবী শ্রেণি। প্রতিদিনের ন্যূনতম খাবারের তালিকায়ও সংকট দেখা দিয়েছে তাদের মধ্যে। একজন রিকশাচালক জলিল মিয়া বলেন, “আমরা নিম্ন আয়ের মানুষ নিয়মিত মাছ-মাংস খেতে পারি না। চারটা ডাল-ভাত হলেই হয়। এখন সেই ভাতেই হাত দিল তারা। আমরা কি খেয়ে বাঁচবো বলেন?” এই কথাগুলোর মধ্য দিয়েই ফুটে ওঠে একজন সাধারণ নাগরিকের অসহায়ত্ব ও ক্ষোভ। চালের বাজারে মূল সমস্যা হিসেবে উঠে এসেছে একটি কথাই—সিন্ডিকেট। চালকল মালিক, পাইকারি ব্যবসায়ী ও কিছু কর্পোরেট মিল মালিকদের এক ধরনের অপারদর্শী সমন্বয়ের মাধ্যমে বাজারে কৃত্রিম সংকট তৈরি করে দাম বাড়িয়ে দেওয়া হচ্ছে বলে অভিযোগ রয়েছে। যাত্রাবাড়ীর চাল ব্যবসায়ী রহিম হাওলাদার বলেন, “মিল মালিকদের সিন্ডিকেটের কবলে চালের বাজার। তারা যেভাবে দাম বাড়ায়, আমাদের সে দামে কিনতে হয়। বাধ্য হয়ে আমরাও বেশি দামে বিক্রি করি।” এমন মন্তব্য থেকে স্পষ্ট বোঝা যায়, খুচরা বিক্রেতারাও অনেক ক্ষেত্রে সিন্ডিকেটের হাতে বন্দি। রাজধানীর শনিরআখড়ার বাজারে এখন খুচরা দরে মোটা চাল (২৮ চাল) বিক্রি হচ্ছে ৫৮ থেকে ৬৫ টাকা কেজিতে। জিরাশাইল বিক্রি হচ্ছে ৭৪ থেকে ৮০ টাকা, মিনিকেট ৭৬ থেকে ৮৪ টাকা এবং কাটারিভোগ ৭০ থেকে ৭৬ টাকা কেজি। অথচ কিছুদিন আগেই সরু চালের দাম ৭৫ টাকায় নেমে এসেছিল। মিলাররা দাবি করছেন, তারা বেশি দামে ধান কিনছেন বলে চালের দাম বাড়াতে বাধ্য হচ্ছেন। তবে বাজার বিশ্লেষকরা বলছেন, মূল সমস্যা হচ্ছে বাজারে সরকারের কার্যকর তদারকির অভাব এবং বড় ব্যবসায়ী গোষ্ঠীর একচেটিয়া নিয়ন্ত্রণ। খুচরা ও পাইকারি দোকানে লোক দেখানো অভিযান পরিচালনা করা হলেও মূল উৎস—মিল ও মোকামে কোনো কার্যকর নজরদারি নেই। ফলে ব্যবসায়ীরা মজুত নীতিমালার তোয়াক্কা না করে ধান ও চাল মজুত করে বাজারে কৃত্রিম ঘাটতির পরিস্থিতি তৈরি করছেন। এতে নিত্যপণ্যের বাজারে নেমেছে চরম অস্থিরতা, যার বড় অংশের ভার এসে পড়েছে সাধারণ জনগণের ঘাড়ে। কনজুমারস অ্যাসোসিয়েশন অব বাংলাদেশের (ক্যাব) ভাইস প্রেসিডেন্ট এস এম নাজের হোসাইন বলেন, “ভরা মৌসুমেও চালের দাম বেড়ে যাওয়া নজিরবিহীন। মোকাম এবং আড়তগুলোতে চাল মজুত থাকা সত্ত্বেও দাম বাড়ানো হচ্ছে। কৃষকের কাছ থেকে ধান কেনার পর মিলার ও কর্পোরেটরা অজুহাত খাড়া করে বাজার নিয়ন্ত্রণ করছে।” তিনি আরও বলেন, “সরকার মাঝে মাঝে খুচরা ও পাইকারি বাজারে তদারকি করে ঠিকই, কিন্তু মোকাম বা মিল পর্যায়ে কোনো নজরদারি করে না। ফলে সিন্ডিকেট কার্যত নিয়ন্ত্রণ করছে পুরো বাজার।” ভোক্তাদের অনেকেই অভিযোগ করছেন, সরকারের খাদ্য বিভাগ বা জেলা প্রশাসন চালের বাজার তদারকিতে কার্যকর ভূমিকা নিচ্ছে না। খাদ্য বিভাগের কর্মকর্তারা বলছেন, তাদের দায়িত্ব শুধুই চাল সংগ্রহ করা, বাজার মনিটরিং নয়। এতে করে অসাধু ব্যবসায়ীদের অপতৎপরতায় কোনো লাগাম টানা যাচ্ছে না। বাংলাদেশ সাধারণ নাগরিক সমাজের আহ্বায়ক মহিউদ্দিন আহমেদ বলেন, “আমরা আগের সরকারের সময়ও চালের সিন্ডিকেট নিয়ে প্রতিযোগিতা কমিশনে অভিযোগ করেছিলাম, মামলাও হয়েছে। কিন্তু আজও কোনো কার্যকর ব্যবস্থা নেওয়া হয়নি। অন্তর্বর্তী সরকারও এ বিষয়ে কোনো পদক্ষেপ নেয়নি। সরকার চাইলে বাজার নিয়ন্ত্রণ করতে পারে, কিন্তু করছে না। প্রতিযোগিতা কমিশনও নিষ্ক্রিয়। একটি গোষ্ঠী চালের বাজারের ৩২ শতাংশ নিয়ন্ত্রণ করছে—তাদের বিরুদ্ধে ব্যবস্থা নেওয়া দরকার।” এই পরিস্থিতিতে দেশের বিভিন্ন স্থানে চালের দামের অস্বাভাবিক বৃদ্ধির প্রতিবাদে জনসচেতনতা গড়ে উঠতে শুরু করেছে। ‘ভাতের পাতে স্বস্তি ফেরাও’ স্লোগানে চট্টগ্রামে নাগরিক সমাজ, খাদ্য নিরাপত্তা নেটওয়ার্ক (খানি), ক্যাব চট্টগ্রাম ও আইএসডিই বাংলাদেশসহ বিভিন্ন সংগঠন মানববন্ধন করেছে। তাঁরা সরকারের প্রতি আহ্বান জানিয়েছেন, বাজারে স্বচ্ছতা ফিরিয়ে আনতে দ্রুত পদক্ষেপ নিতে হবে। সরকারের পক্ষ থেকে যদিও টিসিবি ও খাদ্য অধিদপ্তরের মাধ্যমে স্বল্পদামে চাল বিক্রির উদ্যোগ আছে, তবে তা অত্যন্ত সীমিত পরিসরে। অধিকাংশ ভোক্তা এই সুবিধা থেকে বঞ্চিত হচ্ছেন। এই পরিস্থিতিতে দেশের খাদ্য নিরাপত্তা প্রশ্নের মুখোমুখি। যে দেশে কৃষক প্রতি বছর লাখ লাখ টন ধান ফলায়, সেই দেশে চালের জন্য সাধারণ মানুষকে হাহাকার করতে হবে—এমন চিত্র কোনোভাবেই গ্রহণযোগ্য নয়। বাজারে যদি চালের সংকট না থাকে, তাহলে দাম কেন বাড়ছে—এই প্রশ্নের উত্তর চাইছে জনগণ। বাস্তবতা হচ্ছে, চালের দাম এখন আর ফসল ফলনের ওপর নির্ভর করে না, বরং নিয়ন্ত্রণ করছে একটি প্রভাবশালী গোষ্ঠী। খাদ্য অধিদপ্তরের কাছে পর্যাপ্ত চাল মজুত থাকার পরও বাজারে এর সুফল সাধারণ মানুষ পাচ্ছে না। এর মানে হচ্ছে, সরকারের ভিতরে কিংবা বাইরের কোনো শক্তি এই প্রক্রিয়াকে প্রভাবিত করছে এবং বাজার ব্যবস্থাপনার ঘাটতির সুযোগ নিচ্ছে। এই অবস্থায় বাজার ব্যবস্থাপনায় যে সংস্কার প্রয়োজন, তা শুধু প্রশাসনিক উদ্যোগ নয়—রাজনৈতিক সদিচ্ছাও অপরিহার্য। সিন্ডিকেট ভাঙতে হলে সরকারকে রাজনৈতিক ও প্রশাসনিক উভয় স্তর থেকে কঠোর পদক্ষেপ নিতে হবে। নিয়মিত মনিটরিং, মজুতকারীদের বিরুদ্ধে শাস্তিমূলক ব্যবস্থা, মিল পর্যায়ে নজরদারি এবং বাজার ব্যবস্থার ডিজিটালায়ন ছাড়া এই সমস্যা নিরসন সম্ভব নয়। অন্যথায়, চালসহ অন্যান্য নিত্যপণ্যের বাজারেও একই ধারা অব্যাহত থাকবে, যা দেশের দরিদ্র জনগোষ্ঠীর জীবনকে আরও দুর্বিষহ করে তুলবে। একটি গণতান্ত্রিক ও জনকল্যাণমুখী রাষ্ট্রের জন্য এটা অবশ্যই গ্রহণযোগ্য নয়।</p><p>&nbsp;</p>', 'published', NULL, 'Botble\\Member\\Models\\Member', 1, './07.webp', 463, NULL, '2025-07-06 07:46:29', '2025-07-06 20:19:31'),
(32, 'চট্টগ্রাম বন্দর ও কাস্টমস: রফতানি-কনটেইনার  হ্যান্ডলিং-রাজস্ব আদায়ে রেকর্ড', 'নানা প্রতিকূলতা, রাজনৈতিক অস্থিরতা ও বৈশ্বিক অর্থনৈতিক অনিশ্চয়তার মধ্যেও ২০২৪-২৫ অর্থবছরে চট্টগ্রাম বন্দর দিয়ে আমদানি ও রফতানি উল্লেখযোগ্য হারে বৃদ্ধি পেয়েছে। কনটেইনার হ্যান্ডলিংয়ে নতুন রেকর্ড গড়ার পাশাপাশি পণ্য আমদানি-রফতানিতেও অভূতপূর্ব অগ্রগতি অর্জন করেছে। অপরদিকে কাস্টমস হাউস চলতি বছর রেকর্ড', '<p><br><strong>নিজস্ব প্রতিবেদক:</strong></p><p><br>নানা প্রতিকূলতা, রাজনৈতিক অস্থিরতা ও বৈশ্বিক অর্থনৈতিক অনিশ্চয়তার মধ্যেও ২০২৪-২৫ অর্থবছরে চট্টগ্রাম বন্দর দিয়ে আমদানি ও রফতানি উল্লেখযোগ্য হারে বৃদ্ধি পেয়েছে। কনটেইনার হ্যান্ডলিংয়ে নতুন রেকর্ড গড়ার পাশাপাশি পণ্য আমদানি-রফতানিতেও অভূতপূর্ব অগ্রগতি অর্জন করেছে। অপরদিকে কাস্টমস হাউস চলতি বছর রেকর্ড পরিমাণ রাজস্ব আদায় করেছে। যা দেশের অর্থনীতির জন্য আশাব্যঞ্জক বলছেন সংশ্লিষ্টরা।<br>ব্যবসায়ীদের মতে, বৈদেশিক মুদ্রার সংকট কমে আসা, এলসি নিষ্পত্তি প্রক্রিয়ার গতি বৃদ্ধি, ব্যাংকিং কার্যক্রমে স্থিতিশীলতা এবং বৈশ্বিক বাজারে তৈরি পোশাকসহ রফতানিমুখী পণ্যের চাহিদা বৃদ্ধি পাওয়ায় এ সাফল্য এসেছে।<br>চট্টগ্রাম বন্দর কর্তৃপক্ষ সূত্র জানিয়েছে, চট্টগ্রাম বন্দরের গত পাঁচ অর্থবছরের কনটেইনার ও কার্গো হ্যান্ডলিংয়ের তথ্যে দেখা গেছে, ২০২৪-২৫ অর্থবছরে হ্যান্ডলিং হয়েছে রেকর্ড ৩২ লাখ ৯৬ হাজার ৬৭ কন্টেইনার, ১৩ কোটি ৭ লাখ ২৪ হাজার ৭৮৩ মেট্রিক টন কার্গো। একই সময়ে চট্টগ্রাম বন্দরে ভিড়েছে ৪ হাজার ৭৭টি জাহাজ। ২০২৩-২৪ অর্থবছরে হ্যান্ডলিং হয় ৩১ লাখ ৬৮ হাজার ৬৯০ একক কন্টেইনার। একই সময়ে হ্যান্ডলিং হয় ১২ কোটি ৩২ লাখ ৪২ হাজার ৭৪৮ মেট্রিকটন কার্গো। জাহাজ আসে ৩ হাজার ৯৭১টি। ২০২২-২৩ অর্থবছরে হ্যান্ডলিং হয় ৩০ লাখ ৭ হাজার ৩৭৫ একক কন্টেইনার। ওই বছর ১১ কোটি ৮২ লাখ ৯৭ হাজার ৬৪৩ মেট্রিক টন কার্গো হ্যান্ডলিং হয়। জাহাজ আসে ৪ হাজার ২৫৩টি।<br>চট্টগ্রাম কাস্টম হাউস ২০২৪-২৫ অর্থবছরে রেকর্ড ৭৫ হাজার ৪৩২ কোটি টাকার রাজস্ব আদায় করেছে। ২০২৩-২৪ অর্থবছরে এর পরিমাণ ছিল ৬৮ হাজার ৭৫৫ কোটি ৭ লাখ টাকা। সে হিসাবে বছরের ব্যবধানে রাজস্ব আহরণ বেড়েছে ৬ হাজার ৬৭৬ কোটি ৩ লাখ টাকা বা ৯ দশমিক ৭১ শতাংশ। এর আগের বছর ২০২২-২৩ অর্থবছরে রাজস্ব আদায়ের পরিমাণ ছিল ৬১ হাজার ৩৫০ কোটি ৪৪ লাখ টাকা।<br>চট্টগ্রাম কাস্টম হাউসের মুখপাত্র ও ডেপুটি কমিশনার সাইদুল ইসলাম বলেন, ‘সদ্য বিদায়ী অর্থবছরে চট্টগ্রাম কাস্টমস ৭৫ হাজার ৪৩২ কোটি টাকার রাজস্ব আদায় করেছে। যা অতীতের যেকোনও সময়ের তুলনায় সর্বোচ্চ। তবে গেলো অর্থবছরটিতে রাজস্ব আদায়ের লক্ষ্যমাত্রা ছিল ৮০ হাজার ৪০২ কোটি টাকা।’<br>তিনি আরও বলেন, ‘বছরজুড়ে আমরা বারবার চ্যালেঞ্জের মুখে পড়েছি– ধর্মঘট, আন্দোলন, পরিবহন বন্ধ। তবু রাজস্ব আদায়ে আমরা ইতিবাচক ধারায় ছিলাম।’<br>চট্টগ্রাম বন্দরের ওপর চাপ কমাতে গড়ে উঠেছে ১৯টি বেসরকারি ডিপো। এসব ডিপো দেশের এই প্রধান &nbsp;সমুদ্রবন্দর দিয়ে রফতানি হওয়া পণ্যের প্রায় শতভাগ, ৩৮ ধরনের আমদানি পণ্য এবং খালি কনটেইনার হ্যান্ডলিং করে থাকে।<br>এ বিষয়ে ডিপো মালিকদের সংগঠন বাংলাদেশ ইনল্যান্ড কনটেইনার ডিপোস অ্যাসোসিয়েশন (বিকডা) সচিব রুহুল আমিন শিকদার বলেন, ‘গেল বছর রফতানিতে রেকর্ড গড়েছে। যা বিগত বছরগুলোর তুলনায় সর্বোচ্চ। বৈদেশিক মুদ্রার সংকট কমে আসা, এলসি নিষ্পত্তি প্রক্রিয়ার গতি বৃদ্ধি, ব্যাংকিং কার্যক্রমে স্থিতিশীলতা এবং বৈশ্বিক বাজারে তৈরি পোশাকসহ রফতানিমুখী পণ্যের চাহিদা বৃদ্ধি পাওয়ায় এ সাফল্য এসেছে।’<br>বিকডা’র তথ্য অনুযায়ী, ২০২৪-২৫ অর্থ বছরে বেসরকারি ডিপোগুলো থেকে বিশ্বের বিভিন্ন দেশে জাহাজের মাধ্যমে রফতানি পণ্য বোঝাই কনটেইনার গেছে ৭ লাখ ৭৭ হাজার ৯৯৪ একক। এর আগের বছর ২০২৩-২৪ অর্থবছরে গেছে ৬ লাখ ৭৮ হাজার ১৩৬ একক কনটেইনার। একইভাবে ২০২২-২৩ অর্থ বছরে চট্টগ্রাম বন্দর দিয়ে বিভিন্ন দেশে রফতানি পণ্য গেছে ৬ লাখ ৮৪ হাজার ৮৬২ একক কনটেইনার। চট্টগ্রাম বন্দর কর্তৃপক্ষের সচিব মো. ওমর ফারুক বলেন, ‘চট্টগ্রাম বন্দর এবার কনটেইনার হ্যান্ডলিংয়ে রেকর্ড গড়েছে। একইভাবে কার্গো পণ্য হ্যান্ডলিংও বেড়েছে অন্যান্য বছরের তুলনায়। এ সাফল্যের পেছনে রয়েছে নৌপরিবহন মন্ত্রণালয়ের উপদেষ্টার সরাসরি দিকনির্দেশনা, মন্ত্রণালয়ের সার্বিক সহযোগিতা, বন্দরের বোর্ড সদস্যদের তদারকি এবং কর্মকর্তা-কর্মচারীদের নিরলস পরিশ্রম ও আন্তরিকতা।’<br>তিনি আরও বলেন, ‘চট্টগ্রাম বন্দরের উন্নয়ন পরিকল্পনার অংশ হিসেবে চালু করা হয়েছে ই-গেট পাস, অটোমেটেড কনটেইনার অপারেটিং সিস্টেম, আধুনিক স্ক্যানিং ও নিরাপত্তা ব্যবস্থা। এইসব ব্যবস্থার ফলে বন্দরে পণ্য খালাস ও ডেলিভারির গতি বেড়েছে, কমেছে কাগজপত্রের জটিলতা। এ ছাড়াও বন্দর ব্যবহারকারীদের সময়মতো ডেলিভারি গ্রহণ, সংশ্লিষ্ট পক্ষগুলোর সঙ্গে সার্বক্ষণিক সমন্বয় এবং অংশীজনদের সহযোগিতাও কার্যক্রমকে গতিশীল করেছে। তবে অর্থবছরের শেষের দিকে এনবিআরের শাটডাউন কর্মসূচি না থাকলে কনটেইনার হ্যান্ডলিংয়ের সংখ্যা ৩৩ লাখ একক ছাড়িয়ে যেত বলে মনে করা হচ্ছে।’<br>তিনি জানান, চট্টগ্রাম কাস্টমস হাউস, বাণিজ্য মন্ত্রণালয় ও এনবিআরের মধ্যে সমন্বয়, পণ্য খালাসের সময় হ্রাস, আধুনিক প্রযুক্তির ব্যবহার এবং শ্রমিকদের দক্ষতা বৃদ্ধিও এ অর্জনের পেছনে গুরুত্বপূর্ণ ভূমিকা রেখেছে। পাশাপাশি বন্দরের ভেতরে ও বাইরে সড়ক যোগাযোগ ব্যবস্থার উন্নয়ন, রেল ও নৌপথে পণ্য পরিবহনের বিকল্প ব্যবস্থাপনা এ সাফল্যে সহায়ক হয়েছে।<br>এ প্রসঙ্গে বাংলাদেশ নন প্যাকার ফ্রোজেন ফুডস এক্সপোর্ট অ্যাসোসিয়েশনের সিনিয়র সহ-সভাপতি মাহবুব রানা বলেন, ‘ডলার সংকট, এলসি নিষ্পত্তি প্রক্রিয়ায় কিছুটা গতি বৃদ্ধিসহ দেশে দিন দিন ব্যবসাবান্ধব পরিবেশ গড়ে উঠছে। এ কারণে রফতানি দিন দিন বাড়ছে। এখন পর্যন্ত ব্যবসার প্রসারে যেসব সমস্যা আছে সেসব বাঁধা না কাটলে আগামীতে রফতানিতে বাধাগ্রস্ত হতে পারে।’&nbsp;<br>চট্টগ্রাম মেট্রোপলিটন চেম্বার অব কমার্স অ্যান্ড ইন্ডাস্ট্রির (সিএমসিসিআই) সহ-সভাপতি এএম মাহবুব চৌধুরী বলেন, ‘ডলার সংকট এখনও পুরোপুরি কাটেনি। গত অর্থবছরে অবরোধসহ নানা কারণে প্রায় দুই মাস বন্দর-কাস্টমস অচল ছিল। ওই সময় ব্যবসায়ীরা নির্দিষ্ট সময়ে পণ্য পাঠাতে না পেরে এবং ডেলিভারি নিতে না পেরে ক্ষতিগ্রস্ত হয়েছেন। এমনকি বন্দর থেকে সময়মতো পণ্য ডেভিলারি নিতে না পেরে অনেক ব্যবসায়ী চারগুণ বেশি জরিমানা গুনেছেন। যে কারণে ব্যবসায়ীরা এত ক্ষতিগ্রস্ত হয়েছেন। দেশে ব্যবসাবান্ধব পরিবেশ গড়তে সামগ্রিক প্রয়াস প্রয়োজন।’</p><p>দেশের আমদানি-রফতানি বাণিজ্যের প্রায় ৯২ শতাংশই হয় চট্টগ্রাম বন্দর দিয়ে। দেশের সমুদ্রবন্দর দিয়ে পরিবহন করা পণ্যবাহী কনটেইনারগুলোর প্রায় ৯৮ শতাংশ এ বন্দর দিয়ে পরিবহন করা হয়।<br>&nbsp;</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './06.webp', 45, NULL, '2025-07-06 07:54:32', '2025-07-06 07:54:32'),
(33, 'পবিত্র আশুরা আজ', 'আজ ১০ মহররম রবিবার। বিশ্বের মুসলমানদের জন্য অত্যন্ত তাৎপর্যপূর্ণ ও শোকাবহ একটি দিন। দিনটি অনেকের কাছে পবিত্র আশুরা নামেও পরিচিত।   আরবি ‘আশারা’ শব্দের অর্থ দশ।', '<p><br><br><strong>নিজস্ব প্রতিবেদক</strong></p><p><br>আজ ১০ মহররম রবিবার। বিশ্বের মুসলমানদের জন্য অত্যন্ত তাৎপর্যপূর্ণ ও শোকাবহ একটি দিন। দিনটি অনেকের কাছে পবিত্র আশুরা নামেও পরিচিত। &nbsp; আরবি ‘আশারা’ শব্দের অর্থ দশ।<br>আর আশুরা মানে দশম। আর মহররম অর্থ সম্মানিত বা পবিত্র। ইসলামী পরিভাষায়, হিজরি বর্ষপঞ্জির প্রথম মাস মহররমের ১০ তারিখকে ‘আশুরা’ বলে। সৃষ্টির শুরু থেকে মহররমের ১০ তারিখে অর্থাৎ পবিত্র আশুরার দিনে অনেক গুরুত্বপূর্ণ ঘটনা সংঘটিত হয়েছে।<br>হিজরি ৬১ সনের এই দিনে ফোরাত নদীর তীরে কারবালার প্রান্তরে মহানবী হজরত মুহাম্মদ (সা.)-এর দৌহিত্র ইমাম হোসাইন (রা.) ও তাঁর পরিবারের সদস্যরা শহীদ হয়েছিলেন। সত্য ও ন্যায় প্রতিষ্ঠার জন্য তাঁদের আত্মত্যাগ মানবতার ইতিহাসে সমুজ্জ্বল হয়ে আছে। বিশ্বের মুসলমানদের কাছে এই দিনটি একদিকে যেমন শোকের, তেমনি অন্যায় ও অত্যাচারের বিরুদ্ধে সোচ্চার হতে এবং সত্য ও সুন্দরের পথে চলতে প্রেরণা জোগায়।<br>তবে কারবালার বিয়োগান্ত ঘটনা ছাড়াও ইসলামের ইতিহাসে এই দিনে অনেক তাৎপর্যপূর্ণ ঘটনা ঘটেছে।<br>মুসলমানদের বিশ্বাস, হজরত মুসা (আ.) ফেরাউনের জুলুম থেকে এই দিনে পরিত্রাণ লাভ করেছিলেন তাঁর অনুসারীদের নিয়ে। ইব্রাহিম (আ.) নমরুদের অগ্নিকুণ্ড থেকে এই দিনে মুক্তি পান। এমন অনেক তাৎপর্যময় ঘটনা ঘটেছিল এই দিনে। মহান আল্লাহর রহমত ও ক্ষমা পাওয়ার আশায় ধর্মপ্রাণ মুসলমানরা নফল রোজা, নামাজ, দানখয়রাত ও জিকির-আসকারের মধ্য দিয়ে এই দিনটি পালন করেন।<br>পবিত্র আশুরা উপলক্ষে রাষ্ট্রপতি মো. সাহাবুদ্দিন ও প্রধানমন্ত্রী উপদেষ্ট ড,ইউনুছ পৃথক বাণী দিয়েছেন।</p><p>&nbsp;</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './01.webp', 41, NULL, '2025-07-06 07:57:31', '2025-07-06 07:57:31'),
(34, 'চট্টগ্রামে যুবদল কর্মীকে গুলি করে হত্যা', 'চট্টগ্রামের রাউজান উপজেলায় মো. সেলিম (৪২) নামে এক যুবদল কর্মীকে গুলি করে হত্যা করেছে দুর্বৃত্তরা। রোববার (৬ জুলাই) বেলা ১২টার দিকে উপজেলার কদলপুর ইউনিয়নের ইশান ভট্টের এ ঘটনা ঘটে।', '<p><br><br><strong>নিজস্ব প্রতিবেদক</strong><br><br>চট্টগ্রামের রাউজান উপজেলায় মো. সেলিম (৪২) নামে এক যুবদল কর্মীকে গুলি করে হত্যা করেছে দুর্বৃত্তরা। রোববার (৬ জুলাই) বেলা ১২টার দিকে উপজেলার কদলপুর ইউনিয়নের ইশান ভট্টের এ ঘটনা ঘটে।<br>ভুক্তভোগী সেলিম কদলপুর ৭ নম্বর ওয়ার্ড শমসের পাড়া এলাকার বাসিন্দা। তিনি বিএনপির ভাইস চেয়ারম্যান ও সাবেক সংসদ সদস্য গিয়াস উদ্দিন কাদের চৌধুরীর অনুসারী বলে জানা গেছে<br>স্থানীয়রা জানান, পরিবারের সঙ্গে বাড়িতে ফিরছিলেন সেলিম। হঠাৎ সিএনজিচালিত অটোরিকশাযোগে বোরকা পরে এসে দুর্বৃত্তরা সেলিমকে মাথায় গুলি করে চলে যান। পরে স্থানীয়রা তাকে উদ্ধার করে উপজেলা স্বাস্থ্য কমপ্লেক্সে নিয়ে গেলে কর্তব্যরত চিকিৎসক মৃত ঘোষণা করেন।</p><shortcode>[featured-categories-posts category_id=\"12\" with_sidebar=\"yes\" background_color=\"#ecf0f1\" enable_lazy_loading=\"yes\"][/featured-categories-posts]</shortcode><p>রাউজান থানার ভারপ্রাপ্ত কর্মকর্তা (ওসি) মনিরুল ইসলাম ভূঁইয়া বলেন, নিহতের মরদেহ ময়নাতদন্তের জন্য চট্টগ্রাম মেডিকেল কলেজ হাসপাতালে পাঠানো হচ্ছে। এ ঘটনায় তদন্ত সাপেক্ষে আইনগত ব্যবস্থা নেওয়া হচ্ছে।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, './26.webp', 89, NULL, '2025-07-06 19:00:40', '2025-07-06 20:23:22'),
(35, 'কারবালার শোক স্মরণে চট্টগ্রামে তাজিয়া মিছিল', 'পবিত্র আশুরা উপলক্ষ্যে কারবালার শহীদদের স্মরণে চট্টগ্রামে তাজিয়া মিছিল করেছে শিয়া সম্প্রদায়ের মানুষ। রোববার (৬ জুলাই) সকাল ১০টার দিকে নগরের সদরঘাট ইমামবাড়া থেকে শুরু হয়ে শোক মিছিলটি নগরের নিউমার্কেট, জিপিও, কোতোয়ালি মোড়, আলকরণ এলাকা ঘুরে পুনরায় ইমামবাড়ায় গিয়ে শেষ হয়।', '<p><br><br><strong>নিজস্ব প্রতিবেদক</strong><br><br>পবিত্র আশুরা উপলক্ষ্যে কারবালার শহীদদের স্মরণে চট্টগ্রামে তাজিয়া মিছিল করেছে শিয়া সম্প্রদায়ের মানুষ। রোববার (৬ জুলাই) সকাল ১০টার দিকে নগরের সদরঘাট ইমামবাড়া থেকে শুরু হয়ে শোক মিছিলটি নগরের নিউমার্কেট, জিপিও, কোতোয়ালি মোড়, আলকরণ এলাকা ঘুরে পুনরায় ইমামবাড়ায় গিয়ে শেষ হয়।</p><p>মিছিলে নেতৃত্ব দেন সদরঘাট ইমামবাড়ার পেশ ইমাম মাওলানা আমজাদ হোসেন। তিনি বলেন, ১৪০০ বছর আগের এই দিনেই মানবতার ইতিহাসে সবচেয়ে হৃদয়বিদারক ঘটনা ঘটেছিল। ইমাম হোসাইন (রা.) সত্য ও ন্যায়ের পথে শহীদ হয়েছিলেন। আমরা সেই আত্মত্যাগকে স্মরণ করছি।</p><p>তাজিয়া মিছিলে অংশ নেন শিয়া সম্প্রদায়ের নারী, পুরুষ, কিশোর-কিশোরী থেকে শুরু করে শিশু-বৃদ্ধরা। সবার পরনে ছিল শোকের প্রতীক কালো পোশাক। কেউ কেউ হাতে কালো পতাকা, পাঞ্জা ও ব্যানার নিয়ে ছিলেন।<br>মিছিলে আসা এহসান উদ্দিন বলেন, আমি গত ২০ বছর ধরে এই শোক মিছিলে অংশ নিচ্ছি। আমার সন্তানদেরও শেখাচ্ছি, কারবালার ঘটনা কেবল ধর্মীয় নয়, মানবতার শিক্ষা দেয়। হোসাইনের আত্মত্যাগ আমাদের চোখে আঙুল দিয়ে দেখিয়ে দেয় অন্যায়ের সঙ্গে আপস চলে না।</p><p>মিছিল ঘিরে নগরে ছিল নিরাপত্তা বলয়। চট্টগ্রাম মেট্রোপলিটন পুলিশের একাধিক টিম দায়িত্ব পালন করে। মিছিলে স্বেচ্ছাসেবকরাও নিরবচ্ছিন্নভাবে সহযোগিতা করেন।</p><p>ইমামবাড়ায় ফিরে দোয়া ও বিশেষ মোনাজাতের মাধ্যমে মিছিল শেষ হয়। কারবালার শহীদদের জন্য দোয়া চাওয়া হয় এবং জুলুমের বিরুদ্ধে অবস্থানের শপথ পুনর্ব্যক্ত করেন অংশগ্রহণকারীরা।</p>', 'published', NULL, 'Botble\\Member\\Models\\Member', 0, './27.webp', 56, NULL, '2025-07-06 19:05:47', '2025-07-06 20:18:27'),
(36, 'মব তৈরি করে জামায়াত নেতাকে পুলিশে দেওয়ার অভিযোগ', 'মেঘনা পেট্রোলিয়ামের সিবিএর সাধারণ সম্পাদক ও জামায়াত নেতা নওশেদ জামালকে গ্রেপ্তারের পর বিতর্ক শুরু হয়েছে। অভিযোগ উঠেছে চাঁদা না পেয়ে ‘মব’ তৈরি করে তাকে পুলিশের হাতে সোপর্দ করা হয়েছে।', '<p><br><strong>নিজস্ব প্রতিবেদক</strong><br><br>মেঘনা পেট্রোলিয়ামের সিবিএর সাধারণ সম্পাদক ও জামায়াত নেতা নওশেদ জামালকে গ্রেপ্তারের পর বিতর্ক শুরু হয়েছে। অভিযোগ উঠেছে চাঁদা না পেয়ে ‘মব’ তৈরি করে তাকে পুলিশের হাতে সোপর্দ করা হয়েছে।</p><p><br>শনিবার (৫ জুলাই) নগর পুলিশ কমিশনার বরাবরে একটি অভিযোগে দিয়েছেন নওশেদ জামালের স্ত্রী রিয়াজুল জান্নাত। এতে ঘটনার পেছনে বৈষম্যবিরোধী ছাত্র আন্দোলনের চট্টগ্রাম মহানগর কমিটির সদস্যসচিব নিজাম উদ্দিনকে দায়ী করছেন। সবশেষ শনিবার সন্ধ্যায় নিজামকে শোকজ করা হয়েছে।</p><p>সংগঠনটির কেন্দ্রীয় সভাপতি রশিদুল ইসলাম (রিফাত রশিদ) এবং সাধারণ সম্পাদক হাসান ইনামের নির্দেশনায় এবং সংগঠনের সাংগঠনিক সম্পাদক মুঈনুল ইসলামের সই করা নোটিশে বলা হয়, নিজাম উদ্দিন সংগঠনের নীতিমালা ও সাংগঠনিক শৃঙ্খলা পরিপন্থি কিছু কার্যকলাপে জড়িত হয়েছেন বলে অভিযোগ উঠেছে। কেন তাকে সংগঠন থেকে স্থায়ীভাবে বহিষ্কার করা হবে না- তা লিখিতভাবে ব্যাখ্যা দিতে আগামী তিন কর্মদিবস সময় দেওয়া হয়। নির্ধারিত সময়ের মধ্যে সন্তোষজনক জবাব না পেলে তার বিরুদ্ধে পরবর্তী ব্যবস্থা নেওয়া হবে।</p><p><br>এর আগে সিএমপি কমিশনারের বরাবরে জমা দেওয়া অভিযোগে রিয়াজুল জান্নাত অভিযোগ করেন, তার স্বামী নওশেদ জামাল চট্টগ্রামে মেঘনা পেট্রোলিয়াম এমপ্লয়িজ ইউনিয়নের সাধারণ সম্পাদক পদে থাকার পাশাপাশি জামায়াতে ইসলামীর একজন রুকন। তিনি জামায়াতের বাগমনিরাম দক্ষিণ সাংগঠিনিক ওয়ার্ডে সেক্রেটারি পদে দায়িত্ব পালন করে আসছেন। দীর্ঘদিন ধরে নিজাম উদ্দিন নামে এক ব্যক্তি তার স্বামীর কাছে চাঁদা দাবি করে আসছেন। দুই কোটি টাকা চাঁদা না দেওয়ায় তার স্বামীকে ফাঁসাতে নানা চক্রান্ত করা হয়।</p><p><br>অভিযোগে তিনি আরও উল্লেখ করেন, পতেঙ্গা ইস্টার্ন কেবলস লিমিটেডের ব্যবস্থাপনা পরিচালকের দপ্তরে বসে মোটা অঙ্কের টাকার বিনিময়ে তার স্বামীকে ফাঁসিয়ে দিতে চক্রান্ত করা হয়েছে। এর ধারাবাহিকতায় বৃহস্পতিবার সকাল সাড়ে ১০টায় আগ্রাবাদে মেঘনা পেট্রোলিয়াম অফিসের উদ্দেশ্যে যাওয়াকালে পথে ১০ থেকে ১৫ জন তার স্বামীকে ধরে মারধর ও মব তৈরি করে কোতোয়ালি থানা পুলিশের হাতে তুলে দেওয়া হয়েছে। পরে তড়িঘড়ি করে পুলিশ তাকে আদালতের মাধ্যমে কারাগারে পাঠায়। এই ঘটনায় কোতোয়ালি ওসি ও নিজাম উদ্দিন মোটা অঙ্কের টাকা লেনদেন করেছে।</p><p>অভিযোগের বিষয়ে বৈছাআর মহানগর কমিটির সদস্যসচিব নিজাম উদ্দিন বলেন, যিনি পুলিশের কাছে এই অভিযোগ করেছেন তিনি যদি আমার বিরুদ্ধে চাঁদা দাবির নূন্যতম কোনো প্রমাণ দেখাতে পারেন তাহলে আমি স্বেচ্ছায় নিজেকে আইনের হাতে সোপর্দ করব। প্রয়োজনে আমার নামে একাধিক মামলা হবে। আমার কোনো আপত্তি থাকবে না। আর উনি যদি কোনো প্রমাণ দেখাতে না পারেন তাহলে এমন অভিযোগের জন্য আমি আইনের আশ্রয় নেব। কারণ বৈষম্যবিরোধী ছাত্র আন্দোলনের মহানগরের একজন নেতা হিসেবে আমার সম্মানহানি অর্থ পুরো বৈষম্যবিরোধী প্লাটফর্মের সম্মানহানি করা হবে। এরজন্য আমি অবশ্যই আইনানুগ ব্যবস্থা নিতে বাধ্য থাকব। &nbsp;</p><p>সামাজিক যোগাযোগ মাধ্যম ফেসবুকে পোস্ট করে নিজাম উদ্দিন দাবি করেছেন তিনি চাঁদা চাননি। এ ছাড়া ওই নারীর উল্লিখিত ভিডিওটি পুরোনো। পোস্টে তিনি উল্লেখ করেন, ভিডিওটি পতেঙ্গা থানা এলাকার, তা–ও চার থেকে পাঁচ মাস আগের। অথচ ওই ব্যক্তি গ্রেপ্তার হয়েছেন মাত্র দুই দিন আগে কোতোয়ালি থানার একটি মামলায়। ভিডিওতে কোথাও টাকা দাবির তথ্য না থাকার পরও এটিকে চাঁদাবাজির তকমার ঢাল হিসেবেই ব্যবহার করছে একটি চক্র।</p><p>এ বিষয়ে নগর পুলিশের অতিরিক্ত উপকমিশনার (গণমাধ্যম) মাহমুদা বেগম বলেন, অভিযোগের বিষয়ে তদন্ত করে দেখা হবে।</p><p>এর আগে গত বৃহস্পতিবার (৩ জুলাই) নগরের ডবলমুরিং থানাধীন আগ্রাবাদ এলাকায় মেঘনা পেট্রোলিয়াম কার্যালয়ের সামনে থেকে নওশেদ আলমকে ধরে কোতোয়ালি থানা পুলিশের হাতে সোপর্দ করে বৈষম্যবিরোধী ছাত্র আন্দোলনের নেতা-কর্মীরা। পরে তাকে কোতোয়ালি থানায় দায়ের হওয়া একটি মামলায় গ্রেপ্তার দেখিয়ে কারাগারে পাঠানো হয়।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 0, './28.webp', 66, NULL, '2025-07-06 19:08:43', '2025-07-06 20:18:59'),
(37, 'শাহাদাতে কারবালা দিবস উপলক্ষ্যে চট্টগ্রামে সমাবেশ ও শোভাযাত্রা', 'শাহাদাতে কারবালা দিবস উপলক্ষ্যে চট্টগ্রামে সমাবেশ ও শোভাযাত্রা অনুষ্ঠিত হয়েছে। শনিবার (৫ জুলাই) নগরের পুরাতন রেল স্টেশন চত্বরে আয়োজিত এ কর্মসূচিতে অংশগ্রহণকারীরা ইমাম হোসাইন (রা.) এবং তার অনুসারীদের শাহাদাত স্মরণ করেন।', '<p><br><br><strong>নিজস্ব প্রতিবেদক</strong><br><br>শাহাদাতে কারবালা দিবস উপলক্ষ্যে চট্টগ্রামে সমাবেশ ও শোভাযাত্রা অনুষ্ঠিত হয়েছে। শনিবার (৫ জুলাই) নগরের পুরাতন রেল স্টেশন চত্বরে আয়োজিত এ কর্মসূচিতে অংশগ্রহণকারীরা ইমাম হোসাইন (রা.) এবং তার অনুসারীদের শাহাদাত স্মরণ করেন।</p><p><br>বিশ্ব সুন্নী মুভমেন্ট ও বিশ্ব হিউম্যানিটি রেভুলুশন, বাংলাদেশ চট্টগ্রাম জেলা শাখার উদ্যোগে আয়োজিত এ সমাবেশে সভাপতিত্ব করেন সংগঠনের কেন্দ্রীয় নেতা আল্লামা আরেফ সারতাজ। সমাবেশে বক্তব্য দেন এমদাদুল হক সায়ীফ, আল্লামা ইলিয়াস শাহ, আল্লামা নঈম উদ্দীন, আল্লামা রেজাউল কাউছার, সাবিনা সাআদাত সাফা, কামরুল আলম নকীব, নিজাম উদ্দীন, আজিজ মাবরুর, আবদুল বারেকসহ অনেকে।</p><p>এসময় বক্তারা এটিকে ইসলামের ন্যায়-নীতি ও মানবতার মুক্তির সংগ্রামের একটি অন্যতম স্মারক হিসেবে উল্লেখ করেন। তারা বলেন, ইমাম হোসাইন (রা.)র শাহাদাত ছিল মানবতার জন্য এক অমূল্য দিকনির্দেশনা। এটি আমাদেরকে সত্য, ন্যায় ও মানবাধিকারের প্রতি চিরকাল অবিচল থাকার শিক্ষা দেয়।</p><p><br>নেতারা আরও বলেন, কারবালার যুদ্ধে ইমাম হোসাইন শুধু ইসলামকেই রক্ষা করেননি, বরং তিনি মানবতার পক্ষে একটি মহাকাব্য রচনা করেছেন। তার শাহাদাত আমাদের ঈমানি সত্তা ও জীবনের মূল চেতনা, যা অন্যায় ও অবিচারের বিরুদ্ধে সংগ্রামে আমাদের প্রেরণা জুগিয়ে থাকে।</p><p><br>সমাবেশ শেষে একটি শোভাযাত্রা বের করা হয়। এটি চট্টগ্রাম শহরের বিভিন্ন সড়ক প্রদক্ষিণ করে। শোভাযাত্রার মাধ্যমে তারা শাহাদাতে কারবালা দিবসের মাহাত্ম্য ও এর শিক্ষা নিয়ে মানুষের মধ্যে সচেতনতা সৃষ্টি করতে চেয়েছেন।</p><p>বিশ্ব সুন্নী মুভমেন্টের নেতারা শিয়াবাদ, মোয়াবিয়া ও এজিদপন্থি চক্রের বিকৃতি ও প্রতারণা সম্পর্কে সতর্ক থাকার আহ্বান জানান। তারা বলেন, এটা অত্যন্ত গুরুত্বপূর্ণ যে আমরা ঈমানি আদর্শে দৃঢ় থাকি এবং সত্যের পথে চলি।</p><p>এ ছাড়া নেতারা এই দিনে ইসলাম ও মানবতার প্রতীক ইমাম হোসাইন (রা.)র শাহাদাতের শিক্ষাকে বাস্তব জীবনে প্রতিষ্ঠিত করতে সবাইকে আহ্বান জানান।</p>', 'published', NULL, 'Botble\\Member\\Models\\Member', 0, './29.webp', 61, NULL, '2025-07-06 19:11:45', '2025-07-06 20:16:56'),
(38, 'করোনা: চট্টগ্রামে ২৪ ঘণ্টায় শনাক্ত ৩ জন', 'নগরে বাড়ছে করোনাভাইরাসের সংক্রমণ। একদিনের ব্যবধানে বেড়েছে করোনা পরীক্ষাও।\n\nগত ২৪ ঘণ্টায় ১৩৬টি নমুনা পরীক্ষা করে ৩ জনের করোনা শনাক্ত হয়েছে। এ নিয়ে মোট করোনা আক্রান্ত রোগীর সংখ্যা দাঁড়িয়েছে ১৭৮ জনে।\nরোববার (৬ জুলাই) দুপুরে', '<p>নগরে বাড়ছে করোনাভাইরাসের সংক্রমণ। একদিনের ব্যবধানে বেড়েছে করোনা পরীক্ষাও।</p><p>গত ২৪ ঘণ্টায় ১৩৬টি নমুনা পরীক্ষা করে ৩ জনের করোনা শনাক্ত হয়েছে। এ নিয়ে মোট করোনা আক্রান্ত রোগীর সংখ্যা দাঁড়িয়েছে ১৭৮ জনে।<br>রোববার (৬ জুলাই) দুপুরে জেলা সিভিল সার্জন কার্যালয় থেকে প্রকাশিত করোনা প্রতিবেদনে এ তথ্য জানা যায়।</p><p>প্রতিবেদন অনুযায়ী, চট্টগ্রাম জেলার ১৫টি ল্যাবের ৯টিতে ১৩৬টি নমুনা পরীক্ষা করা হয়। এর মধ্যে শেভরণে ১৬টি নমুনা পরীক্ষায় ২ জন, এপিক হেলথ কেয়ারে ৪৩টি নমুনা পরীক্ষায় ১ জনের করোনা শনাক্ত হয়। আক্রান্ত ৩ জনের মধ্যে ১ জন উপজেলা এবং ২ জন নগরের বিভিন্ন এলাকার বাসিন্দা।</p><p>সিভিল সার্জন ডা. জাহাঙ্গীর আলম জানান, করোনা মোকাবিলায় স্বাস্থ্যবিধি মেনে চলা জরুরি। নিয়মিত মাস্ক ব্যবহার ও পরিস্কার পরিচ্ছন্ন থাকার মধ্য দিয়ে সংক্রমণ প্রতিরোধ করা সম্ভব।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, './46.webp', 46, NULL, '2025-07-06 22:15:25', '2025-07-06 22:15:25'),
(39, 'সুষ্ঠু ও গ্রহণযোগ্য নির্বাচন নিশ্চিতে পিআর পদ্ধতি অপরিহার্য: শাহজাহান', 'জামায়াতে ইসলামীর অ্যাসিস্ট্যান্ট সেক্রেটারি জেনারেল ও চট্টগ্রাম অঞ্চল পরিচালক মাওলানা মুহাম্মদ শাহজাহান বলেছেন, অবাধ, সুষ্ঠু ও গ্রহণযোগ্য নির্বাচন নিশ্চিত করতে সংখ্যানুপাতিক প্রতিনিধিত্ব (পিআর) পদ্ধতি অপরিহার্য। এই পদ্ধতিতে নির্বাচন হলে ফ্যাসিজমের রাস্তা বন্ধ হবে।', '<p>জামায়াতে ইসলামীর অ্যাসিস্ট্যান্ট সেক্রেটারি জেনারেল ও চট্টগ্রাম অঞ্চল পরিচালক মাওলানা মুহাম্মদ শাহজাহান বলেছেন, অবাধ, সুষ্ঠু ও গ্রহণযোগ্য নির্বাচন নিশ্চিত করতে সংখ্যানুপাতিক প্রতিনিধিত্ব (পিআর) পদ্ধতি অপরিহার্য। এই পদ্ধতিতে নির্বাচন হলে ফ্যাসিজমের রাস্তা বন্ধ হবে।</p><p>ভোট বাণিজ্য বন্ধ হয়ে যাবে পরবর্তী প্রতিটি নির্বাচনে। &nbsp;<br>রোববার (৬ জুলাই) সকালে দলটির চট্টগ্রাম অঞ্চল দায়িত্বশীলদের এক সমাবেশে সভাপতির বক্তব্যে তিনি এ কথা বলেন।</p><p>তিনি আরও বলেন, যেনতেন ভাবে নির্বাচন হলে জাতি মেনে নেবে না। সমগ্র জাতি একটি অবাধ, সুষ্ঠু নির্বাচনের জন্য প্রহর গুনছেন। তবে যার জন্য হাজারো ছাত্র-জনতা জীবন দিল সেই কাঙ্ক্ষিত সংস্কার এবং গণহত্যার বিচার না করে যেনতেন নির্বাচনের মাধ্যমে কোনো দলকে ক্ষমতায় বসানো হলে জনগণ সেটা মেনে নেবে না।</p><p>চট্টগ্রাম মহানগর জামায়াতের দেওয়ানবাজারের একাডেমি (বিআইএ) কার্যালয়ের সম্মেলন কক্ষে অনুষ্ঠিত সমাবেশে অন্যান্যের মধ্যে বক্তব্য রাখেন জামায়াতের কেন্দ্রীয় কর্মপরিষদ সদস্য ও চট্টগ্রাম অঞ্চল টিম সদস্য অধ্যাপক আহছানুল্লাহ ভূঁইয়া, কেন্দ্রীয় কর্মপরিষদ সদস্য ও চট্টগ্রাম-১৫ আসনের সংসদ সদস্য প্রার্থী আলহাজ শাহজাহান চৌধুরী, চট্টগ্রাম অঞ্চল টিম সদস্য মুহাম্মদ জাফর সাদেক, অধ্যক্ষ মাওলানা মুহাম্মদ আমিরুজ্জামান, মাওলানা মোস্তাফিজুর রহমান ও অধ্যাপক নুরুল আমিন চৌধুরী, কেন্দ্রীয় মজলিসে শূরা সদস্য ও নগর জামায়াতের ভারপ্রাপ্ত আমির মুহাম্মদ নজরুল ইসলাম, কেন্দ্রীয় মজলিসে শূরা সদস্য ও চট্টগ্রাম দক্ষিণ জেলা আমির আনোয়ারুল আলম চৌধুরী, কেন্দ্রীয় মজলিসে শূরা সদস্য, চট্টগ্রাম উত্তর জেলা আমির ও চট্টগ্রাম-৩ আসনের এমপি প্রার্থী আলাউদ্দিন শিকদার, কক্সবাজার জেলা আমির ও কক্সবাজার-৪ আসনের প্রার্থী অধ্যক্ষ মাওলানা নুর আহমদ আনোয়ারী, বান্দরবান পার্বত্য জেলা আমির মাওলানা এস এম আব্দুস ছালাম আজাদ, খাগড়াছড়ি পার্বত্য জেলা আমির অধ্যাপক সৈয়দ আব্দুল মোমেন, রাঙামাটি জেলা আমির অধ্যাপক আবদুল আলিম, চট্টগ্রাম মহানগর সেক্রেটারি ও চট্টগ্রাম-২ আসনের সংসদ সদস্য পদপ্রার্থী অধ্যক্ষ মুহাম্মদ নুরুল আমিন, চট্টগ্রাম দক্ষিণ জেলা সেক্রেটারি অধ্যক্ষ মাওলানা বদরুল হক, চট্টগ্রাম উত্তর জেলা সেক্রেটারি আব্দুল জব্বার, কক্সবাজার জেলা সেক্রেটারি জাহেদুল ইসলাম, রাঙামাটি জেলা সেক্রেটারি মনছুরুল আলম, খাগড়াছড়ি জেলা সেক্রেটারি মিনহাজুর রহমান প্রমুখ।</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './47.webp', 75, NULL, '2025-07-06 22:19:29', '2025-07-06 22:19:29'),
(40, 'দক্ষিণাঞ্চলে ভারী বৃষ্টির আভাস, চট্টগ্রামে ভূমিধসের ঝুঁকি', 'দক্ষিণ-পশ্চিম মৌসুমি বায়ুর সক্রিয়তার কারণে আগামী ২৪ ঘণ্টায় চট্টগ্রাম, খুলনা ও বরিশাল বিভাগের কোথাও কোথাও ভারী থেকে অতি ভারী বর্ষণের সম্ভাবনা রয়েছে বলে জানিয়েছে আবহাওয়া অধিদপ্তর। রোববার (৬ জুলাই) আবহাওয়ার এক সতর্কবার্তায় এ তথ্য জানানো হয়।', '<p><br>দক্ষিণ-পশ্চিম মৌসুমি বায়ুর সক্রিয়তার কারণে আগামী ২৪ ঘণ্টায় চট্টগ্রাম, খুলনা ও বরিশাল বিভাগের কোথাও কোথাও ভারী থেকে অতি ভারী বর্ষণের সম্ভাবনা রয়েছে বলে জানিয়েছে আবহাওয়া অধিদপ্তর। রোববার (৬ জুলাই) আবহাওয়ার এক সতর্কবার্তায় এ তথ্য জানানো হয়।</p><p><br>আবহাওয়া অধিদপ্তরের ঝড় সতর্কীকরণ কেন্দ্র থেকে পাঠানো এক বিজ্ঞপ্তিতে জানানো হয়, চট্টগ্রাম বিভাগের পাহাড়ি এলাকায় অতি ভারী বর্ষণের কারণে কোথাও কোথাও ভূমিধসের ঝুঁকি রয়েছে। একইসঙ্গে চট্টগ্রাম মহানগরের নিম্নাঞ্চলে জলাবদ্ধতাও সৃষ্টি হতে পারে বলে আশঙ্কা করা হচ্ছে।</p><p>অন্যদিকে, গাঙ্গেয় পশ্চিমবঙ্গ ও তৎসংলগ্ন এলাকায় সৃষ্ট একটি লঘুচাপের কারণে উত্তর বঙ্গোপসাগর ও বাংলাদেশের উপকূলীয় এলাকায় বায়ুচাপের তারতম্যের আধিক্য বিরাজ করছে। এর ফলে সমুদ্রবন্দরগুলোর ওপর দিয়ে ঝোড়ো হাওয়া বয়ে যেতে পারে বলে পূর্বাভাসে জানানো হয়েছে।</p><p><br>এই পরিস্থিতিতে চট্টগ্রাম, কক্সবাজার, মোংলা ও পায়রা সমুদ্রবন্দরকে ৩ নম্বর স্থানীয় সতর্ক সংকেত দেখিয়ে যেতে বলা হয়েছে। এ ছাড়া মাছ ধরার ট্রলার ও নৌকাগুলোকে পরবর্তী নির্দেশ না দেওয়া পর্যন্ত উপকূলের কাছাকাছি থেকে সাবধানে চলাচলের নির্দেশনা দেওয়া হয়েছে।</p><p><br>পাশাপাশি দেশের অভ্যন্তরীণ নদীবন্দরগুলোর জন্যও সতর্কবার্তা জারি করেছে আবহাওয়া অধিদপ্তর। খুলনা, বরিশাল, পটুয়াখালী, নোয়াখালী, কুমিল্লা, চট্টগ্রাম, কক্সবাজার ও সিলেট অঞ্চলে ঘণ্টায় ৪৫-৬০ কিলোমিটার বেগে দক্ষিণ অথবা দক্ষিণ-পূর্ব দিক থেকে দমকা বা ঝোড়ো হাওয়াসহ বজ্রসহ বৃষ্টিপাত হতে পারে বলে পূর্বাভাসে জানানো হয়েছে। এসব এলাকার নদীবন্দরগুলোকে এক নম্বর সতর্ক সংকেত দেখাতে বলা হয়েছে।</p><p>এদিকে, ঢাকা ও পার্শ্ববর্তী এলাকার জন্য দেওয়া সন্ধ্যা ৭টা থেকে পরবর্তী ছয় ঘণ্টার আবহাওয়া পূর্বাভাসে বলা হয়েছে, আকাশ মেঘলা থেকে অস্থায়ীভাবে মেঘলা থাকতে পারে এবং হালকা বৃষ্টিপাতের সম্ভাবনা রয়েছে। দক্ষিণ অথবা দক্ষিণ-পূর্ব দিক থেকে ঘণ্টায় ১০-১৫ কিলোমিটার বেগে বাতাস প্রবাহিত হতে পারে। রাতের তাপমাত্রা সামান্য কমতে পারে বলেও পূর্বাভাসে জানানো হয়েছে।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, './59.webp', 49, NULL, '2025-07-07 03:05:38', '2025-07-07 03:05:38'),
(41, 'ভবন নাছির-রেজাউলরা করেছিলেন একতলা, শাহাদাত করবেন ৪ তলা', 'চট্টগ্রাম নগরের ২ নম্বর গেটের বিপ্লব উদ্যান নিয়ে নতুন চুক্তি করেছে সিটি করপোরেশন (চসিক)। এ চুক্তির মাধ্যমে উদ্যানে নতুন স্থাপনা নির্মাণের সুযোগ পাচ্ছে একটি বেসরকারি প্রতিষ্ঠান। আগের দুই মেয়র আ জ ম নাছির উদ্দীন ও মো. রেজাউল করিম চৌধুরী যেখানে একতলা ভবন নির্মাণের অনুমতি দিয়েছিলেন, সেখানে বর্তমান মেয়র শাহাদাত হোসেনের নতুন চুক্তিতে উদ্যানে চারতলা ভবন নির্মাণের সুযোগ দেওয়া হয়েছে।', '<p><br>চট্টগ্রাম নগরের ২ নম্বর গেটের বিপ্লব উদ্যান নিয়ে নতুন চুক্তি করেছে সিটি করপোরেশন (চসিক)। এ চুক্তির মাধ্যমে উদ্যানে নতুন স্থাপনা নির্মাণের সুযোগ পাচ্ছে একটি বেসরকারি প্রতিষ্ঠান। আগের দুই মেয়র আ জ ম নাছির উদ্দীন ও মো. রেজাউল করিম চৌধুরী যেখানে একতলা ভবন নির্মাণের অনুমতি দিয়েছিলেন, সেখানে বর্তমান মেয়র শাহাদাত হোসেনের নতুন চুক্তিতে উদ্যানে চারতলা ভবন নির্মাণের সুযোগ দেওয়া হয়েছে।</p><p><br>সম্প্রতি চসিক নূর হাফিজ প্রপার্টিজ নামের প্রতিষ্ঠানটির সঙ্গে ২৫ বছরের জন্য চুক্তি করে। চুক্তির শর্ত অনুযায়ী, উদ্যানে বিদ্যমান একতলা স্থাপনাটি বর্ধিত করে চারতলা পর্যন্ত নির্মাণ করা যাবে। দ্বিতীয় তলায় আধুনিক সবুজবান্ধব আরবান লাউঞ্জ, তৃতীয় তলায় ইনডোর গেমসের জন্য কফিশপসহ অবকাঠামো এবং চতুর্থ তলায় মুক্তিযুদ্ধের ইতিহাস নিয়ে প্রদর্শনী কেন্দ্র নির্মাণের সুযোগ রাখা হয়েছে। উদ্যানে বর্তমানে থাকা ২১টি দোকান ও ২টি শৌচাগার নতুন প্রতিষ্ঠানের হাতে তুলে দেওয়া হবে।</p><p><br>জানা যায়, ১৯৭৯ সালে ২ নম্বর গেট এলাকায় এক একর জায়গায় বিপ্লব উদ্যান গড়ে তোলা হয়। ২০১৮ সালে তৎকালীন মেয়র আ জ ম নাছির উদ্দীন উদ্যানটিতে দোকানপাট নির্মাণ শুরু করেন। ২০২৩ সালে এসে তৎকালীন মেয়র রেজাউল করিম চৌধুরী উদ্যানটিতে অবকাঠামো নির্মাণে আরেকটি চুক্তি করেছিলেন।</p><p>এদিকে, বিপ্লব উদ্যানে নতুন স্থাপনা নির্মাণ নিয়ে নাগরিক সমাজের প্রতিনিধিরা তীব্র বিরোধিতা জানিয়েছেন। নগরের পরিবেশ ও ইতিহাসের সুরক্ষায় উদ্বেগও প্রকাশ করেন তারা। তাদের বক্তব্য, নগরের সবুজ এলাকা এবং উন্মুক্ত স্থান ক্রমেই সংকুচিত হয়ে বাণিজ্যিকীকরণ হচ্ছে। আগের দুই মেয়রের সময়েও বিপ্লব উদ্যানে একই ধরনের চুক্তি হয়েছিল। তবে এসব চুক্তি বাতিল করতে হয়েছিল আদালতের নির্দেশে। এরপরেও এই নতুন চুক্তি নিয়ে বিতর্কের সৃষ্টি হয়েছে।</p><p><br>শুধু বিপ্লব উদ্যান নয়। নগরের চান্দগাঁও ও কোতোয়ালি থানার বিভিন্ন ফুটপাত দখল করে অবকাঠামো নির্মাণ শুরু করে চসিক। সম্প্রতি নগরের কোতোয়ালি থানা কাজির দেউরি আউটার স্টেডিয়াম সংলগ্ন পুলিশ বক্সের পাশের প্রায় ১০০ ফুট ফুটপাত ঘিরে সেখানে নতুন করে নির্মাণকাজ শুরু করেছে সংস্থাটি। যেখানে চসিকের মেয়র আ. জ. ম নাছির উদ্দীন ২০১৮ সালে দোকানপাট বরাদ্দ দিয়েছিলেন। ২০২৩ সালে এসে জেলা প্রশাসন সেগুলো উচ্ছেদ করে দিয়েছিল।</p><p>বিপ্লব উদ্যানে নিয়মিত হাঁটতে আসেন জুনায়েদ খান। তিনি বলেন, আমি এখানে নিয়মিত হাঁটতে আসি। এমনিতে এখানে দোকানপাট নির্মাণ করে পরিবেশ নষ্ট হয়েছে। এখন &nbsp;চারতলা বাণিজ্যিক ভবন তৈরি করা খুবই হতাশাজনক। উদ্যানে হাঁটার জন্য যে শান্ত পরিবেশ ছিল, তা যদি হারিয়ে যায়, তাহলে কই যাবো আমরা? সিটি করপোরেশনকে এমন সিদ্ধান্ত নেওয়ার আগে আমাদের মতামত নেওয়ার উচিত ছিল। শহরে আমাদের বিশ্রামের জায়গা খুবই প্রয়োজন। সবুজ উদ্যানগুলো যদি শুধু বাণিজ্যিক কার্যক্রমের জন্য ব্যবহার করা হয়। তাহলে শহরের মানুষের জন্য বেঁচে থাকার স্পেসই তো থাকবে না!</p><p>সুশাসনের জন্য নাগরিক (সুজন) চট্টগ্রাম জেলা শাখার সাধারণ সম্পাদক অ্যাডভোকেট আখতার কবির চৌধুরী বলেন, বিভিন্ন পদে চেহারা পরিবর্তন হয়েছে। বাস্তবে কোনো পরিবর্তন হয়নি। আগের লোকেরাও অনিয়ম ও দুর্নীতি করেছে, এখনো হচ্ছে। এটি দুঃখজনক। চসিকের শীর্ষ পদে যিনি আছেন, তিনি ৫ আগস্টের পরিবর্তনের পর বসেছেন। এত লোকের প্রাণহানির পর যিনি পদে বসেছেন, তার প্রতি জনগণের অনেক প্রত্যাশা। বিপ্লব উদ্যানে স্থাপনার অনুমতি দেওয়া, বাণিজ্য করার সুযোগ দেওয়া কোনোভাবেই গ্রহণযোগ্য নয়।</p><p>চুক্তির বিষয়ে জানতে ডা. শাহাদাত হোসেন কানাডা সফরে থাকায় তার বক্তব্য নেওয়া সম্ভব হয়নি।</p><p>চসিকের প্রধান নির্বাহী কর্মকর্তা শেখ মুহম্মদ তৌহিদুল ইসলাম বলেন, বিপ্লব উদ্যানে খোলা স্থানে কোনো ধরনের স্থাপনা নির্মাণ করা যাবে না। আগের যে জায়গায় দোকান রয়েছে, সেখানে স্থাপনা করতে হবে। এ জন্য চট্টগ্রাম উন্নয়ন কর্তৃপক্ষের (সিডিএ) অনুমতি নিতে হবে।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, './60.webp', 66, NULL, '2025-07-07 03:16:25', '2025-07-07 03:16:58'),
(42, 'বিদায় সাইফ পাওয়ারটেক, এনসিটি চালাবে নৌবাহিনীর ড্রাইডক', 'চট্টগ্রাম বন্দরের নিউমুরিং কনটেইনার টার্মিনাল (এনসিটি) পরিচালনার দায়িত্ব পেয়েছে চট্টগ্রাম ড্রাইডক লিমিটেড। এটি নৌবাহিনী পরিচালিত একটি সামরিক জাহাজ মেরামতকারী প্রতিষ্ঠান।', '<p><br>চট্টগ্রাম বন্দরের নিউমুরিং কনটেইনার টার্মিনাল (এনসিটি) পরিচালনার দায়িত্ব পেয়েছে চট্টগ্রাম ড্রাইডক লিমিটেড। এটি নৌবাহিনী পরিচালিত একটি সামরিক জাহাজ মেরামতকারী প্রতিষ্ঠান।<br>সোমবার (৭ জুলাই) থেকে প্রতিষ্ঠানটি টার্মিনাল পরিচালনা শুরু করবে। রোববার সাইফ পাওয়ারটেকের সঙ্গে বন্দরের চুক্তির মেয়াদ শেষ হচ্ছেএ সরকারের উচ্চ পর্যায়ের নির্দেশনায় বিতর্কিত সাইফ পাওয়ারটেকের সঙ্গে আর চুক্তি করছে না বন্দর কর্তৃপক্ষ। এর মধ্য দিয়ে বন্দরের এনসিটি টার্মিনালে দীর্ঘ দেড় দশকের বেশি সময় রাজত্বে থাকা প্রতিষ্ঠান সাইফ পাওয়ারটেকের বিদায়ঘণ্টা বেজে গেছে।</p><p>যদিও এনসিটি থেকে সাইফ পাওয়ারটেককে সরিয়ে দেওয়ার বিষয়টি আগে চূড়ান্ত হয়েছিল। প্রথমে সিদ্ধান্ত হয়েছিল বন্দর কর্তৃপক্ষ নিজেই টার্মিনালটি পরিচালনা করবে। পরবর্তীতে সরকার নৌবাহিনীকে প্রতিষ্ঠানটি পরিচালনার দায়িত্ব দিতে আগ্রহ প্রকাশ করে। তবে আইনি কিছুটা জটিলতা থাকায় সরাসরি নৌবাহিনীকে দায়িত্ব দেওয়া সম্ভব হয়নি। তাদের নিয়ন্ত্রণাধীন প্রতিষ্ঠান ড্রাইডককে এনসিটির দায়িত্ব দেয় সরকার।</p><p><br>চট্টগ্রাম বন্দরের সচিব মো. ওমর ফারুক বলেন, ড্রাইডকের সঙ্গে চুক্তির বিষয়টি বন্দর কর্তৃপক্ষের বোর্ড সভায় অনুমোদন হয়েছে। সোমবার থেকে ছয় মাসের জন্য চুক্তি হবে। এদিন সাইফ পাওয়ার টেক আনুষ্ঠানিকভাবে দায়িত্ব হস্তান্তর করবে।<br>এরআগে, এনসিটি বিদেশিদের হাতে না দেওয়ার দাবিতে বিভিন্ন পক্ষ সরব হয়। তবে তাদের দাবির আড়ালে সাইফ পাওয়ারটেককে রক্ষা করতেই এই আন্দোলন চালিয়েছে বলে অভিযোগ করে অনেকেই। আন্দোলনের ডামাডোলের মধ্যেই নৌ পরিবহন উপদেষ্টা ব্রিগেডিয়ার এম সাখাওয়াত হোসেন একটি হোয়াটসঅ্যাপ চ্যাট ফাঁস করেন। এতে টাকা ঢেলে বন্দর অচলের জন্য সাইফ পাওয়ারটেকের ব্যবস্থাপনা পরিচালক তরফদার রুহুল আমিন নির্দেশনা দেন বলে অভিযোগ করেন উপদেষ্টা সাখাওয়াত।</p><p>জানা যায়, সাইফ পাওয়ারটেক ২০০৫ সালে যাত্রা শুরু করে বন্দরের যন্ত্রপাতি রক্ষণাবেক্ষণ কাজের মাধ্যমে। ২০০৮ সালে আওয়ামী লীগ ক্ষমতায় আসার পর দলটির শীর্ষ নেতাদের সহযোগিতায় প্রতিষ্ঠানটি বন্দরের কনটেইনার হ্যান্ডলিংসহ নানা খাতে একচেটিয়া নিয়ন্ত্রণ প্রতিষ্ঠা করে। সরকারের উচ্চ মহলের সিদ্ধান্তে বন্দর কর্তৃপক্ষ টেন্ডার না দিয়েই প্রতিষ্ঠানটির সঙ্গে বছরের পর বছর চুক্তি নবায়ন করে। আবার কোনো সময় টেন্ডার হলেও নীতিমালায় এমন সব শর্ত দেওয়া হয় যাতে সাইফ পাওয়ার টেক ছাড়া কোনো প্রতিষ্ঠান প্রতিযোগিতায় টিকতে পারে।</p><p>প্রতিষ্ঠানটির ব্যবস্থাপনা পরিচালক তরফদার মো. রুহুল আমিনের ঘনিষ্ঠ ছিলেন সাবেক নৌপরিবহনমন্ত্রী শাজাহান খান, সাবেক সংসদ সদস্য &nbsp;এম এ লতিফ, নূর-ই-আলম চৌধুরী, সামশুল হক চৌধুরী এবং চট্টগ্রাম নগর আওয়ামী লীগের সাধারণ সম্পাদক আ. জ. ম নাছির উদ্দীনসহ দলটির শীর্ষ নেতাদের। এই ঘনিষ্ঠতাই ছিল তার প্রধান সম্পদ। এর মাধ্যমে তিনি কেবল বন্দর নয়, দেশের আরও অনেক বড় সরকারি প্রকল্পে প্রবেশাধিকার পান।</p><p>সাইফ পাওয়ারটেকের বিরুদ্ধে ২০২২ সালে দুবাইভিত্তিক সাফিন ফিডার কোম্পানির সঙ্গে সমঝোতার ঘোষণা দিয়ে শেয়ারবাজারে শেয়ারদর বাড়িয়ে কোটি কোটি টাকা উত্তোলনের অভিযোগ রয়েছে। এর বাইরে, সংযুক্ত আরব আমিরাতে খোলা প্রতিষ্ঠান ‘সাইফ মেরিটাইম এলএলসির’-অর্থ বাংলাদেশ থেকে কীভাবে পাচার হয়েছে, তা নিয়ে তদন্ত চলছে। বর্তমানে সরকারের বিভিন্ন সংস্থা সাইফ পাওয়ারটেকের বিরুদ্ধে অর্থ পাচার, রাজস্ব ফাঁকি ও রাজনৈতিক প্রভাব খাটিয়ে সরকারি কাজ বাগিয়ে নেওয়ার বিষয়ে অনুসন্ধান শুরু করেছে।&nbsp;</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 1, './61.webp', 75, NULL, '2025-07-07 03:19:50', '2025-07-07 03:19:50');
INSERT INTO `posts` (`id`, `name`, `description`, `content`, `status`, `author_id`, `author_type`, `is_featured`, `image`, `views`, `format_type`, `created_at`, `updated_at`) VALUES
(43, 'রাঙ্গুনিয়ায় বন ধ্বংস ও কাঠ পাচারের নায়ক ফরেস্ট রেঞ্জার মানিক', 'রাঙ্গুনিয়া রেঞ্জের সংরক্ষিত বনাঞ্চল যেন একটি গোপন বনজ বাজারে রূপ নিয়েছে, যেখানে ফরেস্ট রেঞ্জার মো. মেহেদী হাসান মানিকই প্রধান পরিচালক। চট্টগ্রাম দক্ষিণ বন বিভাগের এ', '<p><span style=\"background-color:rgb(255,255,255);color:rgb(68,68,68);\"><span style=\"font-family:Verdana, Arial, Helvetica, sans-serif;font-size:14px;font-style:normal;font-weight:400;word-spacing:0px;\">রাঙ্গুনিয়া রেঞ্জের সংরক্ষিত বনাঞ্চল যেন একটি গোপন বনজ বাজারে রূপ নিয়েছে, যেখানে ফরেস্ট রেঞ্জার মো. মেহেদী হাসান মানিকই প্রধান পরিচালক। চট্টগ্রাম দক্ষিণ বন বিভাগের এই কর্মকর্তা দায়িত্ব গ্রহণের পর থেকেই পার্বত্য রাঙ্গুনিয়ার পাহাড়ি বনাঞ্চলে গাছ নিধনের মাধ্যমে কোটি টাকার কাঠ পাচার শুরু হয়েছে বলে অভিযোগ করেছেন স্থানীয় বাসিন্দা, পরিবেশবাদী সংগঠন ও বন বিভাগের একাধিক কর্মকর্তা। অভিযোগ রয়েছে, মানিক নিয়মিতভাবে রাঙ্গুনিয়া এভিয়ারি ও ইকো পার্কসহ আশপাশের সংরক্ষিত বনাঞ্চল থেকে রাতের আঁধারে কাঠ কেটে তা পাচার করছেন। পাচারের এই সিন্ডিকেটে জড়িত রয়েছে একাধিক স্থানীয় কাঠ ব্যবসায়ী, প্রভাবশালী রাজনৈতিক নেতাদের অনুসারীরা এবং বন বিভাগেরই কিছু অসাধু কর্মকর্তা। চন্দ্রঘোনার এক কাঠ ব্যবসায়ী নাম প্রকাশ না করার শর্তে জানান, তিনি ফরেস্ট রেঞ্জার মানিকের মৌখিক অনুমতি নিয়েই প্রতিদিন রাত ১২টার পর ট্রাক পাঠান, যা পরদিন ভোরের আগেই চট্টগ্রাম শহরে পৌঁছে যায়। এপ্রিল থেকে জুলাই— এই চার মাসে পার্ক এলাকা থেকে অন্তত ২৫টি মূল্যবান সেগুন গাছ কেটে বিক্রি করা হয় বলে স্থানীয় সূত্র জানায়। প্রতি গাছের মূল্য গড়ে ৪০ হাজার টাকা হিসেব করলে এর আর্থিক মূল্য প্রায় ১০ লাখ টাকা। ঘটনাটি প্রকাশ পাওয়ার পর মানিক লোকদেখানোভাবে ২৫০ ঘনফুট কাঠ জব্দ দেখিয়ে বন অফিসে জমা দেন, কিন্তু পরে ২০০ ঘনফুট কাঠ গোপনে এক ব্যবসায়ীর কাছে চার লাখ টাকায় বিক্রি করা হয়, যেখানে তাকে সহযোগিতা করেন সহকারী বন কর্মকর্তা মোতালেব আল আমিন। বিষয়টি জানাজানি হলে বিভাগীয় বন কর্মকর্তা আব্দুল্লাহ আল মামুন একটি তিন সদস্যের তদন্ত কমিটি গঠন করেন, তবে সেই কমিটির প্রতিবেদন আর আলোর মুখ দেখেনি। স্থানীয়দের দাবি, মোটা অঙ্কের আর্থিক লেনদেনের মাধ্যমে তদন্ত প্রতিবেদন গায়েব করা হয়েছে। গোপন সূত্র জানায়, মানিক সরাসরি কাঠ পাচার সিন্ডিকেট পরিচালনা করেন। প্রতিদিন অন্তত ১৫ থেকে ২০টি কাভার্ডভ্যান, পিকআপ, ট্রাক কোদালা বিট থেকে পার্ক এলাকা হয়ে কাঠ পরিবহন করে চট্টগ্রাম-কক্সবাজার মহাসড়ক ধরে দেশের বিভিন্ন অঞ্চলে পৌঁছে দেয়। এসব গাড়ির জন্য জনপ্রতি ৫০ থেকে ৬০ হাজার টাকা করে ঘুষ আদায় করা হয়, যার একটি বড় অংশ স্থানীয় প্রভাবশালীদের মাঝেও বণ্টন হয় বলে অভিযোগ উঠেছে। কর্ণফুলী নদীপথও পাচারের জন্য ব্যবহৃত হচ্ছে। পোমরা, ইছামতি, ইসলামপুর এবং খুরুশিয়া রেঞ্জের বিভিন্ন পয়েন্ট থেকে ট্রলার ও নৌকা করে কাঠ পাচার হচ্ছে রাঙ্গুনিয়ার বিভিন্ন ঘাটে, যেখানে পরে গাড়িতে তুলে তা পাঠানো হয় শহর অভিমুখে। সম্প্রতি রাঙ্গুনিয়া থানা পুলিশ একটি কাঠবোঝাই ট্রাক আটক করলে সংশ্লিষ্ট ব্যবসায়ী খোকন বলেন, তিনি ফরেস্ট রেঞ্জার মানিকের অনুমতিতেই কাঠ পরিবহন করছিলেন। তবে ফোনে যোগাযোগ করলে মানিক বিষয়টি এড়িয়ে যান এবং নিশ্চিত কোনো উত্তর দেননি। অনুসন্ধানে আরও জানা গেছে, মানিক পার্ক এলাকার ভেতর থেকে ভোজ্য ও বনজ মিলিয়ে প্রায় ৫০০টি গাছ বিক্রি করেছেন মাহবুব নামে এক রাজনৈতিক নেতার কাছে ১৫ লাখ টাকায়। সরেজমিনে গিয়ে কর্তনের গোড়া দেখে এই অভিযোগের সত্যতাও মিলেছে। স্থানীয় বনকর্মীরা বলছেন, মানিকের বিরুদ্ধে অভিযোগ করলেই বদলির ভয়, কারণ তার ওপর রয়েছে রাজনৈতিক আশীর্বাদ। অভিযোগ রয়েছে, তিনি ছাত্রলীগের সাবেক ক্যাডার এবং সাবেক স্বরাষ্ট্রমন্ত্রীর সুপারিশে বন বিভাগে নিয়োগ পেয়েছেন। তিনি নিয়োগ পেয়েছেন ‘নন-ক্যাডার বিসিএস অফিসার’ পরিচয়ে, যদিও ফরেস্ট রেঞ্জার পদটি মূলত দ্বিতীয় শ্রেণির সরকারি চাকরি, যা পিএসসির মাধ্যমে নিয়োগ হওয়া উচিত ছিল। বন অধিদপ্তরের সূত্র জানায়, কিছু কর্মকর্তার রাজনৈতিক পরিচয়ের কারণে তাদের বিরুদ্ধে ব্যবস্থা নেওয়া সম্ভব হচ্ছে না। এমনকি উচ্চপর্যায়ের নির্দেশ থাকলেও মাঠপর্যায়ে এসব দুর্নীতিবাজ কর্মকর্তারাই নীতিনির্ধারকের ভূমিকায় থাকেন। মানিক ও তার ঘনিষ্ঠদের বিরুদ্ধে আরও অভিযোগ রয়েছে— তারা বিভিন্ন সময় রাজনৈতিক সভায় অংশ নিচ্ছেন এবং বন বিভাগের অভ্যন্তরে সরকারবিরোধী প্রচারণাও করছেন, যা প্রশাসনিক দৃষ্টিকোণ থেকেও গুরুতর অপরাধ। পরিবেশবাদী সংগঠন ও স্থানীয়রা বলছেন, রাঙ্গুনিয়ার মতো পাহাড়ি এলাকায় প্রাকৃতিক বনাঞ্চল ধ্বংসের পরিণতি ভয়াবহ হবে। পাহাড় ধসে মানুষের জীবন হুমকির মুখে পড়বে, জলবায়ু ও পরিবেশের ভারসাম্য বিনষ্ট হবে, নদীর গতিপথ বাধাগ্রস্ত হবে এবং সরকারের কোটি কোটি টাকার রাজস্ব হারিয়ে যাবে। তবুও মানিকের বিরুদ্ধে আজ পর্যন্ত দৃশ্যমান কোনো ব্যবস্থা নেওয়া হয়নি। যোগাযোগের চেষ্টা করা হলে মানিকের মোবাইল ফোন বন্ধ পাওয়া যায়। অন্যদিকে, বিভাগীয় বন কর্মকর্তা আব্দুল্লাহ আল মামুন গণমাধ্যমকে জানান, মানিকের বিরুদ্ধে অভিযোগ পাওয়া গেছে এবং তদন্ত চলছে। তবে তদন্তের ফলাফল বা তার বিরুদ্ধে কোনো দৃশ্যমান ব্যবস্থা এখনও গ্রহণ করা হয়নি, যা স্থানীয়দের মধ্যে ব্যাপক ক্ষোভ ও হতাশা তৈরি করেছে। স্থানীয়দের দাবি, রাঙ্গুনিয়ার সংরক্ষিত বন রক্ষা করতে হলে রেঞ্জার মানিককে দ্রুত অপসারণ করে তার বিরুদ্ধে ফৌজদারি ব্যবস্থা নিতে হবে, না হলে কিছুদিনের মধ্যেই রাঙ্গুনিয়ার প্রাকৃতিক বন ইতিহাসে পরিণত হবে।</span>&nbsp;</span></p>', 'pending', NULL, 'Botble\\Member\\Models\\Member', 1, './22.webp', 217, NULL, '2025-07-07 07:23:32', '2025-07-14 08:18:38'),
(44, 'মধ্যরাতে হাতিরঝিলে আফঈদা-ঋতুপর্ণাদের সংবর্ধনা দিলো বাফুফে', 'এশিয়ান কাপে খেলার যোগ্যতা অর্জন করে রোববার দিনগত রাত দুইটার দিকে দেশে ফিরেছে বাংলাদেশ নারী ফুটবল দল। রাতেই তাদের সংবর্ধনা দেওয়া হয়েছে রাজধানীর হাতিরঝিলের আম্ফি থিয়েটারে।', '<p>এশিয়ান কাপে খেলার যোগ্যতা অর্জন করে রোববার দিনগত রাত দুইটার দিকে দেশে ফিরেছে বাংলাদেশ নারী ফুটবল দল। রাতেই তাদের সংবর্ধনা দেওয়া হয়েছে রাজধানীর হাতিরঝিলের আম্ফি থিয়েটারে।</p><p>রাতে হযরত শাহজালাল আন্তর্জাতিক বিমানবন্দরে পৌঁছানোর পর সেখান থেকে নারী ফুটবল দলকে সরাসরি হাতিরঝিলে নিয়ে যাওয়া হয়। রাত ৩টা ১৫ মিনিটে আফঈদারা অনুষ্ঠানস্থলে পৌঁছালে তাদের ফুলের তোড়া দিয়ে অভ্যর্থনা জানান বাংলাদেশ ফুটবল ফেডারেশনের (বাফুফ) নির্বাহী কমিটির সদস্যরা।<br>৩৫ মিনিট ধরে চলা সংবর্ধনা অনুষ্ঠানে প্রধান অতিথির বক্তব্য রাখেন সংস্কৃতিবিষয়ক উপদেষ্টা মোস্তফা সরয়ার ফারুকী। আরও বক্তব্য রাখেন- জাতীয় ফুটবল দলের সাবেক অধিনায়ক আমিনুল হক, উত্তর সিটি করপোরেশনের প্রশাসক মোহাম্মদ এজাজ, বাফুফে সভাপতি তাবিথ আউয়াল, দলের অধিনায়ক আফঈদা খন্দকার প্রান্তি, তারকা ফরোয়ার্ড ঋতুপর্ণা চাকমা ও কোচ পিটার বাটলার।</p><p>এর আগে রোববার সন্ধ্যায় মিয়ানমার থেকে রওনা দিয়ে থাইল্যান্ড হয়ে রাতে ঢাকায় পৌঁছান আফঈদা ও ঋতুপর্ণারা। সোমবার ভোরে ঋতুপর্ণা চাকমা ও মনিকা চাকমার ভুটানের লিগ খেলতে থিম্পু যাওয়ার কথা। এ কারণে তারা ঢাকায় থাকতে থাকতেই গভীর রাতে এ সংবর্ধনার আয়োজন করা হয়েছে।</p><p><br>ইয়াঙ্গুনে বাংলাদেশ নারী ফুটবল দল এশিয়ান কাপ বাছাইয়ে বাহরাইন, মিয়ানমার ও তুর্কেমেনিস্তানকে হারিয়ে ‘সি’ গ্রুপ চ্যাম্পিয়ন হয়ে আগামী বছর অস্ট্রেলিয়ায় অনুষ্ঠিতব্য এশিয়ান কাপে খেলার যোগ্যতা অর্জন করেছে।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 0, './screenshot-2025-07-07-033002.webp', 81, NULL, '2025-07-07 09:16:59', '2025-07-07 09:17:46'),
(45, 'গাজায় ইসরায়েলি হামলায় প্রাণ গেল আরও ৮২ ফিলিস্তিনির', 'অবরুদ্ধ গাজায় ইসরায়েলি বাহিনীর হামলায় রোববার (৬ জুলাই) আরও অন্তত ৮২ জন ফিলিস্তিনি নিহত হয়েছেন। এর মধ্যে গাজা সিটিতেই প্রাণ গেছে ৩৯ জনের। এর একদিন আগেই গতকাল শনিবার গাজা উপত্যকাজুড়ে ইসরায়েলি বাহিনীর হামলায় ৭৮ জনের প্রাণহানি হয়েছিল। খবর আল-জাজিরার।', '<p><strong>আন্তর্জাতিক ডেস্ক</strong><br><br>অবরুদ্ধ গাজায় ইসরায়েলি বাহিনীর হামলায় রোববার (৬ জুলাই) আরও অন্তত ৮২ জন ফিলিস্তিনি নিহত হয়েছেন। এর মধ্যে গাজা সিটিতেই প্রাণ গেছে ৩৯ জনের। এর একদিন আগেই গতকাল শনিবার গাজা উপত্যকাজুড়ে ইসরায়েলি বাহিনীর হামলায় ৭৮ জনের প্রাণহানি হয়েছিল। খবর আল-জাজিরার।</p><p>গাজায় অব্যাহতভাবে চলা হামলায় পুরো উপত্যকা মৃত্যুপুরীতে পরিণত হয়েছে আরও আগেই। সেখানে এখন খাদ্য সংকট তীব্র আকার ধারণ করেছে। পুরো উপত্যকায় নেমে আসছে মানবিক বিপর্যয়। এর মধ্যে ত্রাণকেন্দ্রগুলোতে খাবার নিতে গিয়ে ইসরায়েলি হামলার মুখে পড়ছেন সেখানকার বাসিন্দারা।</p><p><br>গাজার স্বাস্থ্য মন্ত্রণালয় শনিবার (৫ জুলাই) এক পরিসংখ্যানে জানায়, উপত্যকায় ইসরায়েল ও যুক্তরাষ্ট্র সমর্থিত ত্রাণ উদ্যোগ গাজা হিউম্যানিটারিয়ান ফাউন্ডেশনের (জিএইচএফ) কেন্দ্রগুলো থেকে খাবার সংগ্রহ করার সময় কমপক্ষে ৭৪৩ ফিলিস্তিনি নিহত হয়েছেন। আহত হয়েছেন আরও অন্তত ৪ হাজার ৮৯১ জন।</p><p>ট্রাম্প প্রশাসন গত জুনের শেষ দিকে জিএইচএফকে ৩০ মিলিয়ন ডলার সরাসরি অনুদান দেওয়ার ঘোষণা দেয়। তবে অভিযোগ আছে, ইসরায়েলি বাহিনী জিএইচএফ কেন্দ্রগুলোর আশপাশের স্থানে খাবারের জন্য অপেক্ষারত ফিলিস্তিনিদের লক্ষ্য করে প্রতিনিয়ত হামলা চালাচ্ছে।</p><p><br>এ নিয়ে যুক্তরাষ্ট্রের ভূমিকার সমালোচনা থাকলেও মার্কিন প্রশাসনের দাবি, জিএইচএফ একমাত্র সংগঠন যারা গাজা উপত্যকায় খাদ্য ও ত্রাণ সরবরাহ করতে পেরেছে।</p><p>২০২৩ সালের ৭ অক্টোবর ইসরায়েলে আকস্মিক হামলা চালায় ফিলিস্তিনি স্বাধীনতাকামী সংগঠন হামাস। এরপর থেকেই গাজায় ধ্বংসযজ্ঞ চালাচ্ছে দখলদার সেনারা।</p><p>গাজার স্বাস্থ্য মন্ত্রণালয়ের তথ্য মোতাবেক, গাজায় ইসলায়েলি হামলায় এখন পর্যন্ত ৫৭ হাজার ৪১৮ জন নিহত ও এক লাখ ৩৬ হাজার ২৬১ জন আহত হয়েছেন।<br>দুই মাসের যুদ্ধবিরতি ভেঙে গত মার্চে গাজায় নতুন করে হামলা শুরু করে ইসরায়েল। এদিকে, গাজায় যুক্তরাষ্ট্রের সাম্প্রতিক যুদ্ধবিরতির প্রস্তাবে ইতিবাচক সাড়া দিয়েছে ফিলিস্তিনের স্বাধীনতাকামী সংগঠন হামাস।</p><p>ইসরায়েল ও ফিলিস্তিনের মধ্যে প্রায় ২১ মাস ধরে চলা যুদ্ধের ইতি টানতে সম্প্রতি মার্কিন প্রেসিডেন্ট ডোনাল্ড ট্রাম্প ৬০ দিনের যুদ্ধবিরতির চূড়ান্ত প্রস্তাব উত্থাপন করেন। আগামী সপ্তাহেই গাজায় যুদ্ধবিরতি চুক্তি হতে পারে, গত শুক্রবার সাংবাদিকদের জানিয়েছেন প্রেসিডেন্ট ট্রাম্প।</p><p>গাজায় যুদ্ধবিরতির প্রস্তাব নিয়ে আলোচনার জন্য মধ্যস্থতাকারী দেশ কাতারে প্রতিনিধিদল পাঠানোর নির্দেশ দিয়েছেন ইসরায়েলের প্রধানমন্ত্রী বেনিয়ামিন নেতানিয়াহু।</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './gaza-20250707034505.webp', 87, NULL, '2025-07-07 09:22:34', '2025-07-07 09:22:34'),
(46, 'চালের দাম বাড়ছে, চাপে গরিব মানুষ', 'চাল বাংলাদেশের মানুষের প্রধান খাদ্য। কিন্তু সম্প্রতি চালের দাম বাড়ার কারণে সাধারণ ও নিম্নআয়ের মানুষ নতুন করে চাপের মুখে পড়েছে। একদিকে আয় বাড়ছে না, অন্যদিকে নি', '<p>চাল বাংলাদেশের মানুষের প্রধান খাদ্য। কিন্তু সম্প্রতি চালের দাম বাড়ার কারণে সাধারণ ও নিম্নআয়ের মানুষ নতুন করে চাপের মুখে পড়েছে। একদিকে আয় বাড়ছে না, অন্যদিকে নিত্যপ্রয়োজনীয় পণ্যের পাশাপাশি চালের দামও লাগামছাড়া হয়ে উঠেছে। ২০২৪-২৫ অর্থবছরে দেশে প্রায় ১৩ লাখ মেট্রিক টন চাল আমদানি হয়েছে। এর মধ্যে সরকারিভাবে এসেছে ৮ লাখ ৩৫ হাজার টন এবং বেসরকারি পর্যায়ে প্রায় ৪ লাখ ৭০ হাজার টন। এছাড়া বোরো মৌসুমে উৎপাদন ভালো হলেও বাজারে তার ইতিবাচক প্রভাব পড়েনি।</p><p>সরকারি সংস্থা টিসিবি জানায়, মোটা চালের কেজি এক মাস আগেও যেখানে ৫০ টাকা ছিল, এখন তা ৫৫ টাকায় উঠেছে। মাঝারি চালের দাম বেড়ে দাঁড়িয়েছে ৬০-৬৫ টাকা, আর সরু মিনিকেট বা বাশমতিসদৃশ চালের কেজি ৭৫-৮৫ টাকা পর্যন্ত বিক্রি হচ্ছে। বাস্তব বাজারে এই দাম আরও বেশি, বিশেষ করে নিম্ন আয়ের মানুষের জন্য। রাজধানীর বিভিন্ন বাজারে খোঁজ নিয়ে দেখা গেছে, পাইজাম, বিআর-২৮, মোটা বা মাঝারি চাল কিনতে হচ্ছে ৬০-৬৫ টাকা কেজি দরে। ২৫ কেজির বস্তা কিনতে গেলে আগের চেয়ে ২০০ থেকে ৩০০ টাকা বেশি দিতে হচ্ছে।</p><p>&nbsp;</p><p>রাজধানীর কাজীপাড়ার গৃহিণী তানিয়া বেগম বলেন, ঈদের আগে যে চালের বস্তা ২ হাজার ১৫০ টাকায় পেয়েছিলেন, এখন তা কিনতে হচ্ছে ২ হাজার ৩০০ টাকায়। প্রতি কেজিতে বেড়েছে ৬ টাকার মতো। সংসারের অন্য খরচও বাড়ছে, কিন্তু আয়ের কোনো গতি নেই। এই অবস্থায় নিম্ন ও মধ্যবিত্ত মানুষের দিন চলে অনিশ্চয়তায়। শুধু শহরে নয়, জেলা শহর ও মফস্বল এলাকায়ও চালের দাম বেড়েছে উল্লেখযোগ্যভাবে। পাইকারি ও খুচরা বিক্রেতারা বলছেন, মিলগেট থেকেই চালের দাম বাড়ছে, ফলে বিক্রিও বাধ্য হয়ে বেশি দামে করতে হচ্ছে।</p><p>বোরো মৌসুমে সাধারণত চালের দাম কিছুটা কমে। কারণ এই মৌসুমেই দেশের মোট চাল উৎপাদনের অর্ধেকের বেশি হয়। কিন্তু এবার মে মাস পার না হতেই জুনেই চালের বাজার গরম হতে শুরু করে। বিশেষজ্ঞরা মনে করছেন, এই অস্বাভাবিক মূল্যবৃদ্ধির পেছনে একাধিক কারণ রয়েছে। এর মধ্যে অন্যতম হলো—চাল আমদানির শুল্ক বাড়ানো, বাজারে আমদানি কার্যক্রমের অনিশ্চয়তা, সরবরাহ ঘাটতি এবং অভ্যন্তরীণ মজুতদারদের প্রভাব।</p><p>গত বছর আগস্টে বন্যার কারণে আমন মৌসুমে উৎপাদন ব্যাহত হয়েছিল। তখন সরকার শুল্ক কমিয়ে ১০ লাখ টন চাল আমদানির অনুমতি দেয়। সেই সিদ্ধান্তের ফলেই ১৩ লাখ টন চাল আমদানি হয়, যার বেশির ভাগই আসে সরকারি উদ্যোগে। কিন্তু এরপর চাল আমদানির অনুমতি ও শুল্ক ছাড়ের মেয়াদ শেষ হয়ে যায়। ফলে এ বছর নতুন করে আমদানি কার্যক্রম বন্ধ হয়ে যায়। বর্তমানে চাল আমদানিতে মোট শুল্ক–কর দাঁড়িয়েছে প্রায় ৬৭.৫ শতাংশ, যা চালের দাম বাড়ার অন্যতম কারণ হিসেবে চিহ্নিত করছেন সংশ্লিষ্টরা।</p><p>&nbsp;</p><p>বিশ্ববাজারে চালের দাম কমেছে। যেমন, থাইল্যান্ডের চালের প্রতি টনের দাম ছিল ৫৮৬ ডলার, যা এখন নেমে এসেছে ৪১৯ ডলারে। একইভাবে ভিয়েতনামের চালের দামও কমেছে প্রায় ৩০ শতাংশ। অথচ বাংলাদেশে সেই প্রভাব পড়ছে না। কারণ, দেশীয় বাজারে আমদানির সুযোগ সীমিত। ব্যবসায়ীরা বলছেন, ভারতীয় চালের দামও তুলনামূলকভাবে কম। বর্ধমান অঞ্চল থেকে রপ্তানি হওয়া চালের কেজি ৩৪ রুপি, যা বাংলাদেশে আনতে খরচ হয় ৫৩-৫৪ টাকা। অথচ দেশে সেই চালও নেই।</p><p>আমদানিতে বাধা থাকায় দেশের ব্যবসায়ীরা নিজেদের নিয়ন্ত্রণে বাজার চালাচ্ছেন। অনেকে আগেভাগে বিপুল পরিমাণ ধান-চাল কিনে মজুত করে রেখেছেন। প্রতিযোগিতা না থাকায় দাম বাড়িয়ে বিক্রি করছেন। সরকারের একাধিক সূত্র বলছে, বাজারে স্বাভাবিক প্রতিযোগিতা ফেরাতে আমদানিকে সহজ করা ছাড়া বিকল্প নেই। অনেক অর্থনীতিবিদ মত দিচ্ছেন, অন্তত তিন মাসের জন্য চাল আমদানিতে শুল্ক তুলে নেওয়া হোক, দেখা যাক তাতে বাজারে প্রতিক্রিয়া কেমন হয়।</p><p>&nbsp;</p><p>এদিকে বাংলাদেশ ব্যাংক মুদ্রানীতির মাধ্যমে মূল্যস্ফীতি নিয়ন্ত্রণের চেষ্টা করছে। সুদের হার বাড়িয়ে বাজারে টাকা সরবরাহ কমানো হয়েছে। এতে মূল্যস্ফীতির গড় হার কিছুটা কমলেও এখনো তা ৯ শতাংশের উপরে। বিশেষজ্ঞরা বলছেন, শুধু মুদ্রানীতি দিয়ে মূল্যস্ফীতি নিয়ন্ত্রণ সম্ভব নয়। নিত্যপ্রয়োজনীয় পণ্যের সরবরাহ ও বাজার ব্যবস্থাপনা ঠিক রাখা জরুরি। বিশেষ করে চালের মতো প্রধান খাদ্যশস্যে কোনো ঘাটতি তৈরি হলে তা পুরো অর্থনীতিতে নেতিবাচক প্রভাব ফেলবে।</p><p>ঢাকা বিশ্ববিদ্যালয়ের অর্থনীতি বিভাগের অধ্যাপক সেলিম রায়হান বলেন, বাংলাদেশ এখনো চাল উৎপাদনে পুরোপুরি স্বয়ংসম্পূর্ণ নয়। তাই সঠিক সময়ে আমদানি নিশ্চিত করতে না পারলে বাজারে ঘাটতি তৈরি হয়। এ ঘাটতি সহজেই ব্যবসায়ীদের জন্য অতিরিক্ত মুনাফার সুযোগ তৈরি করে। তিনি আরও বলেন, যেহেতু এখন দেশের বাজারে চাহিদার চেয়ে সরবরাহ কম, তাই আমদানির পথ খুলে দিয়ে সেই ঘাটতি পূরণ না করলে সাধারণ মানুষ আরও বড় চাপে পড়বে।</p><p>সরকারি হিসেবে বর্তমানে খাদ্যশস্যের মজুত প্রায় ১৮ লাখ টন। এর মধ্যে ১৫ লাখ টনের বেশি চাল। তবে সেটি কতদিন চলবে বা চাহিদা মেটাতে যথেষ্ট কি না, তা নিয়ে সংশয় রয়েছে। কারণ, দেশের প্রায় ১৭ কোটি মানুষ এখনও চাল নির্ভর খাদ্যাভ্যাসে অভ্যস্ত। তাই চালের বাজারে অস্থিরতা মানেই পুরো খাদ্যপণ্যের বাজারে চাপ। বর্তমান পরিস্থিতিতে দ্রুত সিদ্ধান্ত নিতে না পারলে আগামী দিনে সংকট আরও তীব্র হতে পারে।</p><p>&nbsp;</p><p>সংক্ষেপে, বাজারে চালের দাম বৃদ্ধি শুধু একটি পণ্য সমস্যার বিষয় নয়, এটি একটি বৃহৎ অর্থনৈতিক ও সামাজিক সংকটের ইঙ্গিত দিচ্ছে। আয়-ব্যয়ের ভারসাম্য হারিয়ে ফেলছে সাধারণ মানুষ। চালের দাম নিয়ন্ত্রণে কার্যকর পদক্ষেপ নেওয়া এখন সময়ের দাবি। তা না হলে মূল্যস্ফীতি নিয়ন্ত্রণ, খাদ্য নিরাপত্তা ও সামাজিক স্থিতিশীলতা—সবই হুমকির মুখে পড়বে।</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './5-20250705-101010379.webp', 50, NULL, '2025-07-07 10:10:17', '2025-07-07 10:10:17'),
(47, 'আকর্ষণীয় বেতনে এসকেএফ ফার্মায় চাকরি, অভিজ্ঞতার প্রয়োজন নেই', '', '<p><br><br><strong>চাকরি ডেস্ক</strong><br><br>এসকেএফ ফার্মাসিউটিক্যালস লিমিটেড নিয়োগ বিজ্ঞপ্তি প্রকাশ করেছে। প্রতিষ্ঠানটি মেডিকেল সার্ভিস অফিসার পদে জনবল নিয়োগের জন্য এ বিজ্ঞপ্তি দিয়েছে। গত ১৫ জুলাই থেকেই আবেদন নেওয়া শুরু হয়েছে। আবেদন করা যাবে আগামী ১৩ জুলাই পর্যন্ত। আগ্রহী প্রার্থীরা অনলাইনে আবেদন করতে পারবেন। নির্বাচিত প্রার্থীরা মাসিক বেতন ছাড়াও ত্রৈমাসিক প্রণোদনা, উৎসব বোনাস, লাভ বোনাস, প্রভিডেন্ট ফান্ড এবং গ্র্যাচুইটি, বিদেশ ভ্রমণ, গ্রুপ বীমা, টিএ এবং ডিএ, দক্ষতা বৃদ্ধি প্রশিক্ষণসহ প্রতিষ্ঠানের নীতিমালা অনুযায়ী আরো বিভিন্ন সুযোগ-সুবিধা পাবেন</p><p><br>এক নজরে এসকেএফ ফার্মায় নিয়োগ বিজ্ঞপ্তি ২০২৫<br>প্রতিষ্ঠানের নাম<br>এসকেএফ ফার্মাসিউটিক্যালস লিমিটেড<br>চাকরির ধরন<br>বেসরকারি চাকরি<br>প্রকাশের তারিখ<br>০৬ জুলাই ২০২৫<br>পদ ও লোকবল<br>নির্ধারিত নয়&nbsp;<br><br>আবেদন করার মাধ্যম<br>অনলাইন<br>আবেদন শুরুর তারিখ<br>০৬ জুলাই ২০২৫<br>আবেদনের শেষ তারিখ<br>২৭ জুলাই ২০২৫<br>অফিশিয়াল ওয়েবসাইট &gt; <a style=\"--tw-backdrop-blur:;--tw-backdrop-brightness:;--tw-backdrop-contrast:;--tw-backdrop-grayscale:;--tw-backdrop-hue-rotate:;--tw-backdrop-invert:;--tw-backdrop-opacity:;--tw-backdrop-saturate:;--tw-backdrop-sepia:;--tw-blur:;--tw-border-opacity:1;--tw-border-spacing-x:0;--tw-border-spacing-y:0;--tw-brightness:;--tw-contain-layout:;--tw-contain-paint:;--tw-contain-size:;--tw-contain-style:;--tw-contrast:;--tw-drop-shadow:;--tw-gradient-from-position:;--tw-gradient-to-position:;--tw-gradient-via-position:;--tw-grayscale:;--tw-hue-rotate:;--tw-invert:;--tw-numeric-figure:;--tw-numeric-fraction:;--tw-numeric-spacing:;--tw-ordinal:;--tw-pan-x:;--tw-pan-y:;--tw-pinch-zoom:;--tw-ring-color:rgb(59 130 246/0.5);--tw-ring-inset:;--tw-ring-offset-color:#fff;--tw-ring-offset-shadow:0 0 #0000;--tw-ring-offset-width:0px;--tw-ring-shadow:0 0 #0000;--tw-rotate:0;--tw-saturate:;--tw-scale-x:1;--tw-scale-y:1;--tw-scroll-snap-strictness:proximity;--tw-sepia:;--tw-shadow-colored:0 0 #0000;--tw-shadow:0 0 #0000;--tw-skew-x:0;--tw-skew-y:0;--tw-slashed-zero:;--tw-translate-x:0;--tw-translate-y:0;-webkit-text-stroke-width:0px;background-color:rgb(239, 243, 246);border-bottom-width:1px;border-color:rgb(107, 114, 128);border-image:initial;border-left-width:0px;border-right-width:0px;border-style:solid;border-top-width:0px;box-sizing:border-box;color:inherit;font-family:SolaimanLipi, &quot;SolaimanLipi Fallback&quot;;font-size:21.008px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration:inherit;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\" href=\"https://www.skfbd.com/\" title=\"https://www.skfbd.com/\" target=\"_blank\" rel=\"nofollow noopener\">https://www.skfbd.com</a><br><br>আবেদন করার লিংক<br>অফিশিয়াল নোটিশের নিচে<br>প্রতিষ্ঠানের নাম: এসকেএফ ফার্মাসিউটিক্যালস লিমিটেড<br>পদের নাম: মেডিকেল সার্ভিস অফিসার<br>পদসংখ্যা: নির্ধারিত নয়</p><p><br>অন্যান্য যোগ্যতা: মার্কেটিংয়ে দক্ষতা&nbsp;<br>অভিজ্ঞতা: প্রয়োজন নেই</p><p><br>চাকরির ধরন: ফুলটাইম<br>কর্মক্ষেত্র: অফিসে&nbsp;<br>প্রার্থীর ধরন: নারী-পুরুষ (উভয়)<br>বয়সসীমা: সর্বোচ্চ ৩২ বছর</p><p>কর্মস্থল: দেশের যেকোনো স্থানে&nbsp;<br>বেতন: আকর্ষণীয় বেতন<br>অন্যান্য সুবিধা: ত্রৈমাসিক প্রণোদনা, উৎসব বোনাস, লাভ বোনাস, প্রভিডেন্ট ফান্ড এবং গ্র্যাচুইটি, বিদেশ ভ্রমণ, গ্রুপ বীমা, টিএ এবং ডিএ, দক্ষতা বৃদ্ধি প্রশিক্ষণ।</p><p>আবেদন যেভাবে: আগ্রহী প্রার্থীরা আবেদন করতে ও বিস্তারিত বিজ্ঞপ্তিটি দেখতে এখানে <a href=\"https://jobs.bdjobs.com/jobdetails/?id=1381989&amp;ln=1&amp;AspxAutoDetectCookieSupport=1\">https://jobs.bdjobs.com/jobdetails/?id=1381989&amp;ln=1&amp;AspxAutoDetectCookieSupport=1</a> &nbsp;ক্লিক করুন।&nbsp;<br>আবেদনের শেষ সময়: ১৩ জুলাই ২০২৫</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './job-eskayef-pharma-20250705142057.webp', 79, NULL, '2025-07-07 10:14:45', '2025-07-07 10:14:45'),
(48, 'ঢাকা বিশ্ববিদ্যালয়ে চাকরির সুযোগ', 'ঢাকা বিশ্ববিদ্যালয়ে ইন্টারন্যাশনাল বিজনেস বিভাগে শিক্ষক নিয়োগের জন্য বিজ্ঞপ্তি প্রকাশ করা হয়েছে। আগ্রহী প্রার্থীদের বিশ্ববিদ্যালয়ের নির্ধারিত ফরমে আবেদন করতে হবে।', '<p><br><strong>চাকরি &nbsp;ডেস্ক:</strong><br>&nbsp;</p><p>ঢাকা বিশ্ববিদ্যালয়ে ইন্টারন্যাশনাল বিজনেস বিভাগে শিক্ষক নিয়োগের জন্য বিজ্ঞপ্তি প্রকাশ করা হয়েছে। আগ্রহী প্রার্থীদের বিশ্ববিদ্যালয়ের নির্ধারিত ফরমে আবেদন করতে হবে।</p><p>পদের নাম: অধ্যাপক<br>বিভাগ: ইন্টারন্যাশনাল বিজনেস<br>পদসংখ্যা: ১<br>শিক্ষাগত যোগ্যতা: প্রার্থীদের স্বনামধন্য বিশ্ববিদ্যালয় থেকে ইন্টারন্যাশনাল বিজনেস অথবা সংশ্লিষ্ট বিষয়ে (ম্যানেজমেন্ট ইনফরমেশন সিস্টেমস, অ্যাকাউন্টিং অ্যান্ড ইনফরমেশন সিস্টেমস ও মার্কেটিং) উচ্চতর শিক্ষাগত যোগ্যতাসহ পিএইচডি ডিগ্রি থাকতে হবে। বিশ্ববিদ্যালয়ে কমপক্ষে ১২ বছরের শিক্ষকতার অভিজ্ঞতা থাকতে হবে। এর মধ্যে কমপক্ষে সাত বছর ইন্টারন্যাশনাল বিজনেস বিভাগে সহকারী অধ্যাপক ও সহযোগী অধ্যাপক হিসেবে শিক্ষাদানের অভিজ্ঞতা থাকতে হবে। প্রার্থীদের ইনডেক্সড/ডিওআই (ডিজিটাল অবজেক্ট আইডেন্টিফায়ার) সংবলিত মানসম্মত জার্নালে কমপক্ষে ১২টি গবেষণা প্রকাশনা থাকতে হবে। শিক্ষক হিসেবে অভিজ্ঞতা ও দক্ষতা এবং বিশ্ববিদ্যালয়ের অন্যান্য ক্ষেত্রে, বিশেষ করে ছাত্রছাত্রীদের সামগ্রিক শিক্ষা ও শিক্ষা আনুষঙ্গিক কর্মকাণ্ড পরিচালনায় বিশেষ অবদানও যোগ্যতা হিসেবে গণ্য করা হবে। বিভাগের অভ্যন্তরীণ পিএইচডি ডিগ্রিধারী প্রার্থীদের অগ্রাধিকার দেওয়া যেতে পারে।<br>বেতন স্কেল: ৫৬,৫০০-৭৪,৪০০ টাকা</p><p><br>যেভাবে আবেদন<br>সার্টিফিকেট, মার্কশিট, প্রশংসাপত্র ও অভিজ্ঞতার প্রমাণপত্রের সত্যায়িত প্রতিলিপিসহ ১১ কপি দরখাস্ত পাঠাতে হবে।</p><p>আবেদন ফি<br>রেজিস্ট্রারের অনুকূলে এক হাজার টাকা মূল্যের পে-অর্ডার/ব্যাংক ড্রাফট পাঠাতে হবে।</p><p>আবেদনপত্র পাঠানোর ঠিকানা<br>রেজিস্ট্রার, ঢাকা বিশ্ববিদ্যালয়, ঢাকা-১০০০।</p><p>আবেদনের শেষ সময়<br>৩১ আগস্ট ২০২৫।</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './job-technonex-20250705142821.webp', 73, NULL, '2025-07-07 10:20:07', '2025-07-07 10:20:07'),
(49, 'এক লাখ শিক্ষক নিয়োগে আবেদন শুরু, ফি ১০০০ টাকা', 'বেসরকারি শিক্ষক নিবন্ধন ও প্রত্যয়ন কর্তৃপক্ষের (এনটিআরসিএ) অধীন এমপিওভুক্ত বেসরকারি মাধ্যমিক বিদ্যালয়, কলেজ, মাদ্রাসা, কারিগরি ও ব্যবসায় ব্যবস্থাপনা শিক্ষাপ্রতিষ্ঠানে ১ লাখ ৮২২ জন শিক্ষক নিয়োগে আবেদন শুরু হয়েছে।', '<p><br><strong>চাকরি ডেস্ক:</strong></p><p><br>বেসরকারি শিক্ষক নিবন্ধন ও প্রত্যয়ন কর্তৃপক্ষের (এনটিআরসিএ) অধীন এমপিওভুক্ত বেসরকারি মাধ্যমিক বিদ্যালয়, কলেজ, মাদ্রাসা, কারিগরি ও ব্যবসায় ব্যবস্থাপনা শিক্ষাপ্রতিষ্ঠানে ১ লাখ ৮২২ জন শিক্ষক নিয়োগে আবেদন শুরু হয়েছে।</p><p>গতকাল শনিবার দুপুর ১২টায় আবেদন শুরু হয়। আবেদনের শেষ সময় আগামী ১৩ জুলাই। আবেদনকারীর বয়স ৪ জুন তারিখে সর্বোচ্চ ৩৫ বছর।</p><p>আবেদন ফি এক হাজার টাকা। একজন প্রার্থী শূন্যপদের তালিকা থেকে সর্বোচ্চ ৪০টি শিক্ষাপ্রতিষ্ঠানের পছন্দ দিতে পারবেন। মাধ্যমিক ও উচ্চশিক্ষা বিভাগ, শিক্ষা মন্ত্রণালয়ের বিজ্ঞপ্তি অনুসারে কোনো নারী কোটা থাকবে না।</p><p><br>১ লাখ ৮২২ জনের মধ্যে স্কুল ও কলেজে নেওয়া হবে ৪৬ হাজার ২১১ জন, মাদ্রাসায় ৫৩ হাজার ৫০১ জন এবং কারিগরি ও ব্যবসায় ব্যবস্থাপনা প্রতিষ্ঠানে নেওয়া হবে ১ হাজার ১১০ জন।</p><p>যেভাবে আবেদন<br>অনলাইনে আবেদন ফি দেওয়া–সংক্রান্ত নিয়ম টেলিটক বাংলাদেশ লিমিটেডের ওয়েবসাইট এবং এনটিআরসিএর ওয়েবসাইটে দেওয়া হয়েছে। আবেদন এবং ফি দেওয়ার নিয়মের বিষয়ে ভিডিও টিউটোরিয়াল নমুনা (ডেমো) টেলিটক বাংলাদেশ লিমিটেডের ওয়েবসাইটে পাওয়া যাবে।</p><p>প্রত্যেক আবেদনকারী ভিন্ন ভিন্ন নিবন্ধন পরীক্ষায় অর্জিত একাধিক নিবন্ধন সনদপ্রাপ্ত হলেও একই পর্যায় একটিমাত্র সনদ দিয়ে আবেদন করতে পারবেন।</p><p>আবেদনকারীর যোগ্যতা<br>সংশ্লিষ্ট বিষয়, পদ ও প্রতিষ্ঠানের ধরন অনুযায়ী নিবন্ধন সনদধারী হতে হবে। এনটিআরসিএ কর্তৃক প্রকাশিত সম্মিলিত মেধাতালিকার অন্তর্ভুক্ত এবং বেসরকারি শিক্ষক নিবন্ধন পরীক্ষা গ্রহণ ও প্রত্যয়ন বিধিমালা, ২০০৬ (সংশোধিত ২০১৫)–এর বিধি ১০ (১) মোতাবেক বৈধ নিবন্ধন সনদধারী হতে হবে।</p><p>মাধ্যমিক ও উচ্চশিক্ষা বিভাগ এবং কারিগরি ও মাদ্রাসা শিক্ষা বিভাগ থেকে জারিকৃত সর্বশেষ জনবলকাঠামো ও এমপিও নীতিমালা অনুযায়ী কাম্য শিক্ষাগত যোগ্যতাসম্পন্ন হতে হবে। কাম্য শিক্ষা যোগ্যতার বিবরণ এনটিআরসিএর ওয়েবসাইটের ‘৬ষ্ঠ নিয়োগ সুপারিশ বিজ্ঞপ্তি’ নামের সেবা বক্সে পাওয়া যাবে।</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './screenshot-2025-07-07-062154.webp', 84, NULL, '2025-07-07 10:23:41', '2025-07-07 10:23:41'),
(50, 'ফলভর্তি বাগানে সুখ খুঁজে পেলেন জয়া আহসান', '', '<p><br><strong>বিনোদন ডেস্ক</strong><br><br>ঢালিউড কিংবা টলিউড— এখন দুই বাংলাতেই সমানতালে কাজ করে যাচ্ছেন নন্দিত অভিনেত্রী জয়া আহসান। কখনো কলকাতা, আবার কখনো ঢাকা— সিনেমার প্রচার ও শুটিং নিয়েই দৌড়াদৌড়ি তার</p><p><br>তবে কাজের ব্যস্ততার ফাঁকেও মাটির সঙ্গে মিশতে ভালোবাসেন এই অভিনেত্রী; তা জানান দিয়েছেন বহুবার। কখনো নানা জাতের সবজি চাষ করছেন, আবার কখনও ফল! বলা বাহুল্য, অভিনয়ের পাশাপাশি বাগান কিংবা কৃষিকাজ তার যেন অন্যতম প্রিয় শখ।</p><p>নিজের জন্য একটি ছোট্ট ফার্ম করেছেন জয়া আহসান; প্রায়ই সেখান থেকে ধরা দেন অভিনেত্রী। রোববার সামাজিক মাধ্যমে নিজের সেই ফার্ম হাউজের কিছু ছবি ভাগ করে নিলেন অনুরাগীদের মাঝে। তাতে দেখা যায়, পেঁপে, পিচফল এর মতো গাছ ও তার ব্যাপক ফলন!</p><p><br>দেখা যায়, পেঁপের গাছের পাশে সবুজ পোশাকে হাস্যোজ্জ্বল অবস্থায় দেখা যায় জয়াকে। আর থেকে দেখে মুগ্ধ ভক্তরাও। ক্যাপশনে অভিনেত্রী লেখেন, ‘আমার জীবনের লক্ষ্য; আমার ছোট্ট ফার্ম নিয়েই আমি সুখী!’<br>উল্লেখ্য, কলকাতায় ‘ডিয়ার মা’ ছবির প্রচারণা ও ‘আজও অর্ধাঙ্গিনী’র শুটিং শেষে সদ্যই দেশে ফিরেছেন এই অভিনেত্রী। এসেই খামারে সময় কাটাতে দেখা গেল তাকে। অন্যদিকে কিছু প্রেক্ষাগৃহে একযোগে চলছে জয়া আহসানের দুটি ছবি—‘তাণ্ডব’ ও ‘উৎসব’। দুটি চলচ্চিত্রেই রয়েছে তার প্রশংসনীয় অভিনয়।&nbsp;</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './০১-1.webp', 78, NULL, '2025-07-07 10:26:54', '2025-07-07 10:26:54'),
(51, '‘আমারটা ক্যানসেল করিয়ে আমার সহকর্মী দুটি অ্যাওয়ার্ড নেন’', 'নিউ ইয়র্কে টকশো নিয়ে হাজির হয়েছেন আলোচিত চিত্রনায়ক জায়েদ খান; সেখানেই প্রথম অতিথি হিসেবে অভিনেত্রী তানজিন তিশাকে নিয়ে হাজির হন জায়েদ। যেখানে অভিনেত্রী তার ক্যারিয়ার, ব্যক্তিগত জীবন নিয়ে নানা আলোচনা করেন।', '<p><strong>বিনোদন ডেস্ক</strong></p><p><br>নিউ ইয়র্কে টকশো নিয়ে হাজির হয়েছেন আলোচিত চিত্রনায়ক জায়েদ খান; সেখানেই প্রথম অতিথি হিসেবে অভিনেত্রী তানজিন তিশাকে নিয়ে হাজির হন জায়েদ। যেখানে অভিনেত্রী তার ক্যারিয়ার, ব্যক্তিগত জীবন নিয়ে নানা আলোচনা করেন।</p><p><br>সেখানে এক পর্যায়ে জায়েদ খান তাকে প্রশ্ন করেন, ‘কোনো সহকর্মীর আচরণে তুমি মর্মাহত হয়েছিলে?’—উত্তরে তানজিন তিশা বলেন,‘আমার এক সিনিয়র সহকর্মী কোনো একটা অ্যাওয়ার্ড অনুষ্ঠানের দিনে বলেছে, ও (তানজিন তিশা) যদি অ্যাওয়ার্ডটা নেয় তাহলে আমি (সহকর্মী) অ্যাওয়ার্ড নেব না। মানে আমি অ্যাওয়ার্ড নিলে তিনি নেবেন না।’</p><p>তানজিন তিশা বলেন, ‘এটা নিয়ে আগে কখনো বলিনি, প্রথমবারের মতো বিষয়টা নিয়ে বলছি। মানে আমি অ্যাওয়ার্ড নিলে তিনি নেবেন না। এরপর তিনি আমার অ্যাওয়ার্ডটা ক্যানসেল করিয়েছেন। অনুষ্ঠানের দিন আমাকে ফোন করে জানানো হয় যে, তুমি অ্যাওয়ার্ড পাচ্ছ না। এরপর দেখি, ওই দুইটা অ্যাওয়ার্ডটাই তিনি নিয়েছে।’</p><p>&nbsp;</p><p>তানজিন তিশা আরও বলেন, ‘হয়তো তিনি ডিজার্ভ করে- তিনি দুইটা অ্যাওয়ার্ডই পাবেন, এটা চিন্তা করেছেন বলে নিয়েছে। আমি প্রত্যেকটি কো-আর্টিস্ট, কলিগদের ভালো জানি; ভালো জানতে চাই। এটা না যে আমি ওপর দিয়ে বলছি, তুমি আমার ভালো বন্ধু, আমি যেটা মনে করি, সেটা আমার চেহারাতেই বোঝা যায়। সে জায়গা থেকে আমি শকড, তবে ঠিক আছে। তিনি মনে করেছে দুটি অ্যাওয়ার্ড তার প্রাপ্য, ভালো তো!’</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './০২.webp', 80, NULL, '2025-07-07 10:30:05', '2025-07-07 10:30:05'),
(52, 'বিমানবন্দরে অঝোরে কাঁদলেন নোরা, কারণ কী', '', '<p><br><strong>বিনোদন ডেস্ক</strong><br><br>পরনে কালো প্যান্ট ও কালো লম্বা হাতা জ্যাকেট। খোলা চুল। চোখে কালো রঙের সানগ্লাস। হাতে ছিল ব্যাগ। মুম্বাই বিমানবন্দরে গাড়ি থেকে এমন বেশেই নামেন বলিউডের জনপ্রিয় অভিনেত্রী ও নৃত্যশিল্পী নোরা ফাতেহি। কিন্তু চোখে কালো চশমা পরে থাকলেও তিনি লুকিয়ে রাখতে পারেননি তার অশ্রু। বিমানবন্দরে অঝোরে কাঁদলেন এই অভিনেত্রী।<br>&nbsp;রোববার ভারতীয় সংবাদ মাধ্যম আনন্দবাজারের এক প্রতিবেদনে বিষয়টি উঠে এসেছে। তবে ঘটনাটি কবেকার তা প্রতিবেদনে উল্লেখ করা হয়নি।</p><p>প্রতিবেদনে বলা হয়, কাঁদতে কাঁদতে বিমানবন্দরে প্রবেশ করতে দেখা যায় নোরাকে। চোখ ঢাকা থাকলেও তার মুখের অভিব্যক্তি স্পষ্ট বলে দেয়, মন ভালো নেই অভিনেত্রীর। অঝোরে কাঁদতে কাঁদতেই প্রবেশ করছেন তিনি। পেছনে ছিলেন তার দেহরক্ষী।<br>নোরাকে দেখেই ছুটে আসেন ফটোগ্রাফাররা ও কয়েকজন অনুরাগী। বিমানবন্দরে প্রবেশ করার সময়ে এক অনুরাগী নোরার সঙ্গে সেলফি তোলার জন্য অনেকটা এগিয়ে যান। সেই সময়ে সঙ্গে সঙ্গে তাকে ধাক্কা দিয়ে সরিয়ে দেন দেহরক্ষী। দেহরক্ষীর অভিব্যক্তিও স্পষ্ট বলে দেয়, নোরার মন ভালো নেই। কিন্তু ঠিক কী কারণে অভিনেত্রী কাঁদছেন, তা অবশ্য জানা যায়নি। যদিও অনুরাগীদের অনুমান, কাছের কোনো মানুষকে হারিয়েছেন অভিনেত্রী</p><p><br>এদিকে বিমানবন্দরে আসার এক ঘণ্টা আগেই নোরা তার সামাজিক মাধ্যমে লিখেছিলেন, ‘ইন্না ইল্লাহি ওয়া ইন্না ইলাহি রাজিউন।’ কারও মৃত্যুর খবরে ইসলাম ধর্মাবলম্বীরা এটি বলে থাকেন।</p><p>কয়েক মাস আগেই মুক্তি পেয়েছে নোরার ওয়েব সিরিজ ‘দ্য রয়্যালস্‌’। সিরিজে অভিনেত্রীর সঙ্গে দেখা গেছে ঈশান খট্টর, ভূমি পেডনেকর, জিনাত আমান, সাক্ষী তনওয়ার ও দিনো মোরিয়াকেও। ঈশান খট্টরের প্রাক্তন প্রেমিকা আয়েশার চরিত্রে অভিনয় করেন নোরা।</p>', 'published', NULL, 'Botble\\Member\\Models\\Member', 0, './০৩.webp', 76, NULL, '2025-07-07 10:32:33', '2025-07-07 10:36:06'),
(53, 'মুখ ঢেকে বাজারে গিয়ে বলি, ‘এটার দাম কত’', 'দীর্ঘ এক যুগ ধরে শোবিজে সাফল্যের সঙ্গে কাজ করে যাচ্ছেন অভিনেত্রী ও মডেল মৌসুমী হামিদ। নাটক, সিনেমা ও ওটিটি—তিনটি মাধ্যমেই দর্শকদের কাছে সমানভাবে জনপ্রিয়তা পেয়েছেন; ভিন্ন ভিন্ন চরিত্রে অভিনয়ের মাধ্যমে নিজের অভিনয় দক্ষতা দেখিয়েছেন মৌসুমী।\nসম্প্রতি মৌসুমী অভিনয় করেছেন নির্মাতা অমিতাভ রেজা চৌধুরীর পরিচালনায় নির্মিত নতুন ওয়েব সিরিজ ‘বোহেমিয়ান ঘোড়া’-তে। এছাড়া আসন্ন দুর্গাপূজায় মুক্তি পাচ্ছে', '<p><br><strong>বিনোদন ডেস্ক</strong><br><br>দীর্ঘ এক যুগ ধরে শোবিজে সাফল্যের সঙ্গে কাজ করে যাচ্ছেন অভিনেত্রী ও মডেল মৌসুমী হামিদ। নাটক, সিনেমা ও ওটিটি—তিনটি মাধ্যমেই দর্শকদের কাছে সমানভাবে জনপ্রিয়তা পেয়েছেন; ভিন্ন ভিন্ন চরিত্রে অভিনয়ের মাধ্যমে নিজের অভিনয় দক্ষতা দেখিয়েছেন মৌসুমী।<br>সম্প্রতি মৌসুমী অভিনয় করেছেন নির্মাতা অমিতাভ রেজা চৌধুরীর পরিচালনায় নির্মিত নতুন ওয়েব সিরিজ ‘বোহেমিয়ান ঘোড়া’-তে। এছাড়া আসন্ন দুর্গাপূজায় মুক্তি পাচ্ছে তার নতুন চলচ্চিত্র ‘রঙবাজার’, যেখানে যৌনপল্লীর প্রেক্ষাপটে গড়ে ওঠা একটি গল্পে অভিনয় করেছেন তিনি।</p><p>মৌসুমীর অভিনয় জীবনের পাশাপাশি ব্যক্তিগত জীবন নিয়েও ভক্তদের কৌতূহলের শেষ নেই। সম্প্রতি এক সাক্ষাৎকারে অভিনেত্রী জানান, তিনি সাধারণ বাজার থেকেই কেনাকাটা করতে পছন্দ করেন। শপিং মল নয়, বরং কাঁচাবাজারই তার পছন্দের জায়গা। সময় সুযোগ পেলেই স্বামীর সঙ্গে বাজারে যান তিনি।<br>বাজারে নিয়ে গেলে তার স্বামী তাকে কি কিনে দেয়, সে প্রসঙ্গে অভিনেত্রী মজার ছলেই বলেন, ‘এইতো- আলু, পেঁয়াজ, মাছ, মুরগি।’ আরও জানান, মৌসুমী নিজেও নাকি বাজারে যেয়ে কেনেন এসব।<br>কথা প্রসঙ্গে মৌসুমী হামিদ এও বলেন, ‘দামাদামিটা আমি কম জানি, তোমাদের ভাইয়া বার্গেইনটা বেশিই জানে। ৫০০ টাকার কোনোকিছু ৫০ টাকা বলবে।’</p><p>ভ্যান কিংবা ফুটপাতের মতো জায়গা থেকেও কেনাকাটা করেছেন মৌসুমী হামিদ। সেখান থেকে কীভাবে কেনেন, সে প্রসঙ্গে অভিনেত্রী বলেন, ‘মুখ-টুখ বেঁধে, মাস্ক পড়ে, হিজাব বেঁধে একদম খালাদের মতো বলি- মামা এইডা কয় টাকা। যদি বলে ৫০০, তখন বলি ২০০-৩০০। কিন্তু খুব বেশি ওইটা (দামাদামি) পারি না, অল্প অল্প; যতটুকু পারি, ইদানিং শিখতেছি আরকি।’</p><p>সঙ্গে এও জানান, অল্প দামে অনেক সুন্দর সুন্দর জিনিস পাওয়া যায়, আর সেগুলো কেনাও হয়েছে।</p><p>&nbsp;</p><p>উল্লেখ্য, মৌসুমী হামিদ ২০১০ সালে লাক্স-চ্যানেল আই সুপারস্টারে রানার্সআপ হওয়ার পর থেকেই টিভি নাটক ও বিভিন্ন অনুষ্ঠানে নিয়মিত কাজ করছেন। খালিদ মাহমুদ মিঠুর নাটক ‘বাংলা আমার মাতৃভাষা’-তে প্রথম অভিনয় করলেও, মোস্তফা কামাল রাজ পরিচালিত ‘বিয়োগফল’ নাটকের মাধ্যমে ছোটপর্দায় মূলধারায় যাত্রা শুরু করেন এই অভিনেত্রী।</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './০৪.webp', 75, NULL, '2025-07-07 10:35:40', '2025-07-07 10:35:40'),
(54, 'সুষ্ঠু ও গ্রহণযোগ্য নির্বাচনের মাধ্যমেই দেশ সঠিক পথে অগ্রসর হবে: মির্জা ফখরুল', 'একটি সুষ্ঠু ও গ্রহণযোগ্য নির্বাচনের মাধ্যমেই দেশ সঠিক পথে অগ্রসর হবে বলে মন্তব্য করেছেন বিএনপির মহাসচিব মির্জা ফখরুল ইসলাম আলমগীর। তিনি বলেছেন, ‘আমাদের প্রত্যাশা—অন্তবর্তীকালীন সরকার আগামী বছরের ফেব্রুয়ারিতেই নির্বাচন আয়োজন করবে। একটি সুষ্ঠু ও গ্রহণযোগ্য নির্বাচনের মাধ্যমেই দেশ সঠিক পথে অগ্রসর হবে।’', '<p><strong>সিলেট ব্যুরো</strong></p><p><br>একটি সুষ্ঠু ও গ্রহণযোগ্য নির্বাচনের মাধ্যমেই দেশ সঠিক পথে অগ্রসর হবে বলে মন্তব্য করেছেন বিএনপির মহাসচিব মির্জা ফখরুল ইসলাম আলমগীর। তিনি বলেছেন, ‘আমাদের প্রত্যাশা—অন্তবর্তীকালীন সরকার আগামী বছরের ফেব্রুয়ারিতেই নির্বাচন আয়োজন করবে। একটি সুষ্ঠু ও গ্রহণযোগ্য নির্বাচনের মাধ্যমেই দেশ সঠিক পথে অগ্রসর হবে।’</p><p>সোমবার সকাল সাড়ে ১০টার দিকে সিলেটে হযরত শাহজালাল (রহ.) ও হযরত শাহপরান (রহ.)-এর মাজার জিয়ারত শেষে সাংবাদিকদের প্রশ্নের জবাবে এ কথা বলেন তিনি।</p><p>এর আগে সকাল ৯টা ২৫ মিনিটে একটি ফ্লাইটে বিএনপি মহাসচিব সিলেট ওসমানী আন্তর্জাতিক বিমানবন্দরে এসে পৌঁছান। সেখানে তাকে অভ্যর্থনা জানান সিলেট বিএনপি নেতৃবৃন্দ।</p><p>এদিকে বিএনপির মহাসচিব দুপুরে নগরীর পাঠানটুলা এলাকার সানরাইজ কমিউনিটি সেন্টারে খালেদা জিয়ার রোগমুক্তি কামনায় দোয়া মাহফিলে ও বিকেলে বিশেষ স্মরণ ও সম্মাননা অনুষ্ঠানে বক্তব্য দেবেন।</p><p>বিএনপি মহাসচিবের সঙ্গে রয়েছেন দলের স্থায়ী কমিটির সদস্য মির্জা আব্বাস, ডা. এ জেড এম জাহিদ হোসেন, ইকবাল মাহমুদ টুকু, চেয়ারপারসনের উপদেষ্টা হাবিবুর রহমান হাবিব ও ঢাকা জেলা বিএনপির সাধারণ সম্পাদক অ্যাডভোকেট নিপুণ রায় চৌধুরী প্রমুখ।</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './s-2-4-1751869654.webp', 61, NULL, '2025-07-07 16:41:05', '2025-07-07 16:41:05'),
(55, 'বন্দরে নৌপরিবহন উপদেষ্টাকে অবাঞ্ছিতের ঘোষণায় শোকজ, পরে ক্ষমা প্রার্থনা', '+\nনৌপরিবহন মন্ত্রণালয়ের উপদেষ্টা ব্রিগেডিয়ার জেনারেল (অব.) এম সাখাওয়াত হোসেনকে চট্টগ্রাম বন্দরে অবাঞ্ছিত করার ঘোষণা দেওয়ার পর ক্ষমা চেয়েছেন সাবেক সিবিএ নেতা হুমায়ুন কবীর।', '<p><br>+<br>নৌপরিবহন মন্ত্রণালয়ের উপদেষ্টা ব্রিগেডিয়ার জেনারেল (অব.) এম সাখাওয়াত হোসেনকে চট্টগ্রাম বন্দরে অবাঞ্ছিত করার ঘোষণা দেওয়ার পর ক্ষমা চেয়েছেন সাবেক সিবিএ নেতা হুমায়ুন কবীর।</p><p>নিউমুরিং কনটেইনার টার্মিনালের (এনসিটি) বিষয়ে মন্ত্রণালয়ের সিদ্ধান্তে ক্ষুদ্ধ হয়ে গত ২৮ জুন চট্টগ্রাম বন্দর অকশন শেড সংলগ্ন শ্রমিক দলের কার্যালয়ে এক কর্মীসভায় ওই সাবেক সিবিএ নেতা উপদেষ্টাকে নিয়ে এমন অসৌজন্যমূলক বক্তব্য দেন। তবে পরে এমন বক্তব্য ভুলবশত, অনিচ্ছাকৃত এবং অজ্ঞতাবশত বলে উল্লেখ করেন তিনি। এমন অসৌজন্যমূলক বক্তব্য প্রত্যাহার করে উপদেষ্টার কাছে এক কারণ দর্শানো নোটিশের জবাবে ক্ষমা প্রার্থনা করেন হুমায়ুন কবীর।</p><p>ওই সাবেক সিবিএ নেতার এমন বক্তব্যের কারণ জানতে চেয়ে গত ১ জুলাই &nbsp;কারণ দর্শানো নোটিশ ইস্যু করে বন্দর কর্তৃপক্ষ। চিঠিতে ৩ কর্মদিবসের মধ্যে লিখিতভাবে তাকে এর উত্তর জানানোর জন্য নির্দেশ দেওয়া হয়। পরে নোটিশের জবাবে হুমায়ুন কবীর ক্ষমা প্রার্থনা করেন।</p><p>মো. হুমায়ুন কবীর চট্টগ্রাম বন্দরের অভ্যন্তরীণ নিরীক্ষা ও পরিদর্শন বিভাগের সুপারিন্টেনডেন্ট অডিট হিসেবে কর্মরত। তিনি চট্টগ্রাম বন্দর জাতীয়তাবাদী শ্রমিক দলের (সাবেক সিবিএ) প্রচার ও প্রকাশনা সম্পাদক। এনসিটি বিদেশিদের কাছে ইজারা দেওয়ার সিদ্ধান্তের বিরুদ্ধে তার নেতৃত্বে দীর্ঘদিন আন্দোলন কর্মসূচি পালন করছে চট্টগ্রাম বন্দর জাতীয়তাবাদী শ্রমিক দল। সর্বশেষ এক কর্মসূচিতে উপদেষ্টাকে নিয়ে বক্তব্যের মাধ্যমে নতুন করে আলোচনায় আসেন তিনি।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, './ctg-1751847686.webp', 49, NULL, '2025-07-07 16:43:38', '2025-07-07 16:43:38'),
(56, 'লোহাগাড়ায় ১১ মৃত্যু: তিন মাস পর ধরা পড়লেন বাস চালক', '-কক্সবাজার মহাসড়কের লোহাগাড়ার চুনতিতে ১১ জনের প্রাণহানির ঘটনায় দুর্ঘটনায় পড়া বাসের চালককে গ্রেপ্তার করেছে র‌্যাব।\n\nরোববার রাতে ঢাকার আনসার ক্যাম্প এলাকা থেকে ২৭ বছর বয়সী সোহেল তালুকদারকে গ্রেপ্তার করা হয়।', '<p>-কক্সবাজার মহাসড়কের লোহাগাড়ার চুনতিতে ১১ জনের প্রাণহানির ঘটনায় দুর্ঘটনায় পড়া বাসের চালককে গ্রেপ্তার করেছে র‌্যাব।</p><p>রোববার রাতে ঢাকার আনসার ক্যাম্প এলাকা থেকে ২৭ বছর বয়সী সোহেল তালুকদারকে গ্রেপ্তার করা হয়।</p><p>সোহেল ঢাকার দক্ষিণ খান এলাকার হানিফের ছেলে।<br>র‌্যাব-৭ এর সিনিয়র সহকারী পুলিশ সুপার এ আর এম মোজাফ্ফর হোসেন জানান,দুর্ঘটনার পর থেকে বাস চালক সোহেল ঢাকায় পালিয়ে আত্মগোপনে ছিলেন।</p><p>গত ২ এপ্রিল সকালে চট্টগ্রাম-কক্সবাজার মহাসড়কের লোহাগাড়া উপজেলার চুনতিতে কক্সবাজারমুখী মাইক্রোবাসের সঙ্গে বিপরীত দিক থেকে আসা বাসের সংঘর্ষ হয়।<br>তাতে ঘটনাস্থলেই মাইক্রোবাসের ১০ যাত্রী নিহত হন। পরে হাসপাতালে আরেকজন মারা যান। ঘটনার পরপরই রিল্যাক্স পরিহনের চালক সোহেল পালিয়ে যান।</p><p>এ ঘটনায় নিহত রফিকুল ইসলামের শ্যালক রবিউল হোসাইন বাদী হয়ে লোহাগাড়া থানায় অচেনা ব্যক্তিদের আসামি করে একটি মামলা করেন।</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './06-1.webp', 48, NULL, '2025-07-07 16:48:22', '2025-07-07 16:48:22'),
(57, 'এসএসসি পরীক্ষার ফল ১০ জুলাই', 'সোমবার (৭ জুলাই) সকালে আন্তঃশিক্ষা বোর্ড পরীক্ষা নিয়ন্ত্রক কমিটির আহ্বায়ক অধ্যাপক এস এম কামাল উদ্দিন হায়দার এ তথ্য নিশ্চিত করেছেন।\n\nআন্তঃশিক্ষা বোর্ড সমন্বয় কমিটির তথ্যমতে', '<p>&nbsp;</p><p>সোমবার (৭ জুলাই) সকালে আন্তঃশিক্ষা বোর্ড পরীক্ষা নিয়ন্ত্রক কমিটির আহ্বায়ক অধ্যাপক এস এম কামাল উদ্দিন হায়দার এ তথ্য নিশ্চিত করেছেন।</p><p>আন্তঃশিক্ষা বোর্ড সমন্বয় কমিটির তথ্যমতে, এবার সাধারণ ৯টি শিক্ষা বোর্ডের অধীনে এসএসসি পরীক্ষায় অংশ নেন ১৪ লাখ ৯০ হাজার ১৪২ জন। মাদরাসা বোর্ডের অধীনে দাখিলে অংশ নেন ২ লাখ ৯৪ হাজার ৭২৬ জন। আর কারিগরি বোর্ডের অধীনে পরীক্ষার্থী ছিলেন ১ লাখ ৪৩ হাজার ৩১৩ জন।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 0, './ssc-result-20250707120827.webp', 52, NULL, '2025-07-07 16:50:33', '2025-07-07 16:50:33'),
(58, 'চট্টগ্রামে ওয়ারেন্টভুক্ত ৮ আসামি গ্রেফতার', 'চট্টগ্রামের চান্দগাঁও থানা এলাকা থেকে আট আসামিকে গ্রেফতার করেছে পুলিশ। শনিবার (৬ জুলাই) রাতে নগরীর বিভিন্ন স্থানে অভিযান চালিয়ে সাজাপ্রাপ্ত ও ওয়ারেন্টভুক্ত এই আট আসামিকে গ্রেফতার করা হয়।', '<p><br>চট্টগ্রামের চান্দগাঁও থানা এলাকা থেকে আট আসামিকে গ্রেফতার করেছে পুলিশ। শনিবার (৬ জুলাই) রাতে নগরীর বিভিন্ন স্থানে অভিযান চালিয়ে সাজাপ্রাপ্ত ও ওয়ারেন্টভুক্ত এই আট আসামিকে গ্রেফতার করা হয়।</p><p>তারা হলেন- চান্দগাঁওয়ের খাজা রোডের সাবান ঘাটার মোহাম্মদ জিয়াউর রহমান, উত্তর ফরিদা পাড়ার আয়েশা বেগম (৪৪), ফজল আমিন কলোনি ওরফে ফজু কলোনির শাহীন প্রকাশ আজাদ (২৩), মৌলভী পুকুর পাড়ের মো. দ্বীলের ছেলে মো. কুতুব উদ্দিন, মো. মানিক, মো. ইদ্রিস, ইকবাল হোসেন ও নুরুল আবছার (৪২)।</p><p><br>চান্দগাঁও থানার ভারপ্রাপ্ত কর্মকর্তা (ওসি) মো. আফতাব উদ্দিন জানান, অভিযানে মোট আট আসামিকে গ্রেফতার করা হয়েছে। পরে তাদের আইনি প্রক্রিয়ার মাধ্যমে আদালতে পাঠানো হয়েছে।</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 0, './05.webp', 53, NULL, '2025-07-07 16:54:17', '2025-07-07 16:54:17'),
(59, 'জুলাই আন্দোলনের হত্যা মামলা: সাবেক এমপি ফজলে করিম ট্রাইব্যুনালে', 'জুলাই অভ্যুত্থানের হত্যা মামলায় চট্টগ্রাম-৬ আসনের সাবেক এমপি এ বি এম ফজলে করিম চৌধুরীকে আন্তর্জাতিক অপরাধ ট্রাইব্যুনালে হাজির করা হয়েছে।', '<p style=\"-webkit-text-stroke-width:0px;color:rgb(68, 68, 68);font-family:Verdana, Arial, Helvetica, sans-serif;font-size:14px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">&nbsp;</p><p style=\"-webkit-text-stroke-width:0px;color:rgb(68, 68, 68);font-family:Verdana, Arial, Helvetica, sans-serif;font-size:14px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">জুলাই অভ্যুত্থানের হত্যা মামলায় চট্টগ্রাম-৬ আসনের সাবেক এমপি এ বি এম ফজলে করিম চৌধুরীকে আন্তর্জাতিক অপরাধ ট্রাইব্যুনালে হাজির করা হয়েছে।</p><p style=\"-webkit-text-stroke-width:0px;color:rgb(68, 68, 68);font-family:Verdana, Arial, Helvetica, sans-serif;font-size:14px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">সোমবার (৭ জুলাই) সকালে প্রিজনভ্যানে করে কারাগার থেকে ট্রাইব্যুনালে তাকে হাজির করা হয়। আন্তর্জাতিক অপরাধ ট্রাইব্যুনালে তার তদন্তের অগ্রগতির বিষয়ে শুনানি হওয়ার কথা রয়েছে।</p><p style=\"-webkit-text-stroke-width:0px;color:rgb(68, 68, 68);font-family:Verdana, Arial, Helvetica, sans-serif;font-size:14px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">এর আগে গত ১৬ ফেব্রুয়ারি জুলাই-আগস্ট গণহত্যার মামলায় এ বি এম ফজলে করিম চৌধুরীকে কারাগারে পাঠানোর নির্দেশ দেন আন্তর্জাতিক অপরাধ ট্রাইব্যুনাল।</p><p style=\"-webkit-text-stroke-width:0px;color:rgb(68, 68, 68);font-family:Verdana, Arial, Helvetica, sans-serif;font-size:14px;font-style:normal;font-variant-caps:normal;font-variant-ligatures:normal;font-weight:400;letter-spacing:normal;orphans:2;text-align:start;text-decoration-color:initial;text-decoration-style:initial;text-decoration-thickness:initial;text-indent:0px;text-transform:none;white-space:normal;widows:2;word-spacing:0px;\">সেদিন প্রসিকিউশনের পক্ষে প্রসিকিউটর আব্দুল্লাহ আল নোমান তাকে কারাগারে পাঠানোর আবেদন করেন। এসময় উপস্থিত ছিলেন প্রসিকিউটর বিএম সুলতান মাহমুদ, গাজী মনোয়ার হোসেন তামিম, ব্যারিস্টার মইনুল করিম, তারেক আব্দুল্লাহ ও সাইমুম রেজা।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 0, './fazle-20250707114112.webp', 55, NULL, '2025-07-07 16:56:11', '2025-07-07 16:56:11'),
(60, 'চট্টগ্রাম বন্দর তরফদারের রাহু মুক্ত', 'অবশেষে চট্টগ্রাম বন্দরের আলোচিত নিউমুরিং কনটেইনার টার্মিনাল (এনসিটি) পরিচালনাতে সাইফ পাওয়ারটেকের ‘তরফদার’ যুগের অবসান হয়েছে। আজ (সোমবার) থেকেই এনসিটি পরিচালনা শুরু করছে চিটাগাং ড্রাই ডক লিমিটেড (সিডিডিএল)।', '<p><br>অবশেষে চট্টগ্রাম বন্দরের আলোচিত নিউমুরিং কনটেইনার টার্মিনাল (এনসিটি) পরিচালনাতে সাইফ পাওয়ারটেকের ‘তরফদার’ যুগের অবসান হয়েছে। আজ (সোমবার) থেকেই এনসিটি পরিচালনা শুরু করছে চিটাগাং ড্রাই ডক লিমিটেড (সিডিডিএল)।</p><p>বন্দর সূত্র জানিয়েছে, ডাইরেক্ট প্রকিউরমেন্ট মেথডে (ডিপিএম) এনসিটি পরিচালনা করবে চিটাগাং ড্রাইডক লিমিটেড। চট্টগ্রাম বন্দর কর্তৃপক্ষের সচিব মো. ওমর ফারুক বিষয়টি নিশ্চিত করেছেন।<br>তিনি বলেন, নৌ-পরিবহন মন্ত্রণালয়ের নির্দেশনা অনুযায়ী সোমবার (৭ জুলাই) থেকে আগামী ৬ মাসের জন্য এনসিটি পরিচালনা করবে চিটাগাং ড্রাই ডক লিমিটেড। গত কয়েকদিন ধরেই সাইফ পাওয়ারটেক থেকে অপারেশনাল কাজ বুঝে নিচ্ছে ড্রাই ডকের একটি টিম।<br>চট্টগ্রাম বন্দরের এনসিটি টার্মিনালটি গত ১৭ বছর ধরে বেসরকারি প্রতিষ্ঠান দিয়ে পরিচালিত হয়ে আসছে। টার্মিনালটি বর্তমানে পরিচালনা করছে সাইফ পাওয়ারটেক লিমিটেড। প্রতিষ্ঠানটির ব্যবস্থাপনা পরিচালক তরফদার রুহুল আমীন। রোববার (৬ জুলাই) তাদের সঙ্গে বন্দর কর্তৃপক্ষের চুক্তির মেয়াদ শেষ হয়েছে। এখন টার্মিনালটি নিজস্ব ব্যবস্থাপনায় পরিচালিত হবে। এরইমধ্যে এনসিটি পরিচালনায় ৬ মাসের জন্য ৪২ কোটি টাকা ব্যয় অনুমোদন দিয়েছে মন্ত্রণালয়।</p><p>এনসিটি চট্টগ্রাম বন্দরের সবচেয়ে বড় টার্মিনাল। টার্মিনালটিতে পাঁচটি জেটি রয়েছে। এতে চারটি সমুদ্রগ্রামী জাহাজ এবং একটি অভ্যন্তরীণ নৌপথে চলাচলকারী জাহাজ বার্থিং করতে পারে। ২০২৪ সালে চট্টগ্রাম বন্দর ৩২ লাখ ৭৫ হাজার ৬২৭ টিইইউস কনটেইনার হ্যান্ডলিং করে। যার মধ্যে ১২ লাখ ৮১ হাজার টিইইউস কনটেইনার হ্যান্ডলিং হয়েছে এনসিটিতে। যা বন্দরের মোট কনটেইনার হ্যান্ডলিংয়ের ৪৪ শতাংশ।</p><p>বিগত আওয়ামী লীগ আমলে এনসিটি পরিচালনার ভার সংযুক্ত আরব আমিরাতের ডিপি ওয়ার্ল্ডকে দেওয়ার প্রক্রিয়া শুরু হয়। অন্তবর্তী সরকারও ডিপি ওয়ার্ল্ডকে এনসিটি পরিচালনার ভার দেওয়ার ব্যাপারে কার্যক্রম এগিয়ে নেয়। বিষয়টি নিয়ে আগামী নভেম্বরে চুক্তি হওয়ার আশা রয়েছে।</p>', 'published', 4, 'Botble\\Member\\Models\\Member', 1, './image-279600-1581996160.webp', 70, NULL, '2025-07-07 17:00:30', '2025-07-07 17:00:30'),
(61, 'জুলাই গণহত্যা : শেখ হাসিনার বিরুদ্ধে অভিযোগ গঠনের আদেশ ১০ জুলাই', 'জুলাই-আগস্টে গণহত্যার ঘটনায় মানবতাবিরোধী অপরাধের মামলায় পলাতক সাবেক প্রধানমন্ত্রী শেখ হাসিনা, সাবেক স্বরাষ্ট্রমন্ত্রী আসাদুজ্জামান খান কামাল ও সাবেক পুলিশ প্রধান (আইজিপি) চৌধুরী আবদুল্লাহ আল মামুনের বিরুদ্ধে অভিযোগ গঠনের বিষয়ে আগামী ১০ জুলাই আদেশ দেবেন ট্রাইব্যুনাল।', '<p><br>জুলাই-আগস্টে গণহত্যার ঘটনায় মানবতাবিরোধী অপরাধের মামলায় পলাতক সাবেক প্রধানমন্ত্রী শেখ হাসিনা, সাবেক স্বরাষ্ট্রমন্ত্রী আসাদুজ্জামান খান কামাল ও সাবেক পুলিশ প্রধান (আইজিপি) চৌধুরী আবদুল্লাহ আল মামুনের বিরুদ্ধে অভিযোগ গঠনের বিষয়ে আগামী ১০ জুলাই আদেশ দেবেন ট্রাইব্যুনাল।</p><p><br>সোমবার (৭ জুলাই) আন্তর্জাতিক অপরাধ ট্রাইব্যুনালের চেয়ারম্যান বিচারপতি মো. গোলাম মর্তুজা মজুমদারের নেতৃত্বে তিন সদস্যের ট্রাইব্যুনাল-১ আদেশের জন্য এদিন ধার্য করেন।</p><p>আদালতে পলাতক সাবেক প্রধানমন্ত্রী শেখ হাসিনা, সাবেক স্বরাষ্ট্রমন্ত্রী আসাদুজ্জামান খান কামালের পক্ষে শুনানি করেন রাষ্ট্রনিযুক্ত আইনজীবী আমির হোসেন।</p><p><br>এর আগে জুলাই-আগস্টে গণহত্যার ঘটনায় মানবতাবিরোধী অপরাধের মামলায় পলাতক সাবেক প্রধানমন্ত্রী শেখ হাসিনা, সাবেক স্বরাষ্ট্রমন্ত্রী আসাদুজ্জামান খান কামাল ও সাবেক পুলিশ প্রধান চৌধুরী আবদুল্লাহ আল মামুনের বিরুদ্ধে অভিযোগ গঠনের শুনানির জন্য ১ জুলাই দিন নির্ধারণ করেন ট্রাইব্যুনাল।</p><p><br>আন্তর্জাতিক অপরাধ ট্রাইব্যুনালের চেয়ারম্যান বিচারপতি মো. গোলাম মর্তুজা মজুমদারের নেতৃত্বে তিন সদস্যের ট্রাইব্যুনাল এ আদেশ দেন।</p><p>গত ১৬ জুন শেখ হাসিনা ও খান আসাদুজ্জামান খান কামালকে এক সপ্তাহের মধ্যে হাজির হতে দুটি পত্রিকায় বিজ্ঞপ্তি প্রকাশের নির্দেশ দেন ট্রাইব্যুনাল এবং ২৪ জুন এই মামলার পরবর্তী শুনানির দিন ধার্য করা হয়। পরদিন ১৭ জুন শেখ হাসিনা ও আসাদুজ্জামান খান কামালকে আত্মসমর্পণের নির্দেশ দিয়ে নোটিশ জারি করে আন্তর্জাতিক অপরাধ ট্রাইব্যুনাল। পত্রিকায় এই বিজ্ঞপ্তি প্রকাশ করা হয়েছে। বিজ্ঞপ্তি প্রকাশের ৭ দিনের মধ্যে হাজির না হলে তাদের অনুপস্থিতিতে বিচারকাজ চলবে।</p><p>আন্তর্জাতিক অপরাধ ট্রাইব্যুনালের চেয়ারম্যান বিচারপতি মো. গোলাম মর্তুজা মজুমদারের নেতৃত্বে তিন সদস্যের ট্রাইব্যুনাল এ আদেশ দেন। মামলার আরেক আসামি সাবেক পুলিশ প্রধান চৌধুরী আবদুল্লাহ আল মামুন ট্রাইব্যুনালে হাজির ছিলেন। আদালতে প্রসিকিউশনের পক্ষে শুনানি করেন চিফ প্রসিকিউটর মোহাম্মদ তাজুল ইসলাম।</p><p>গত ১ জুন শেখ হাসিনাসহ ৩ জনের বিরুদ্ধে ৫টি অভিযোগ আমলে নেয় ট্রাইব্যুনাল। মামলার অপর দুই আসামি হলেন আসাদুজ্জামান খান কামাল এবং সাবেক পুলিশের মহাপরিদর্শক (আইজিপি) চৌধুরী মামুন। একইসঙ্গে এই মামলায় শেখ হাসিনা ও আসাদুজ্জামান কামালের বিরুদ্ধে নতুন করে গ্রেপ্তারি পরোয়ানা জারি করা হয়।</p><p>সেদিন আদালতে শেখ হাসিনাসহ তিন আসামির বিরুদ্ধে অভিযোগ পড়ে শোনান চিফ প্রসিকিউটর মোহাম্মদ তাজুল ইসলাম, প্রসিকিউটর আব্দুস সোবহান তরফদার, মিজানুল ইসলাম। যা সব গণমাধ্যমে সম্প্রচার করা যায়।</p><p>এর আগে মানবতা বিরোধী অপরাধের মামলায় সাবেক প্রধানমন্ত্রী শেখ হাসিনাকে প্রধান অভিযুক্ত করে আন্তর্জাতিক অপরাধ ট্রাইব্যুনালে আনুষ্ঠানিক অভিযোগ দাখিল করা হয়।</p><p>গত ১২ মে জুলাই-আগস্টের গণহত্যার ঘটনায় শেখ হাসিনার বিরুদ্ধে তদন্ত প্রতিবেদন দাখিল করেন তদন্ত সংস্থার কর্মকর্তারা। তদন্ত প্রতিবেদনে জুলাই গণহত্যার নির্দেশদাতা হিসেবে শেখ হাসিনার নাম উঠে এসেছে।</p><p>গত ১৮ ফেব্রুয়ারি জুলাই-আগস্টের গণহত্যার ঘটনায় শেখ হাসিনার বিরুদ্ধে তদন্ত ২০ এপ্রিলের মধ্যে শেষ করতে নির্দেশ দেন ট্রাইব্যুনাল। আন্তর্জাতিক অপরাধ ট্রাইব্যুনালের চেয়ারম্যান বিচারপতি মো. গোলাম মর্তুজা মজুমদারের নেতৃত্বে তিন সদস্যের ট্রাইব্যুনাল এ আদেশ দেন। প্রসিকিউশনের সময় আবেদনের পরিপ্রেক্ষিতে আদালত এ আদেশ দেন। ট্রাইব্যুনালে প্রসিকিউশনের পক্ষে শুনানি করেন অতিরিক্ত চিফ প্রসিকিউটর মিজানুল ইসলাম।</p><p>গত বছরের ১৭ ডিসেম্বর দুই মামলায় শেখ হাসিনা, ওবায়দুল কাদেরসহ ৪৬ জনের বিরুদ্ধে তদন্ত দুই মাসের মধ্যে শেষ করার নির্দেশ দেন ট্রাইব্যুনাল।</p><p>বৈষম্যবিরোধী ছাত্র আন্দোলনে নিরস্ত্র ছাত্র-জনতার ওপর গুলি, হত্যার নির্দেশদাতা ও পরিকল্পনাকারী হিসেবে সাবেক প্রধানমন্ত্রী শেখ হাসিনাসহ অভিযুক্তদের বিরুদ্ধে আন্তর্জাতিক অপরাধ ট্রাইব্যুনালে বিচার চলছে। ছাত্র-জনতার আন্দোলন ঠেকাতে আওয়ামী লীগ সরকার নির্বিচারে হত্যা চালায়। প্রায় দেড় হাজার মানুষ প্রাণ হারায় এই আন্দোলনে।</p>', 'published', NULL, 'Botble\\Member\\Models\\Member', 0, './33.webp', 53, NULL, '2025-07-07 17:48:05', '2025-07-09 02:13:47'),
(62, 'মিয়ানমারে তুমুল সংঘর্ষ, পালাচ্ছেন হাজার হাজার মানুষ', '', '<p>&nbsp;<br><strong>মিয়ানমারে সামরিক জান্তা-বিরোধী সশস্ত্র দুটি গোষ্ঠীর মাঝে তুমুল সংঘর্ষের ঘটনা ঘটেছে। চলমান এই সংঘর্ষে প্রাণ বাঁচাতে দেশটির হাজার হাজার শরণার্থী পালিয়ে প্রতিবেশী ভারতের উত্তর-পূর্বাঞ্চলীয় মিজোরাম রাজ্যে আশ্রয় নিয়েছেন। সোমবার ভারতীয় কর্তৃপক্ষের বরাত দিয়ে ব্রিটিশ বার্তা সংস্থা রয়টার্সের এক প্রতিবেদনে এই তথ্য জানানো হয়েছে</strong></p><p><br>ভারতের জ্যেষ্ঠ এক নিরাপত্তা কর্মকর্তা রয়টার্সকে বলেছেন, গত ২ জুলাই মিয়ানমারের উত্তর-পশ্চিমাঞ্চলীয় চিন রাজ্যের কৌশলগত বিভিন্ন এলাকার নিয়ন্ত্রণ নিয়ে প্রতিদ্বন্দ্বী দুই গোষ্ঠী চিন ন্যাশনাল ডিফেন্স ফোর্স (সিএনডিএফ) ও চিনল্যান্ড ডিফেন্স ফোর্স-হুয়ালংরাম (সিডিএফ-এইচ) মাঝে সংঘর্ষের সূত্রপাত হয়। সেদিন থেকেই চিন রাজ্যের হাজার হাজার শরণার্থী সীমান্ত পেরিয়ে মিজোরামে ঢুকতে শুরু করেন।</p><p>গণমাধ্যমের সঙ্গে কথা বলার অনুমতি না থাকায় নাম প্রকাশে অনিচ্ছুক ওই কর্মকর্তা বলেন, চিন রাজ্যে সংঘর্ষ শুরুর পর থেকে প্রায় ৪ হাজার শরণার্থী সীমান্ত পেরিয়ে মিজোরামে পাড়ি জমিয়েছেন<br>মিয়ানমারের চিন রাজ্যে প্রতিদ্বন্দ্বী গোষ্ঠীগুলোর নিয়ন্ত্রণ থাকা বিভিন্ন এলাকার সঙ্গে ভারতের মিজোরাম রাজ্যের সীমান্ত রয়েছে। মিজোরামের বাসিন্দাদের সঙ্গে মিয়ানমারের চিন জনগোষ্ঠীর জাতিগত সম্পর্ক রয়েছে। ২০২১ সালের ফেব্রুয়ারিতে সামরিক অভ্যুত্থানের মাধ্যমে মিয়ানমারে অং সান সু চি নেতৃত্বাধীন সরকারের পতনের পর থেকেই হাজার হাজার শরণার্থীকে আশ্রয় দিয়ে আসছে মিজোরাম।</p><shortcode>[featured-categories-posts category_id=\"10\" with_sidebar=\"yes\" background_color=\"#ecf0f1\" enable_lazy_loading=\"no\"][/featured-categories-posts]</shortcode><p>মিজোরামের স্বরাষ্ট্রমন্ত্রী কে সাপদাঙ্গা মিয়ানমারের নতুন শরণার্থীদের ওই রাজ্যে পৌঁছানোর তথ্য নিশ্চিত করেছেন। তবে মিয়ানমার থেকে আসা শরণার্থীদের সংখ্যা ৩ হাজার হতে পারে বলে জানিয়েছেন তিনি।<br>সাপদাঙ্গা বলেন, ‘‘চিন রাজ্যের এই সংঘর্ষ আমাদের নিয়ন্ত্রণের বাইরে। মানুষ চলে এসেছে এবং মানবিক দৃষ্টিকোণ থেকে আমরা তাদের পানি, খাদ্য ও আশ্রয় দিতে বাধ্য হয়েছি।’’</p><blockquote><p>আর ভারতীয় ওই নিরাপত্তা বলেছেন, রোববার রাত পর্যন্ত রাজ্যের চাম্পাই জেলার জোখাওথার ও সাইখুমফাই গ্রামে মোট ৩ হাজার ৯৮০ জন শরণার্থীকে নথিভুক্ত করা হয়েছে।</p></blockquote><p>তিনি বলেন, শরণার্থীদের এই সংখ্যা প্রাথমিক এবং ক্রমাগত তা পরিবর্তন হচ্ছে। শুরুতে অল্প-সংখ্যক মানুষ এসেছিলেন। তবে সংঘর্ষ তীব্র আকার ধারণ করায় ও সীমান্তের কাছাকাছি এলাকায় ছড়িয়ে পড়ায় আরও বেশিসংখ্যক মানুষ আসতে শুরু করেন।</p><p>&nbsp;</p><p>এই বিষয়ে জানতে মিয়ানমারের জান্তা সরকারের একজন মুখপাত্রকে টেলিফোন করা হলেও তিনি সাড়া দেননি বলে জানিয়েছে রয়টার্স।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 0, './myanmar-20250707180600-1.webp', 73, NULL, '2025-07-07 22:37:16', '2025-07-07 22:46:55'),
(63, 'চট্টগ্রামে তিন থানায় ওসি পদে রদবদল, পটিয়ার দায়িত্বে নুরুজ্জামান', 'চট্টগ্রাম জেলার বোয়ালখালী ও চন্দনাইশ থানার ভারপ্রাপ্ত কর্মকর্তা (ওসি) পদে রদবদল আনা হয়েছে। পাশাপাশি পটিয়া থানায় নতুন ওসি হিসেবে দায়িত্ব পেয়েছেন মো. নুরুজ্জামান।', '<p><br>চট্টগ্রাম জেলার বোয়ালখালী ও চন্দনাইশ থানার ভারপ্রাপ্ত কর্মকর্তা (ওসি) পদে রদবদল আনা হয়েছে। পাশাপাশি পটিয়া থানায় নতুন ওসি হিসেবে দায়িত্ব পেয়েছেন মো. নুরুজ্জামান।<br>সোমবার (৭ জুলাই) জেলা পুলিশ সুপার মো. সাইফুল ইসলাম সানতু স্বাক্ষরিত এক প্রজ্ঞাপনে এ বদলির আদেশ জারি করা হয়।</p><p>প্রজ্ঞাপনে বলা হয়, বোয়ালখালী থানার ওসি গোলাম সারোয়ারকে চন্দনাইশ থানায় বদলি করা হয়েছে। অপরদিকে, চন্দনাইশ থানার ওসি নুরুজ্জামানকে পটিয়া থানায় বদলি করা হয়েছে।</p><p><br>সম্প্রতি পটিয়া এলাকায় পুলিশ ও বৈষম্যবিরোধী ছাত্র আন্দোলনের নেতাকর্মীদের মধ্যে সংঘর্ষ হয়। ওই সময় গ্রেপ্তার করা হয় ছাত্রলীগের রাঙামাটি জেলা সভাপতিকে। সংঘর্ষ ও গ্রেপ্তারের ঘটনায় উত্তপ্ত হয়ে ওঠে পরিস্থিতি। চট্টগ্রাম-কক্সবাজার মহাসড়কে দিনভর অবরোধ চলায় জনসাধারণের দুর্ভোগ চরমে পৌঁছায়</p><p><br>ঘটনার পরপরই পটিয়া থানার তৎকালীন ওসি জাহেদ নুরকে প্রত্যাহার করে নেওয়া হয়। তার জায়গায় দায়িত্ব দেওয়া হয়েছে চন্দনাই-শ থানা থেকে বদলি হওয়া ওসি নুরুজ্জামানকে।</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, './26-1.webp', 50, NULL, '2025-07-08 00:17:02', '2025-07-08 00:17:02');
INSERT INTO `posts` (`id`, `name`, `description`, `content`, `status`, `author_id`, `author_type`, `is_featured`, `image`, `views`, `format_type`, `created_at`, `updated_at`) VALUES
(64, 'কক্সবাজারে সমুদ্রে নেমে চবি শিক্ষার্থীর মৃত্যু, নিখোঁজ ২', 'কক্সবাজারে সমুদ্রে গোসল করতে নেমে কে এম সাদনান রহমান সাবাব (২১) নামে এক বিশ্ববিদ্যালয় শিক্ষার্থীর মৃত্যু হয়েছে। একই ঘটনায় নিখোঁজ রয়েছেন আরও দুই শিক্ষার্থী।', '<p><br><br>কক্সবাজারে সমুদ্রে গোসল করতে নেমে কে এম সাদনান রহমান সাবাব (২১) নামে এক বিশ্ববিদ্যালয় শিক্ষার্থীর মৃত্যু হয়েছে। একই ঘটনায় নিখোঁজ রয়েছেন আরও দুই শিক্ষার্থী।</p><p><br>মঙ্গলবার (৮ জুলাই) হিমছড়ি সমুদ্র সৈকত পয়েন্টে এ ঘটনা ঘটে। গোসলের এক পর্যায়ে স্রোতের টানে তিনজনই ভেসে যান বলে প্রাথমিকভাবে জানা গেছে।</p><p>আক্রান্ত তিনজন চট্টগ্রাম বিশ্ববিদ্যালয়ের ডেভেলপমেন্ট স্টাডিজ বিভাগের ২০২৩-২৪ শিক্ষাবর্ষের শিক্ষার্থী</p><p><br>মারা যাওয়া শিক্ষার্থী সাবাব ঢাকার মিরপুর এলাকার কে এম আনিসুর রহমানের ছেলে। এখনো যে দুজন নিখোঁজ রয়েছেন তারা হলেন, বগুড়া জেলার রফিকুল ইসলামের ছেলে আসিফ আহমেদ (২২), একই এলাকার আমিনুল ইসলামের ছেলে অরিত্র (২২)।</p><p>চবির সহকারী প্রক্টর ও ডেভেলপমেন্ট স্টাডিজ বিভাগের অধ্যাপক সাঈদ বিন কামাল চৌধুরী বলেন, গতকাল রাতে প্রথম বর্ষের চার শিক্ষার্থী কক্সবাজারে ঘুরতে যায়। তারা নিজ উদ্যোগে সেখানে গিয়েছেন। এর মধ্যে একজনের মরদেহ উদ্ধার করেছে স্থানীয় জেলেরা। বাকি দু’জন নিখোঁজ। আমরা সেখানকার পুলিশের সঙ্গে যোগাযোগ করেছি। তাদের পরিবারকে জানানো হয়েছে। এছাড়া বিশ্ববিদ্যালয় থেকে আমাদের বিভাগের সিনিয়র কয়েকজন কক্সবাজারের উদ্দেশ্যে রওনা দিয়েছেন।</p><p>হিমছড়ি পুলিশ ফাঁড়ির ইনচার্জ (আইসি) সুমনাথ বসু বলেন, চার বন্ধু মিলে হিমছড়ি পয়েন্টে ঘুরতে আসেন। তিন বন্ধু এক সঙ্গে গোসল করতে নামেন। গোসলের এক পর্যায়ে স্রোতের টানে তারা ভেসে যান। একজনের মরদেহ পাওয়া গেলেও এখনো দুইজন নিখোঁজ আছেন। ফায়ার সার্ভিস ও সি সেইফ লাইফ গার্ড উদ্ধার কার্যক্রম চালাচ্ছে।&nbsp;</p>', 'published', 1, 'Botble\\Member\\Models\\Member', 1, './04-1.webp', 59, NULL, '2025-07-08 18:45:25', '2025-07-08 18:46:16');
INSERT INTO `posts` (`id`, `name`, `description`, `content`, `status`, `author_id`, `author_type`, `is_featured`, `image`, `views`, `format_type`, `created_at`, `updated_at`) VALUES
(65, 'প্রকৌশলী নুরুল হত্যা মামলায় মা ও দুই ভাই গ্রেপ্তার', 'রাউজান থানার প্রকৌশলী নুরুল আলম বকুল হত্যা মামলায় মা ও দুই ভাইকে গ্রেপ্তারকে করেছে র‌্যাব-৭।', '<p>&nbsp;</p><p><span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">রাউজান</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">থানার</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">প্রকৌশলী</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">নুরুল</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">আলম</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">বকুল</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">হত্যা</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">মামলায়</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">মা</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">ও</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">দুই</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">ভাইকে</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">গ্রেপ্তারকে</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">করেছে</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">র</span> <span style=\"font-family:\'Times New Roman\', serif;font-size:18pt;line-height:115%;\">‌</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">্যাব</span> <span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">-</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">৭।</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span></p><p><span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">গ্রেপ্তাররা</span>&nbsp;<span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">হলেন</span> <span style=\"font-family:SutonnyMJ;font-size:18pt;line-height:115%;\">,&nbsp;</span> <span style=\"font-family:\'Nirmala UI\', sans-serif;font-size:18pt;line-height:115%;\">রাউজান</span>&nbsp;<span style=