INSERT INTO `posts_translations` (`lang_code`, `posts_id`, `name`, `description`, `content`) VALUES
('en_US', 82, 'চট্টগ্রামেভারী বৃষ্টিতে জলাবদ্ধতা, ভোগান্তিতে নগরবাসী', 'টানাভারী বৃষ্টির কারণে চট্টগ্রাম নগরের বেশ কয়েকটি এলাকায়জলাবদ্ধতা সৃষ্টি হয়েছে। বুধবার রাত থেকে শুরুহওয়া মুষলধারে বৃষ্টির ফলে বুধবার সকালথেকে নগরের বিভিন্ন এলাকায় রাস্তাঘাটে পানি জমে যায়, যা যান চলাচল ওজনজীবনে ভোগান্তি তৈরি করেছে।', '<p><span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">টানাভারী</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">বৃষ্টির</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">কারণে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">চট্টগ্রাম</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">নগরের</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">বেশ</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">কয়েকটি</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">এলাকায়জলাবদ্ধতা</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">সৃষ্টি</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">হয়েছে।</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">বুধবার</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">রাত</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">থেকে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">শুরুহওয়া</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">মুষলধারে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">বৃষ্টির</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">ফলে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">বুধবার</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">সকালথেকে</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">নগরের</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">বিভিন্ন</span> <span style=\"font-family:&quot;Nirmala UI&quot;,sans-serif;\">এল